// E-1b (Escenarios.pdf, 17 de agosto): "Se puede crear un tipo nuevo con su nombre, familia y sus
// campos (importe, mensualidad, plazo, mes). Se guarda en el catálogo, aparece en la lista y se
// valida contra las mismas comprobaciones que los once tipos de fábrica." `mes` ancla siempre la
// decisión (sin mes no hay dónde situarla en el horizonte) — los otros tres son los que elige quien
// crea el tipo. En el motor y el esquema todos comparten el tipo `propio`; `definicionId` distingue
// cuál de los tipos propios guardados es cada decisión.
const ESCENARIO_MOTOR_CUSTOM_FIELD_DEFS = Object.freeze({
  importe: { key: "importe", kind: "money", label: "Importe" },
  mensualidad: { key: "mensualidad", kind: "money", label: "Mensualidad" },
  plazo: { key: "plazo", kind: "int", label: "Plazo (meses)", min: 1, max: 480 },
});

function loadEscenarioMotorCustomTypes() {
  try {
    const parsed = JSON.parse(storageGet(storageKey("escenario-motor-custom-types"), "[]"));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveEscenarioMotorCustomTypesList(list) {
  storageSet(storageKey("escenario-motor-custom-types"), JSON.stringify(list));
}

// Convierte una definición guardada en un objeto con la misma forma que un tipo de fábrica —
// `campos`/`mes`/`params`/`titulo`/`detalle`/`importeTexto` — para que el resto del formulario
// (`escenarioMotorFieldHtml`, `escenarioMotorEffectiveValues`…) no distinga entre ambos. `id` es la
// clave de selección en el formulario (`propio_<definicionId>`, única por definición); `engineTipo`
// es el tipo real que se manda al motor y al esquema (siempre `"propio"`).
function escenarioMotorCustomTypeEntry(custom) {
  const campos = (custom.campos || [])
    .map((key) => ESCENARIO_MOTOR_CUSTOM_FIELD_DEFS[key])
    .filter(Boolean)
    .concat([{ key: "mes", kind: "month", label: "Mes" }]);
  return {
    id: `propio_${custom.id}`,
    engineTipo: "propio",
    definicionId: custom.id,
    // Mockup: los tipos propios se listan aparte («Propios · lo que no encaja arriba»), no
    // mezclados en Deuda/Vida — `familia` queda en la definición solo como metadato informativo.
    grupo: "Propios",
    familia: custom.familia,
    label: custom.label,
    ayuda: "Tipo propio: se resuelve como golpe único (importe) y/o cuota recurrente (mensualidad durante el plazo) desde el mes elegido — la misma comprobación de contrato que los once de fábrica.",
    campos,
    mes: (v) => v.mes,
    params: (v) => {
      const params = { definicionId: custom.id, nombre: custom.label, mes: v.mes };
      if ((custom.campos || []).includes("importe") && v.importe !== undefined) params.importe = v.importe;
      if ((custom.campos || []).includes("mensualidad") && v.mensualidad !== undefined) params.mensualidad = v.mensualidad;
      if ((custom.campos || []).includes("plazo") && v.plazo !== undefined) params.plazo = escenarioMotorInt(v.plazo);
      return params;
    },
    titulo: () => escenarioMotorTrim(custom.label),
    detalle: (d) => {
      const parts = [];
      if (d.params?.importe !== undefined) parts.push(money(d.params.importe, true));
      if (d.params?.mensualidad !== undefined) parts.push(`${money(d.params.mensualidad, true)}/mes${d.params.plazo ? ` · ${d.params.plazo} meses` : ""}`);
      return parts.join(" · ") || "—";
    },
    importeTexto: (d) => (d.params?.importe !== undefined
      ? money(d.params.importe, true)
      : d.params?.mensualidad !== undefined
        ? `${money(d.params.mensualidad, true)}/mes`
        : "—"),
  };
}

function escenarioMotorCustomTypeEntries() {
  return loadEscenarioMotorCustomTypes().map(escenarioMotorCustomTypeEntry);
}

function escenarioMotorAllTypeEntries() {
  return ESCENARIO_MOTOR_TYPES.concat(escenarioMotorCustomTypeEntries());
}

let escenarioMotorDraftTipo = ESCENARIO_MOTOR_TYPES[0].id;
let escenarioMotorDraftValues = {};

function escenarioMotorTypeById(tipo) {
  return ESCENARIO_MOTOR_TYPES.find((item) => item.id === tipo) || null;
}

// A diferencia de `escenarioMotorTypeById` (solo catálogo de fábrica, el que ya reutilizaba Deuda ›
// Comparar), esta también busca entre los tipos propios — hace falta donde `escenarioMotorDraftTipo`
// puede llevar una clave `propio_<id>` (el formulario de decisión), no donde siempre es uno de
// fábrica (D-5).
function escenarioMotorTypeOrCustomById(tipo) {
  return escenarioMotorAllTypeEntries().find((item) => item.id === tipo) || null;
}

// Las decisiones guardadas (o ya añadidas a la simulación) de un tipo propio llevan `tipo: "propio"`
// — no basta con `escenarioMotorTypeById` para reconstruir cuál definición era, hace falta
// `params.definicionId`. Si la definición se hubiera borrado (no hay manera de borrarlas todavía,
// pero el código no lo da por hecho) se degrada a un texto honesto en vez de romper el render.
function escenarioMotorResolveType(decision) {
  if (decision?.tipo !== "propio") return escenarioMotorTypeById(decision?.tipo);
  const custom = loadEscenarioMotorCustomTypes().find((item) => item.id === decision.params?.definicionId);
  if (custom) return escenarioMotorCustomTypeEntry(custom);
  return {
    id: "propio",
    grupo: "Propios",
    label: "Tipo propio eliminado",
    titulo: () => decision.titulo || "Tipo propio eliminado",
    detalle: () => "",
    importeTexto: () => "—",
  };
}

function escenarioMotorVisibleFields(type, values) {
  if (!type) return [];
  return type.campos.filter((field) => (typeof field.visibleSi === "function" ? field.visibleSi(values) : true));
}

// Los campos ocultos por `visibleSi` no cuentan: si la compra no está financiada, sus cuatro
// campos de financiación no entran en los params aunque el usuario los hubiera rellenado antes.
function escenarioMotorEffectiveValues(type, values) {
  const visible = new Set(escenarioMotorVisibleFields(type, values).map((field) => field.key));
  const effective = {};
  Object.keys(values).forEach((key) => {
    if (visible.has(key)) effective[key] = values[key];
  });
  return effective;
}

function escenarioMotorFieldElementId(key, idPrefix = "escenarioMotorField") {
  return `${idPrefix}_${key}`;
}

function escenarioMotorMonthOptionsHtml(months, selected, placeholder) {
  const head = placeholder ? `<option value="">${escapeHtml(placeholder)}</option>` : "";
  return head + months
    .map((month) => `<option value="${escapeHtml(month.monthKey)}"${month.monthKey === selected ? " selected" : ""}>${escapeHtml(month.month)}</option>`)
    .join("");
}

// D-5 · `idPrefix`/`dataAttr` dejan reutilizar el mismo dibujado de campo (y su `params()`/`mes()`
// del catálogo) desde el selector de modo de Deuda › Comparar sin generar los mismos `id` que el
// formulario real de «Escenario · simular» — ambas pantallas conviven en el DOM a la vez.
function escenarioMotorFieldControlHtml(field, months, values, { idPrefix = "escenarioMotorField", dataAttr = "data-escenario-motor-field" } = {}) {
  const id = escenarioMotorFieldElementId(field.key, idPrefix);
  const attrs = `id="${id}" ${dataAttr}="${escapeHtml(field.key)}"`;
  const value = values[field.key];
  const numberAttrs = `${field.min !== undefined ? ` min="${field.min}"` : ""}${field.max !== undefined ? ` max="${field.max}"` : ""}`;
  switch (field.kind) {
    case "debt":
    case "debtMulti": {
      const debts = escenarioMotorDebtOptions().filter(field.filtro || (() => true));
      if (!debts.length) return `<select ${attrs}${field.kind === "debtMulti" ? " multiple size=\"4\"" : ""}><option value="">${escapeHtml(field.vacio || "Sin deudas vivas")}</option></select>`;
      const selected = field.kind === "debtMulti" ? new Set(Array.isArray(value) ? value : []) : new Set(value ? [value] : []);
      const options = debts
        .map((contract) => `<option value="${escapeHtml(contract.id)}"${selected.has(contract.id) ? " selected" : ""}>${escapeHtml(escenarioMotorDebtLabel(contract))} · ${money(contract.currentPrincipal, true)}</option>`)
        .join("");
      return `<select ${attrs}${field.kind === "debtMulti" ? ` multiple size="${Math.min(6, Math.max(3, debts.length))}"` : ""}>${options}</select>`;
    }
    case "month":
      return `<select ${attrs}>${escenarioMotorMonthOptionsHtml(months, value, null)}</select>`;
    case "monthOptional":
      return `<select ${attrs}>${escenarioMotorMonthOptionsHtml(months, value, "Hasta el final del horizonte")}</select>`;
    case "select":
      return `<select ${attrs}>${(field.opciones || [])
        .map(([optionValue, optionLabel]) => `<option value="${escapeHtml(optionValue)}"${optionValue === value ? " selected" : ""}>${escapeHtml(optionLabel)}</option>`)
        .join("")}</select>`;
    case "checkbox":
      return `<input ${attrs} type="checkbox"${value === true ? " checked" : ""} />`;
    case "money":
      return `<input ${attrs} type="number" min="0.01" step="0.01" placeholder="€" value="${value === undefined ? "" : escapeHtml(String(value))}" />`;
    case "pct":
      return `<input ${attrs} type="number" step="0.01" placeholder="%" value="${value === undefined ? "" : escapeHtml(String(value))}"${numberAttrs} />`;
    case "int":
      return `<input ${attrs} type="number" step="1"${numberAttrs} value="${value === undefined ? "" : escapeHtml(String(value))}" />`;
    case "number":
      return `<input ${attrs} type="number" step="0.01" placeholder="€" value="${value === undefined ? "" : escapeHtml(String(value))}" />`;
    case "date":
      return `<input ${attrs} type="date" value="${value === undefined ? "" : escapeHtml(String(value))}" />`;
    default:
      return `<input ${attrs} type="text" maxlength="60" value="${value === undefined ? "" : escapeHtml(String(value))}" />`;
  }
}

function escenarioMotorFieldHtml(field, months, values, options = {}) {
  const { idPrefix = "escenarioMotorField", dataAttr = "data-escenario-motor-field", wrapAttr = "data-escenario-motor-field-wrap" } = options;
  const control = escenarioMotorFieldControlHtml(field, months, values, { idPrefix, dataAttr });
  const hint = field.ayuda ? `<small class="e19-kpi-note">${escapeHtml(field.ayuda)}</small>` : "";
  const classes = ["escenario-motor-field"];
  // Los selectores de deuda llevan entidad, tipo e importe: a media columna se recortan justo en la
  // parte que distingue una deuda de otra, así que ocupan la fila entera.
  if (field.ancho || field.kind === "debt" || field.kind === "debtMulti") classes.push("escenario-motor-field-wide");
  if (field.kind === "checkbox") classes.push("escenario-motor-field-check");
  const hidden = typeof field.visibleSi === "function" && !field.visibleSi(values) ? " hidden" : "";
  const body = field.kind === "checkbox"
    ? `${control}<span>${escapeHtml(field.label)}</span>${hint}`
    : `<span>${escapeHtml(field.label)}</span>${control}${hint}`;
  return `<label class="${classes.join(" ")}" ${wrapAttr}="${escapeHtml(field.key)}"${hidden}>${body}</label>`;
}

function escenarioMotorReadFieldValue(field, element) {
  if (!element) return undefined;
  if (field.kind === "checkbox") return element.checked;
  if (field.kind === "debtMulti") return Array.from(element.selectedOptions || []).map((option) => option.value).filter(Boolean);
  const raw = String(element.value ?? "").trim();
  if (raw === "") return undefined;
  if (["money", "number", "int", "pct"].includes(field.kind)) {
    const parsed = Number(raw);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return raw;
}

function escenarioMotorSyncDraftValues() {
  const type = escenarioMotorTypeOrCustomById(escenarioMotorDraftTipo);
  const container = qs("escenarioMotorFields");
  if (!type || !container) return;
  type.campos.forEach((field) => {
    const element = qs(escenarioMotorFieldElementId(field.key));
    if (!element) return;
    escenarioMotorDraftValues[field.key] = escenarioMotorReadFieldValue(field, element);
  });
}

function escenarioMotorSyncFieldVisibility() {
  const type = escenarioMotorTypeOrCustomById(escenarioMotorDraftTipo);
  const container = qs("escenarioMotorFields");
  if (!type || !container) return;
  type.campos.forEach((field) => {
    if (typeof field.visibleSi !== "function") return;
    const wrap = container.querySelector(`[data-escenario-motor-field-wrap="${field.key}"]`);
    if (wrap) wrap.hidden = !field.visibleSi(escenarioMotorDraftValues);
  });
}

// Rebusca opciones (deudas y meses) en cada render para que no queden obsoletas, pero se abstiene
// si el usuario tiene el foco dentro del formulario: reconstruirlo bajo sus dedos le haría perder
// el cursor a media escritura.
function renderEscenarioMotorForm(baseInput) {
  const typeSelect = qs("escenarioMotorType");
  const container = qs("escenarioMotorFields");
  const hint = qs("escenarioMotorTypeHint");
  if (!typeSelect || !container) return;

  const allTypes = escenarioMotorAllTypeEntries();
  // E-1b: se reconstruye también cuando cambia el número de tipos propios guardados (crear uno
  // nuevo), no solo la primera vez — `childElementCount` por sí solo no lo detectaría.
  if (!typeSelect.childElementCount || typeSelect.dataset.typeCount !== String(allTypes.length)) {
    const grupos = [];
    allTypes.forEach((type) => {
      const grupo = grupos.find((item) => item.nombre === type.grupo);
      if (grupo) grupo.tipos.push(type);
      else grupos.push({ nombre: type.grupo, tipos: [type] });
    });
    typeSelect.innerHTML = grupos
      .map((grupo) => `<optgroup label="${escapeHtml(grupo.nombre)}">${grupo.tipos
        .map((type) => `<option value="${escapeHtml(type.id)}">${escapeHtml(type.label)}</option>`)
        .join("")}</optgroup>`)
      .join("");
    typeSelect.dataset.typeCount = String(allTypes.length);
  }
  typeSelect.value = escenarioMotorDraftTipo;

  const type = escenarioMotorTypeOrCustomById(escenarioMotorDraftTipo);
  if (hint) hint.textContent = type?.ayuda || "";
  if (!type) return;

  if (container.contains(document.activeElement)) {
    escenarioMotorSyncFieldVisibility();
    return;
  }
  escenarioMotorSyncDraftValues();
  container.innerHTML = type.campos
    .map((field) => escenarioMotorFieldHtml(field, baseInput.months, escenarioMotorDraftValues))
    .join("");
  container.dataset.tipo = type.id;
  // Los desplegables no admiten «sin valor»: lo que muestran ya es el valor efectivo, así que se
  // vuelca al borrador para que `params()` vea lo mismo que el usuario.
  escenarioMotorSyncDraftValues();
  escenarioMotorSyncFieldVisibility();
}

function escenarioMotorShowFormErrors(messages) {
  const box = qs("escenarioMotorFormError");
  const list = qs("escenarioMotorFormErrorList");
  if (!box || !list) return;
  if (!messages.length) {
    box.hidden = true;
    list.innerHTML = "";
    return;
  }
  box.hidden = false;
  list.innerHTML = messages.map((message) => `<li>${escapeHtml(message)}</li>`).join("");
}

// Traduce el `path` que devuelve el contrato ($.params.importe) al rótulo del campo, para que el
// mensaje señale el control que hay que rellenar en vez de un nombre técnico.
function escenarioMotorIssueMessage(issue, type) {
  const key = String(issue.path || "").split(".").pop();
  const field = type.campos.find((item) => item.key === key || (item.key === "mes" && key === "mesManual"));
  return field ? `${field.label}: ${issue.message}` : issue.message;
}

// Traduce los códigos de rechazo reales del motor (canonical-scenario-engine.js) a texto legible.
// Ningún resultado se inventa aquí: solo se etiqueta lo que el motor ya ha decidido.
function escenarioMotorResultInfo(resultado) {
  const table = {
    aplicada: { text: "Aplicada", badge: "e19-badge-success" },
    "guardarril-incumplido": { text: "Rechazada: rompe el saldo mínimo indicado", badge: "e19-badge-danger" },
    "conflicto-bloqueante": { text: "Rechazada: la deuda ya la afecta otra decisión de este escenario", badge: "e19-badge-danger" },
    "deuda-ya-cerrada": { text: "Rechazada: la deuda ya está cerrada", badge: "e19-badge-danger" },
    "deuda-desconocida": { text: "Rechazada: deuda no encontrada", badge: "e19-badge-danger" },
    "sin-objetivo": { text: "Rechazada: falta indicar la deuda", badge: "e19-badge-danger" },
    "sin-mes-viable": { text: "Rechazada: ningún mes del horizonte la sostiene", badge: "e19-badge-danger" },
    "tipo-no-soportado-aun": { text: "Rechazada: el motor no resuelve este tipo todavía", badge: "e19-badge-danger" },
    inactiva: { text: "Desactivada", badge: "e19-badge-neutral" },
  };
  return table[resultado] || { text: resultado, badge: "e19-badge-neutral" };
}

// `resultado: "rechazada"` viene siempre acompañado de un `motivo` del propio aplicador; sin él, el
// texto genérico sería inútil para decidir qué corregir.
function escenarioMotorRejectionInfo(resultado) {
  if (resultado?.resultado !== "rechazada") return null;
  const table = {
    "deuda-no-suspendida": "Rechazada: esa deuda no tiene los pagos suspendidos",
    "sin-objetivo": "Rechazada: falta indicar la deuda",
  };
  const text = table[resultado.motivo];
  return { text: text || `Rechazada: ${resultado.motivo || "sin motivo declarado"}`, badge: "e19-badge-danger" };
}

function escenarioMotorEfectoLabel(efecto) {
  const table = {
    "cierre-total": "Amortización total · deuda cerrada",
    "amortizacion-parcial": "Amortización parcial",
    "cierre-total-fraccionado": "Amortización a plazos · deuda cerrada",
    "amortizacion-fraccionada-parcial": "Amortización a plazos parcial",
    refinanciada: "Deuda refinanciada",
    "pagos-reanudados": "Pagos retomados",
    reunificada: "Deudas reunificadas",
    compra: "Compra añadida al plan",
    imprevisto: "Imprevisto añadido al plan",
    proyecto: "Proyecto añadido al plan",
    cambio_ingreso: "Ingreso mensual ajustado",
    cambio_gasto: "Gasto mensual ajustado",
  };
  return table[efecto] || efecto || "";
}

// T-5 · Una dependencia que no carga no puede quedarse callada.
//
// Hasta el 10 de agosto de 2026 el sitio publicado no llevaba estos dos archivos, y las cinco
// pantallas del motor se quedaban en blanco **sin un solo error de consola**: el comparador daba
// fecha «—» y coste 0,00 €, la ruta decía «Sin calcular» y «Aplicar al plan» no se habilitaba
// nunca. Un 0,00 € se lee como una respuesta, no como una avería, así que el fallo pasó semanas
// desapercibido. Los canarios de `build-public-site.mjs` y `smoke-public.mjs` impiden ya que falte
// un archivo; esto cubre lo otro: que si algún día falta —por caché vieja, por un despliegue a
// medias o por un bloqueo de red—, la pantalla lo diga en vez de fingir que ha calculado.
const ESCENARIO_MOTOR_DEPENDENCIES = [
  ["FinanceCanonicalScenarioEngine", "canonical-scenario-engine.js"],
  ["FinanceCanonicalScenarioSchema", "canonical-scenario-schema.js"],
];

function missingScenarioDependencies() {
  return ESCENARIO_MOTOR_DEPENDENCIES.filter(([global]) => !window[global]).map(([, file]) => file);
}

function scenarioDependencyMessage(missing) {
  return `Esta pantalla no puede calcular nada ahora mismo: no se ha cargado ${missing.join(" ni ")}. `
    + "Las cifras que falten no son ceros ni resultados, son cálculos que no se han hecho. "
    + "Recarga la página; si sigue igual, vuelve a abrirla sin conexión guardada.";
}

// Devuelve true cuando falta algo, para que quien llame pueda además no pintar cifras vacías como
// si fueran un resultado.
function renderScenarioDependencyNotice(viewId) {
  const section = document.getElementById(viewId);
  if (!section) return false;
  const missing = missingScenarioDependencies();
  const existing = section.querySelector("[data-dependency-notice]");
  if (!missing.length) {
    existing?.remove();
    return false;
  }
  const message = scenarioDependencyMessage(missing);
  if (existing) {
    existing.querySelector("[data-dependency-notice-text]").textContent = message;
    return true;
  }
  const notice = document.createElement("div");
  notice.className = "e19-insight is-danger";
  notice.setAttribute("data-dependency-notice", "");
  notice.setAttribute("role", "status");
  const wrapper = document.createElement("div");
  const title = document.createElement("strong");
  title.textContent = "Falta una pieza para poder calcular";
  const text = document.createElement("p");
  text.setAttribute("data-dependency-notice-text", "");
  text.textContent = message;
  wrapper.append(title, text);
  notice.append(wrapper);
  section.prepend(notice);
  announceStatus(message);
  return true;
}

function runEscenarioMotor(baseInput, decisions, guardrailValue) {
  const engine = window.FinanceCanonicalScenarioEngine;
  if (!engine) return null;
  const context = {
    baseInput,
    debtContracts: canonicalDebtContractRows(),
    meta: { reason: "escenario-motor-ui" },
  };
  if (Number.isFinite(guardrailValue) && guardrailValue > 0) {
    context.guardarrailes = { saldoMinimoAbsoluto: guardrailValue };
  }
  return engine.resolveEscenario(decisions || [], context);
}

// El mes en que una deuda queda a cero, a partir de su propio estado (cuota + plazo restante),
// nunca de una cifra inventada: si la deuda sigue activa se proyecta cuota fija durante
// remainingInstallments meses desde su último cambio real (o desde el inicio del horizonte si
// nadie la ha tocado); si el resultado cae fuera del horizonte modelado se dice explícitamente.
function escenarioMotorContractPayoffMonth(contract, months) {
  if (!months.length) return null;
  if (!(Number(contract.currentPrincipal) > 0) || Number(contract.remainingInstallments) <= 0) {
    return contract.scheduleEffectiveFrom || months[0].monthKey;
  }
  const startIndex = contract.scheduleEffectiveFrom
    ? Math.max(0, months.findIndex((month) => month.monthKey === contract.scheduleEffectiveFrom))
    : 0;
  const payoffIndex = startIndex + Math.max(0, Math.floor(contract.remainingInstallments) - 1);
  return payoffIndex < months.length ? months[payoffIndex].monthKey : null;
}

function escenarioMotorLibreDeDeuda(debtStateFinal, months) {
  const withPrincipal = (debtStateFinal || []).filter((contract) => Number(contract.currentPrincipal) > 0);
  if (!withPrincipal.length) return "sin deuda pendiente";
  const active = withPrincipal.filter((contract) => contract.paymentStatus === "active");
  // Una deuda sin cuota activa (suspendida, o reunificada sin que el plan combinado esté en los
  // datos) no tiene calendario de pago del que proyectar cierre: se dice explícitamente en vez de
  // inventar una fecha a partir de una cuota que hoy no se está pagando.
  if (!active.length) return "sin fecha estimable · sin cuota activa";
  const payoffs = active.map((contract) => escenarioMotorContractPayoffMonth(contract, months));
  if (payoffs.some((value) => value === null)) return "fuera de horizonte";
  const latest = payoffs.sort().at(-1);
  return active.length < withPrincipal.length ? `${latest} · queda deuda sin cuota activa` : latest;
}

function escenarioMotorMonthLabel(value) {
  if (!value) return "—";
  const match = String(value).match(/^(\d{4}-\d{2})(.*)$/);
  if (!match) return value;
  const date = dateFromMonthKey(match[1]);
  return date ? `${monthLabel(date)}${match[2]}` : value;
}

// E-3 (Escenarios.pdf) · «reserva, colchón, fecha libre, ahorro anual, peor mes y capacidad» — los
// tres últimos no tenían cifra propia en el motor E20 (solo daba liquidez final y mínima). Se
// definen aquí sin inventar un dato nuevo: ahorro anual suma `row.saving` (el mismo campo que ya
// usa Plan · Previsión) de los primeros 12 meses del horizonte; meses de colchón divide la liquidez
// final entre el gasto corriente medio de esos mismos 12 meses (`coreSpend`, motor canónico);
// capacidad libre real reutiliza `monthlyFreeCapacity`, la misma función que ya usa Hoy — no una
// fórmula paralela que pudiera divergir.
function escenarioMotorAverageCoreSpend(series) {
  const sample = series.slice(0, 12);
  if (!sample.length) return 0;
  return sumRows(sample, (row) => Number(row.coreSpend || 0)) / sample.length;
}

function escenarioMotorAhorroAnual(series) {
  return round2(sumRows(series.slice(0, 12), (row) => Number(row.saving || 0)));
}

// E-5 (Escenarios.pdf): "Cuatro comprobaciones: origen de fondos, reserva protegida, umbral de
// capacidad y condiciones registradas. Cada una con su estado." Reutiliza señales que el resto de
// la pantalla ya calcula (E-3, el guardarraíl del formulario, el modo de saldo de Registrar) en
// vez de inventar una comprobación paralela. Cuando no hay nada que comprobar dice "sin dato"
// (`pending`), nunca "cumple" — regla transversal 04, dato ausente no es cero.
function escenarioMotorValidationChecks(result, scenarioSummary, guardrailValue) {
  const resultados = result?.resultados || [];
  const rejected = resultados.filter((item) => item.resultado !== "aplicada" && item.resultado !== "inactiva");
  const guardrailBroken = rejected.some((item) => item.resultado === "guardarril-incumplido");
  const otherRejected = rejected.filter((item) => item.resultado !== "guardarril-incumplido");
  const isManualBalance = state?.balanceMode === "manual";
  const hasGuardrail = Number.isFinite(guardrailValue) && guardrailValue > 0;
  const capacidad = scenarioSummary?.capacidadLibre;
  const hasCapacidad = capacidad !== null && capacidad !== undefined;

  return [
    {
      id: "origen",
      label: "Origen de los fondos",
      status: isManualBalance ? "ok" : "warn",
      detail: isManualBalance
        ? `Saldo real declarado a ${formatIsoDate(state.balanceDate || defaultBalanceDate())}.`
        : "Saldo estimado por el motor de fecha, no un saldo declarado a mano.",
    },
    {
      id: "reserva",
      label: "Reserva protegida",
      status: !hasGuardrail ? "pending" : guardrailBroken ? "fail" : "ok",
      detail: !hasGuardrail
        ? "Sin saldo mínimo indicado: no hay nada que comprobar."
        : guardrailBroken
          ? "Alguna decisión rompe el saldo mínimo indicado."
          : `Se mantiene por encima de ${money(guardrailValue, true)} en todo el horizonte.`,
    },
    {
      id: "capacidad",
      label: "Umbral de capacidad",
      status: !hasCapacidad ? "pending" : capacidad < 0 ? "fail" : "ok",
      detail: !hasCapacidad
        ? "Sin datos suficientes para calcular la capacidad libre."
        : capacidad < 0
          ? `Capacidad libre negativa: ${money(capacidad, true)}.`
          : `Capacidad libre real: ${money(capacidad, true)}.`,
    },
    {
      id: "condiciones",
      label: "Condiciones registradas",
      status: !resultados.length ? "pending" : otherRejected.length ? "fail" : "ok",
      detail: !resultados.length
        ? "Todavía no hay ninguna decisión que comprobar."
        : otherRejected.length
          ? `${otherRejected.length} decisión(es) no cumplen sus condiciones.`
          : "Todas las decisiones cumplen las condiciones del contrato.",
    },
  ];
}

function escenarioMotorValidationChecklistHtml(checks) {
  const statusClass = { ok: "is-ok", fail: "is-danger", warn: "is-warn", pending: "is-neutral" };
  return checks
    .map(
      (check) =>
        `<li class="deuda-ruta-check ${statusClass[check.status] || "is-neutral"}"><strong>${escapeHtml(check.label)}</strong><span>${escapeHtml(check.detail)}</span></li>`
    )
    .join("");
}

function escenarioMotorSummaryFor(result, months) {
  if (!result || !result.valid) {
    return {
      minimoLiquidez: null,
      liquidezFinal: null,
      libreDeDeuda: null,
      mesesColchon: null,
      ahorroAnual: null,
      peorMesClave: null,
      peorMesValor: null,
      capacidadLibre: null,
    };
  }
  const series = result.series;
  const worst = series.length
    ? FinanceCanonicalCushion.worstMonthOf(
        months.map((month, index) => ({ key: month.key, totalLiquidity: series[index]?.totalLiquidity ?? 0 })),
        { monthKeyField: "key" },
      )
    : null;
  const liquidezFinal = series.length ? series.at(-1).totalLiquidity : null;
  const avgCoreSpend = series.length ? escenarioMotorAverageCoreSpend(series) : 0;
  return {
    minimoLiquidez: series.length ? Math.min(...series.map((row) => row.totalLiquidity)) : null,
    liquidezFinal,
    libreDeDeuda: escenarioMotorLibreDeDeuda(result.debtStateFinal, months),
    mesesColchon: avgCoreSpend > 0 && liquidezFinal !== null ? round2(liquidezFinal / avgCoreSpend) : null,
    ahorroAnual: series.length ? escenarioMotorAhorroAnual(series) : null,
    peorMesClave: worst?.key || null,
    peorMesValor: worst ? Number(worst.totalLiquidity ?? 0) : null,
    capacidadLibre: series.length ? monthlyFreeCapacity(series) : null,
  };
}

// Fila de la comparativa de seis indicadores: plan vigente frente a la simulación, coloreada según
// mejore o empeore (no según el signo bruto — una fecha «después» es peor aunque sea un número
// mayor). `higherIsBetter=null` deshabilita el color (no hay una dirección buena/mala clara).
function escenarioMotorCompareRowHtml(label, planValue, scenarioValue, formatValue, formatDelta, higherIsBetter = true) {
  const hasBoth = planValue !== null && planValue !== undefined && scenarioValue !== null && scenarioValue !== undefined;
  let toneClass = "";
  let deltaText = "—";
  if (hasBoth) {
    const delta = round2(scenarioValue - planValue);
    deltaText = formatDelta(delta);
    if (higherIsBetter !== null && delta !== 0) toneClass = (delta > 0) === higherIsBetter ? "is-up" : "is-down";
  }
  return `<tr>
    <td>${escapeHtml(label)}</td>
    <td>${hasBoth ? escapeHtml(formatValue(planValue)) : "—"}</td>
    <td><strong>${hasBoth ? escapeHtml(formatValue(scenarioValue)) : "—"}</strong></td>
    <td class="escenario-motor-compare-delta ${toneClass}">${escapeHtml(deltaText)}</td>
  </tr>`;
}

function escenarioMotorMonthCompareDelta(scenarioKey, baseKey) {
  const scenarioIsMonth = /^\d{4}-\d{2}/.test(scenarioKey || "");
  const baseIsMonth = /^\d{4}-\d{2}/.test(baseKey || "");
  if (!scenarioIsMonth || !baseIsMonth) return { text: "—", tone: "" };
  if (scenarioKey === baseKey) return { text: "sin cambio", tone: "" };
  return scenarioKey < baseKey ? { text: "antes", tone: "is-up" } : { text: "después", tone: "is-down" };
}

function escenarioMotorKpiCardsHtml(baseSummary, scenarioSummary) {
  const bajoReserva = Number.isFinite(escenarioMotorGuardrailValue) && (scenarioSummary.minimoLiquidez ?? 0) < escenarioMotorGuardrailValue;
  const libreDelta = escenarioMotorMonthCompareDelta(scenarioSummary.libreDeDeuda, baseSummary.libreDeDeuda);
  const peorMesLabel = (summary) =>
    summary.peorMesClave ? `${escenarioMotorMonthLabel(summary.peorMesClave)} · ${money(summary.peorMesValor ?? 0, true)}` : "—";

  const rows = [
    escenarioMotorCompareRowHtml(
      "Reserva protegida",
      baseSummary.liquidezFinal,
      scenarioSummary.liquidezFinal,
      (value) => money(value, true),
      (delta) => `${delta >= 0 ? "+" : ""}${money(delta, true)}`,
    ),
    escenarioMotorCompareRowHtml(
      "Meses de colchón",
      baseSummary.mesesColchon,
      scenarioSummary.mesesColchon,
      (value) => value.toFixed(1),
      (delta) => `${delta >= 0 ? "+" : ""}${delta.toFixed(1)}`,
    ),
    `<tr>
      <td>Fecha libre de deuda</td>
      <td>${escapeHtml(escenarioMotorMonthLabel(baseSummary.libreDeDeuda))}</td>
      <td><strong>${escapeHtml(escenarioMotorMonthLabel(scenarioSummary.libreDeDeuda))}</strong></td>
      <td class="escenario-motor-compare-delta ${libreDelta.tone}">${escapeHtml(libreDelta.text)}</td>
    </tr>`,
    escenarioMotorCompareRowHtml(
      "Ahorro anual",
      baseSummary.ahorroAnual,
      scenarioSummary.ahorroAnual,
      (value) => money(value, true),
      (delta) => `${delta >= 0 ? "+" : ""}${money(delta, true)}`,
    ),
    `<tr class="${bajoReserva ? "is-danger" : ""}">
      <td>Peor mes</td>
      <td>${escapeHtml(peorMesLabel(baseSummary))}</td>
      <td><strong>${escapeHtml(peorMesLabel(scenarioSummary))}</strong></td>
      <td class="escenario-motor-compare-delta ${
        baseSummary.peorMesValor !== null && scenarioSummary.peorMesValor !== null
          ? scenarioSummary.peorMesValor >= baseSummary.peorMesValor
            ? "is-up"
            : "is-down"
          : ""
      }">${
        baseSummary.peorMesValor !== null && scenarioSummary.peorMesValor !== null
          ? `${round2(scenarioSummary.peorMesValor - baseSummary.peorMesValor) >= 0 ? "+" : ""}${money(round2(scenarioSummary.peorMesValor - baseSummary.peorMesValor), true)}${bajoReserva ? " · bajo el saldo mínimo indicado" : ""}`
          : "—"
      }</td>
    </tr>`,
    escenarioMotorCompareRowHtml(
      "Capacidad libre real",
      baseSummary.capacidadLibre,
      scenarioSummary.capacidadLibre,
      (value) => money(value, true),
      (delta) => `${delta >= 0 ? "+" : ""}${money(delta, true)}`,
    ),
  ];

  return `<table class="e19-table escenario-motor-compare-table">
    <thead><tr><th>Indicador</th><th>Plan</th><th>Simulado</th><th>Diferencia</th></tr></thead>
    <tbody>${rows.join("")}</tbody>
  </table>`;
}

// Gráfico plan actual vs. simulación (mockup 1e). Reutiliza projectChartTickIndexes (ya usado por
// el simulador de proyectos) para las etiquetas de mes — misma convención visual en toda la app.
function renderEscenarioMotorChart(baseSeries, scenarioSeries, months, guardrailValue) {
  const svg = qs("escenarioMotorChart");
  if (!svg || !baseSeries.length || !scenarioSeries.length) return;
  const width = svg.clientWidth || 640;
  const height = 170;
  const pad = { left: 50, right: 16, top: 16, bottom: 26 };
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
  svg.innerHTML = "";

  const values = [...baseSeries.map((row) => row.totalLiquidity), ...scenarioSeries.map((row) => row.totalLiquidity)];
  if (Number.isFinite(guardrailValue)) values.push(guardrailValue);
  const minV = Math.min(...values, 0);
  const maxV = Math.max(...values, 1);
  const plotW = width - pad.left - pad.right;
  const plotH = height - pad.top - pad.bottom;
  const n = baseSeries.length;
  const x = (i) => pad.left + (n <= 1 ? 0 : (i / (n - 1)) * plotW);
  const y = (value) => pad.top + plotH - ((value - minV) / Math.max(1, maxV - minV)) * plotH;
  const pathFor = (series) => series.map((row, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(2)} ${y(row.totalLiquidity).toFixed(2)}`).join(" ");

  let markup = `<path class="chart-line-base" d="${pathFor(baseSeries)}" />`;
  markup += `<path class="chart-line-scenario" d="${pathFor(scenarioSeries)}" />`;
  if (Number.isFinite(guardrailValue)) {
    const ry = y(guardrailValue).toFixed(2);
    markup += `<line class="chart-line-reserve" x1="${pad.left}" x2="${width - pad.right}" y1="${ry}" y2="${ry}" />`;
  }
  projectChartTickIndexes(months, width).forEach((idx) => {
    markup += `<text class="chart-label" x="${(x(idx) - 14).toFixed(2)}" y="${height - 6}">${escapeHtml(months[idx]?.month || "")}</text>`;
  });
  svg.insertAdjacentHTML("beforeend", markup);
}

function escenarioMotorNavigate(viewId) {
  history.pushState(null, "", `#${viewId}`);
  setActiveView(viewId);
}

// Los escenarios guardados antes de E20-3 no llevan `titulo` (solo existía amortización), igual que
// las rutas que llegan desde el comparador de estrategias. Se reconstruye con el mismo generador de
// título del catálogo, que solo lee claves presentes también en `params`.
function escenarioMotorDecisionTitle(decision, debts) {
  if (decision.titulo) return decision.titulo;
  const type = escenarioMotorResolveType(decision);
  if (!type) return decision.tipo || "Decisión";
  const debtLabel = (deudaId) => {
    const contract = debts?.get(deudaId);
    return contract ? escenarioMotorDebtLabel(contract) : escenarioMotorDebtLabelById(deudaId);
  };
  return escenarioMotorTrim(type.titulo(decision.params || {}, { debtLabel }) || type.label);
}

function escenarioMotorDecisionDetail(decision) {
  const type = escenarioMotorResolveType(decision);
  return type && typeof type.detalle === "function" ? type.detalle(decision) : "";
}

function escenarioMotorDecisionAmountText(decision) {
  const type = escenarioMotorResolveType(decision);
  return type && typeof type.importeTexto === "function" ? type.importeTexto(decision) : "—";
}

// El mes efectivo depende del tipo: la planificación lo lleva en los tipos de deuda y en compra,
// pero `imprevisto`, `retomar_pagos` y los cambios de ingreso/gasto lo llevan en sus propios params.
function escenarioMotorDecisionMonthKey(decision, resultado) {
  return resultado?.mesResuelto
    || decision.planificacion?.mesResuelto
    || decision.planificacion?.mesManual
    || decision.params?.mes
    || decision.params?.mesInicio
    || decision.params?.mesObjetivo
    || null;
}

function escenarioMotorDraftName() {
  const debts = new Map(canonicalDebtContractRows().map((contract) => [contract.id, contract]));
  const parts = escenarioMotorDecisions.map((decision) => escenarioMotorDecisionTitle(decision, debts));
  return parts.join(" + ") || "Escenario sin nombre";
}

// E-7 (Escenarios.pdf): "Además del diagnóstico, nombra qué parámetro habría que cambiar y qué
// dirección para que el escenario deje de romper la reserva." Reutiliza las mismas cuatro
// comprobaciones de E-5 — nunca vuelve a decidir por su cuenta si algo falla — y nombra la decisión
// concreta que rompe el guardarraíl cuando la hay, con una dirección genérica (importe o mes), no
// una cifra recalculada: dar un número exacto exigiría probar valores hasta encontrar uno viable,
// un buscador que esta pantalla no tiene (eso es lo que hace «Ajustar automáticamente» con el mes,
// no con el importe).
function escenarioMotorVerdictText(checks, decisions, rejected) {
  if (!decisions.length) return "";
  const reserva = checks.find((check) => check.id === "reserva");
  if (reserva?.status === "fail") {
    const culprit = rejected.find((item) => item.resultado === "guardarril-incumplido");
    const decision = culprit ? decisions.find((item) => item.id === culprit.id) : null;
    const debts = new Map(canonicalDebtContractRows().map((contract) => [contract.id, contract]));
    const nombre = decision ? escenarioMotorDecisionTitle(decision, debts) : "una de las decisiones";
    return `Esta simulación rompe la reserva mínima indicada. La palanca es «${nombre}»: reduce su importe o elígele un mes con más margen.`;
  }
  const capacidad = checks.find((check) => check.id === "capacidad");
  if (capacidad?.status === "fail") {
    return "La capacidad libre real queda en negativo: reduce el gasto comprometido en esta simulación o repártelo en más meses para que deje de romperla.";
  }
  const condiciones = checks.find((check) => check.id === "condiciones");
  if (condiciones?.status === "fail") {
    return "Alguna decisión no cumple sus propias condiciones (ver su motivo en la lista); el resto de la simulación no rompe ningún límite conocido.";
  }
  return "Esta simulación no rompe ningún límite conocido con las decisiones actuales.";
}

// E-8: "Liquidez apilada CaixaBank / Mediolanum mes a mes; los meses bajo el mínimo operativo se
// tiñen y se nombran." El motor de dos cuentas ya reparte cada mes en `checking` (CaixaBank) y
// `savings` (Mediolanum) — la banda es una lectura nueva de esa misma serie, no un cálculo nuevo.
// Sin una cifra de «mínimo operativo» configurada en la app, el umbral honesto es 0: CaixaBank en
// negativo ese mes (regla transversal 04, no inventar un umbral que no existe en Ajustes).
function escenarioMotorAccountBand(scenarioSeries, months) {
  const sample = scenarioSeries.slice(0, 12);
  return sample.map((row, index) => ({
    key: months[index]?.key || "",
    label: months[index]?.month || "",
    checking: round2(row.checking ?? 0),
    savings: round2(row.savings ?? 0),
    bajoMinimo: (row.checking ?? 0) < 0,
  }));
}

function escenarioMotorAccountBandHtml(band) {
  if (!band.length) return "";
  const max = Math.max(1, ...band.map((item) => Math.abs(item.checking) + Math.max(0, item.savings)));
  return band
    .map((item) => {
      const checkingHeight = round2((Math.abs(item.checking) / max) * 100);
      const savingsHeight = round2((Math.max(0, item.savings) / max) * 100);
      return `<div class="escenario-motor-account-col${item.bajoMinimo ? " is-bajo-minimo" : ""}">
        <div class="escenario-motor-account-bar">
          <span class="escenario-motor-account-seg is-savings" style="height:${savingsHeight}%"></span>
          <span class="escenario-motor-account-seg ${item.bajoMinimo ? "is-bajo" : "is-checking"}" style="height:${checkingHeight}%"></span>
        </div>
        <span class="escenario-motor-account-label">${escapeHtml(item.label)}</span>
      </div>`;
    })
    .join("");
}

function escenarioMotorAccountBandNote(band) {
  const bajo = band.filter((item) => item.bajoMinimo);
  if (!bajo.length) return "";
  return `${bajo.map((item) => item.label).join(", ")} queda${bajo.length > 1 ? "n" : ""} con CaixaBank en negativo.`;
}

// E-9: "El conmutador de la barra sustituye la vista entera: desaparecen la tabla de indicadores y
// la validación, y queda la explicación llana con las cuatro cifras que importan en casa." Las
// cuatro son un subconjunto de los seis indicadores de E-3 (los dos más operativos —peor mes,
// capacidad libre— se quedan en la vista técnica): mismas cifras, sin recalcular nada.
function escenarioMotorFamilyCardHtml(scenarioSummary) {
  const rows = [
    ["¿Cuánto nos queda?", scenarioSummary.liquidezFinal !== null ? money(scenarioSummary.liquidezFinal, true) : "—"],
    ["¿Cuántos meses aguantaríamos sin ingresos?", scenarioSummary.mesesColchon !== null ? `${scenarioSummary.mesesColchon.toFixed(1)} meses` : "—"],
    ["¿Cuándo dejamos de deber?", escenarioMotorMonthLabel(scenarioSummary.libreDeDeuda)],
    ["¿Cuánto ahorramos al año?", scenarioSummary.ahorroAnual !== null ? money(scenarioSummary.ahorroAnual, true) : "—"],
  ];
  return `<article class="e19-card escenario-motor-family-card">
    <h3 class="escenario-motor-panel-title">Explicado para casa</h3>
    <dl class="escenario-motor-family-list">${rows
      .map(([label, value]) => `<div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>`)
      .join("")}</dl>
  </article>`;
}

// E-6b: "Un escenario rechazado se puede guardar como aviso: queda etiquetado «esto es lo que no
// aguantamos» y no se puede aplicar." Reutiliza el texto de rechazo ya calculado (E-5/E-6) — nunca
// inventa una explicación nueva — y comparte la lista de guardados con estado `"aviso"`, distinto
// de `"guardado"`/`"aplicado"`.
function escenarioMotorAvisoReason(rejected) {
  if (!rejected.length) return "Rechazado sin motivo declarado.";
  const info = escenarioMotorRejectionInfo(rejected[0]) || escenarioMotorResultInfo(rejected[0].resultado);
  return `${info?.text || "Rechazado"}.`;
}

function handleEscenarioMotorSaveAviso() {
  if (!escenarioMotorDecisions.length) return;
  const baseInput = escenarioMotorBaseInput();
  const result = runEscenarioMotor(baseInput, escenarioMotorDecisions, escenarioMotorGuardrailValue);
  const rejected = (result?.resultados || []).filter((item) => item.resultado !== "aplicada" && item.resultado !== "inactiva");
  if (!rejected.length) return;
  const saved = loadEscenarioMotorSaved();
  escenarioMotorSavedSeq += 1;
  saved.unshift({
    id: `escenario-guardado-${Date.now()}-${escenarioMotorSavedSeq}`,
    nombre: escenarioMotorDraftName(),
    motivo: escenarioMotorAvisoReason(rejected),
    estado: "aviso",
    fecha: new Date().toISOString(),
    decisiones: JSON.parse(JSON.stringify(escenarioMotorDecisions)),
    guardrailValue: escenarioMotorGuardrailValue,
  });
  saveEscenarioMotorSavedList(saved);
  escenarioMotorDecisions = [];
  renderEscenarioSimular();
}

function handleEscenarioMotorFamilyToggle() {
  escenarioMotorFamilyView = !escenarioMotorFamilyView;
  renderEscenarioSimular();
}

function renderEscenarioSimular() {
  renderScenarioDependencyNotice("escenario-simular");
  const baseInput = escenarioMotorBaseInput();
  renderEscenarioMotorForm(baseInput);

  const guardrailField = qs("escenarioMotorGuardrail");
  if (guardrailField && document.activeElement !== guardrailField) {
    guardrailField.value = escenarioMotorGuardrailValue ?? "";
  }

  const body = qs("escenarioMotorDecisionsList");
  const empty = qs("escenarioMotorEmpty");
  const kpis = qs("escenarioMotorKpis");
  const validationCard = qs("escenarioMotorValidationCard");
  const validationList = qs("escenarioMotorValidationList");
  const warning = qs("escenarioMotorWarning");
  const warningText = qs("escenarioMotorWarningText");
  const autoAdjustButton = qs("escenarioMotorAutoAdjust");
  const goApplyButton = qs("escenarioMotorGoApply");
  const saveAvisoButton = qs("escenarioMotorSaveAviso");
  const verdictEl = qs("escenarioMotorVerdict");
  const accountBandCard = qs("escenarioMotorAccountBandCard");
  const accountBandEl = qs("escenarioMotorAccountBand");
  const accountBandNoteEl = qs("escenarioMotorAccountBandNote");
  const familyToggle = qs("escenarioMotorFamilyToggle");
  const familyCard = qs("escenarioMotorFamilyCard");
  if (!body || !kpis) return;

  familyToggle?.classList.toggle("is-active", escenarioMotorFamilyView);
  if (familyToggle) familyToggle.textContent = escenarioMotorFamilyView ? "Vista técnica" : "Vista familiar";

  const baseResult = runEscenarioMotor(baseInput, [], null);

  if (!escenarioMotorDecisions.length) {
    body.innerHTML = "";
    if (empty) empty.hidden = false;
    kpis.innerHTML = "";
    if (validationCard) validationCard.hidden = true;
    if (validationList) validationList.innerHTML = "";
    if (warning) warning.hidden = true;
    if (goApplyButton) goApplyButton.disabled = true;
    if (verdictEl) verdictEl.hidden = true;
    if (familyCard) familyCard.hidden = true;
    if (accountBandCard) accountBandCard.hidden = true;
    renderEscenarioMotorChart(baseResult?.series || [], baseResult?.series || [], baseInput.months, escenarioMotorGuardrailValue);
    return;
  }
  if (empty) empty.hidden = true;

  const result = runEscenarioMotor(baseInput, escenarioMotorDecisions, escenarioMotorGuardrailValue);
  const debts = new Map(canonicalDebtContractRows().map((contract) => [contract.id, contract]));
  const resultadosById = new Map((result?.resultados || []).map((item) => [item.id, item]));
  const rejected = (result?.resultados || []).filter((item) => item.resultado !== "aplicada");
  if (saveAvisoButton) saveAvisoButton.hidden = !rejected.length;

  body.innerHTML = escenarioMotorDecisions
    .map((decision) => {
      const resultado = resultadosById.get(decision.id);
      const info = (resultado && escenarioMotorRejectionInfo(resultado))
        || (resultado ? escenarioMotorResultInfo(resultado.resultado) : { text: "Sin calcular", badge: "e19-badge-neutral" });
      const mesLabel = decision.planificacion.modo === "optimo"
        ? (resultado?.mesResuelto ? `Óptimo · ${escenarioMotorMonthLabel(resultado.mesResuelto)}` : "Buscando mes óptimo…")
        : escenarioMotorMonthLabel(escenarioMotorDecisionMonthKey(decision, resultado));
      const detalle = escenarioMotorDecisionDetail(decision);
      return `<li class="escenario-motor-decision-item">
        <div class="escenario-motor-decision-main">
          <strong>${escapeHtml(escenarioMotorDecisionTitle(decision, debts))}</strong>
          <span>${escapeHtml(detalle ? `${detalle} · ${mesLabel}` : mesLabel)}</span>
        </div>
        <div class="escenario-motor-decision-status">
          <span class="e19-badge ${info.badge}">${escapeHtml(info.text)}</span>
          <button type="button" class="escenario-motor-decision-remove" data-escenario-motor-remove="${escapeHtml(decision.id)}">Quitar</button>
        </div>
      </li>`;
    })
    .join("");

  renderEscenarioMotorChart(baseResult?.series || [], result?.series || baseResult?.series || [], baseInput.months, escenarioMotorGuardrailValue);

  if (!result || !result.valid) {
    kpis.innerHTML = "";
    if (validationCard) validationCard.hidden = true;
    if (validationList) validationList.innerHTML = "";
    if (warning) warning.hidden = true;
    if (goApplyButton) goApplyButton.disabled = true;
    if (verdictEl) verdictEl.hidden = true;
    if (familyCard) familyCard.hidden = true;
    if (accountBandCard) accountBandCard.hidden = true;
    return;
  }

  const baseSummary = escenarioMotorSummaryFor(baseResult, baseInput.months);
  const scenarioSummary = escenarioMotorSummaryFor(result, baseInput.months);
  const checks = escenarioMotorValidationChecks(result, scenarioSummary, escenarioMotorGuardrailValue);

  // E-9: el conmutador sustituye la comparativa técnica entera por la tarjeta llana — nunca se
  // muestran las dos a la vez.
  if (kpis) kpis.hidden = escenarioMotorFamilyView;
  if (validationCard) validationCard.hidden = escenarioMotorFamilyView;
  if (verdictEl) verdictEl.hidden = escenarioMotorFamilyView;
  if (familyCard) {
    familyCard.hidden = !escenarioMotorFamilyView;
    if (escenarioMotorFamilyView) familyCard.innerHTML = escenarioMotorFamilyCardHtml(scenarioSummary);
  }
  if (!escenarioMotorFamilyView) {
    kpis.innerHTML = escenarioMotorKpiCardsHtml(baseSummary, scenarioSummary);
    if (validationList) validationList.innerHTML = escenarioMotorValidationChecklistHtml(checks);
    if (verdictEl) verdictEl.textContent = escenarioMotorVerdictText(checks, escenarioMotorDecisions, result.resultados || []);
  }

  // E-8: banda de doce meses por cuenta — se ve en ambas vistas, técnica y familiar, porque no es
  // parte de «la tabla de indicadores» que E-9 retira.
  if (accountBandCard) accountBandCard.hidden = false;
  if (accountBandEl || accountBandNoteEl) {
    const band = escenarioMotorAccountBand(result.series || [], baseInput.months);
    if (accountBandEl) accountBandEl.innerHTML = escenarioMotorAccountBandHtml(band);
    if (accountBandNoteEl) accountBandNoteEl.textContent = escenarioMotorAccountBandNote(band);
  }

  if (rejected.length) {
    if (warning) warning.hidden = false;
    const info = escenarioMotorRejectionInfo(rejected[0]) || escenarioMotorResultInfo(rejected[0].resultado);
    if (warningText) {
      warningText.textContent = rejected.length > 1
        ? `${info.text} (y ${rejected.length - 1} decisión(es) más sin aplicar).`
        : `${info.text}.`;
    }
    if (autoAdjustButton) autoAdjustButton.hidden = !rejected.some((item) => item.resultado === "guardarril-incumplido");
    if (goApplyButton) goApplyButton.disabled = true;
  } else {
    if (warning) warning.hidden = true;
    if (goApplyButton) goApplyButton.disabled = false;
  }
}

// Construye la decisión desde el borrador y la valida con el contrato antes de aceptarla. Si el
// contrato la rechaza no se añade nada: se muestran sus propios mensajes, campo a campo, en vez de
// dejar entrar una decisión que el motor resolvería a medias o ignoraría.
function handleEscenarioMotorSubmit(event) {
  event.preventDefault();
  const type = escenarioMotorTypeOrCustomById(escenarioMotorDraftTipo);
  if (!type) return;
  escenarioMotorSyncDraftValues();
  const values = escenarioMotorEffectiveValues(type, escenarioMotorDraftValues);
  const mesManual = type.mes(values);

  const decision = {
    id: escenarioMotorNewDecisionId(),
    // E-1b: un tipo propio se identifica en el formulario por su clave de selección
    // (`propio_<definicionId>`), pero el motor y el esquema solo conocen el tipo real `"propio"`.
    tipo: type.engineTipo || type.id,
    titulo: escenarioMotorTrim(type.titulo(values, { debtLabel: escenarioMotorDebtLabelById }) || type.label),
    activa: true,
    orden: escenarioMotorDecisions.length,
    planificacion: mesManual ? { modo: "manual", mesManual } : { modo: "optimo" },
    params: type.params(values),
  };

  const issues = [];
  const schema = window.FinanceCanonicalScenarioSchema;
  // Sin esquema no se validaba nada y la decisión entraba igual: peor que no poder añadirla, porque
  // aceptaba en silencio un dato sin comprobar. Ahora se dice y no se añade.
  if (!schema) {
    escenarioMotorShowFormErrors([
      "No se puede comprobar esta decisión: no se ha cargado canonical-scenario-schema.js. No se añade nada, para no aceptar un dato sin validar.",
    ]);
    return;
  }
  schema.validateDecision(decision, "$", issues);
  const errors = issues.filter((issue) => issue.severity === "error");
  if (errors.length) {
    escenarioMotorShowFormErrors(errors.map((issue) => escenarioMotorIssueMessage(issue, type)));
    return;
  }

  escenarioMotorShowFormErrors([]);
  escenarioMotorDecisions.push(decision);
  escenarioMotorResetDraft(type);
  renderEscenarioSimular();
}

function escenarioMotorDebtLabelById(deudaId) {
  const contract = canonicalDebtContractRows().find((item) => item.id === deudaId);
  return contract ? escenarioMotorDebtLabel(contract) : deudaId || "deuda sin identificar";
}

// Tras añadir una decisión se vacían los importes y textos, pero se conservan los desplegables
// (deuda, mes, titular…): encadenar dos decisiones sobre el mismo mes es el caso normal.
function escenarioMotorResetDraft(type) {
  type.campos.forEach((field) => {
    if (["money", "number", "int", "pct", "text", "date"].includes(field.kind)) delete escenarioMotorDraftValues[field.key];
    if (field.kind === "checkbox") escenarioMotorDraftValues[field.key] = false;
  });
}

function handleEscenarioMotorTypeChange(event) {
  escenarioMotorSyncDraftValues();
  escenarioMotorDraftTipo = event.target.value;
  escenarioMotorShowFormErrors([]);
  renderEscenarioMotorForm(escenarioMotorBaseInput());
}

// E-1b: el constructor de tipos propios es un panel plegable independiente del formulario de
// decisión — abrirlo/cerrarlo no toca `escenarioMotorDraftTipo` ni el borrador en curso.
function handleEscenarioMotorCustomToggle() {
  escenarioMotorCustomBuilderOpen = !escenarioMotorCustomBuilderOpen;
  const builder = qs("escenarioMotorCustomBuilder");
  if (builder) builder.hidden = !escenarioMotorCustomBuilderOpen;
}

function escenarioMotorCustomFieldsFromForm() {
  const campos = [];
  if (qs("escenarioMotorCustomFieldImporte")?.checked) campos.push("importe");
  if (qs("escenarioMotorCustomFieldMensualidad")?.checked) campos.push("mensualidad");
  if (qs("escenarioMotorCustomFieldPlazo")?.checked) campos.push("plazo");
  return campos;
}

// Crea la definición y deja el simulador listo para su primera decisión: el tipo nuevo queda
// seleccionado, con su propio formulario (los campos elegidos + mes) ya pintado.
function handleEscenarioMotorCustomCreate() {
  const labelInput = qs("escenarioMotorCustomLabel");
  const familiaSelect = qs("escenarioMotorCustomFamilia");
  const errorEl = qs("escenarioMotorCustomError");
  const label = (labelInput?.value || "").trim();
  const campos = escenarioMotorCustomFieldsFromForm();
  const showError = (message) => {
    if (errorEl) {
      errorEl.hidden = false;
      errorEl.textContent = message;
    }
  };
  if (!label) {
    showError("Ponle un nombre al tipo.");
    return;
  }
  if (!campos.length) {
    showError("Elige al menos un campo, además del mes.");
    return;
  }
  if (errorEl) errorEl.hidden = true;

  const custom = {
    id: escenarioMotorNewCustomTypeId(),
    familia: familiaSelect?.value === "Deuda" ? "Deuda" : "Vida",
    label: escenarioMotorTrim(label, 60),
    campos,
  };
  const list = loadEscenarioMotorCustomTypes();
  list.push(custom);
  saveEscenarioMotorCustomTypesList(list);

  escenarioMotorCustomBuilderOpen = false;
  if (labelInput) labelInput.value = "";
  escenarioMotorDraftTipo = `propio_${custom.id}`;
  escenarioMotorDraftValues = {};
  renderEscenarioSimular();
}

// Solo reacciona a los campos que gobiernan la visibilidad de otros (la casilla «la financio», el
// selector de modalidad…); el resto se lee al enviar, para no reconstruir el formulario mientras se
// escribe en él.
function handleEscenarioMotorFieldChange(event) {
  const key = event.target?.dataset?.escenarioMotorField;
  if (!key) return;
  const type = escenarioMotorTypeOrCustomById(escenarioMotorDraftTipo);
  const field = type?.campos.find((item) => item.key === key);
  if (!field) return;
  escenarioMotorDraftValues[key] = escenarioMotorReadFieldValue(field, event.target);
  if (field.controla) escenarioMotorSyncFieldVisibility();
}

function handleEscenarioMotorRemove(id) {
  escenarioMotorDecisions = escenarioMotorDecisions.filter((decision) => decision.id !== id);
  renderEscenarioSimular();
}

// E-2 (Escenarios.pdf): "el resultado se recalcula al editar, con 120 ms de debounce sobre el
// cálculo" — este campo es el único que recalcula la simulación completa mientras se escribe (los
// campos por tipo solo se leen al enviar, R-6/E-2 no aplican ahí). Se lee el valor al vuelo para
// que el propio `<input>` nunca pierda lo que se ha tecleado, pero el recálculo/render se retrasa.
function handleEscenarioMotorGuardrailInput(event) {
  const value = Number(event.target.value);
  escenarioMotorGuardrailValue = Number.isFinite(value) && value > 0 ? value : null;
  clearTimeout(escenarioMotorGuardrailDebounceTimer);
  escenarioMotorGuardrailDebounceTimer = setTimeout(renderEscenarioSimular, 120);
}

// «Ajustar automáticamente» reutiliza el buscador de mes óptimo real del motor (planificacion.modo
// "optimo", día 3 de E20-0): no calcula nada aquí, solo cambia cómo se planifica la decisión y deja
// que el motor busque el primer mes viable — o la rechace con «sin-mes-viable» si no existe.
function handleEscenarioMotorAutoAdjust() {
  const baseInput = escenarioMotorBaseInput();
  const result = runEscenarioMotor(baseInput, escenarioMotorDecisions, escenarioMotorGuardrailValue);
  const rejectedIds = new Set(
    (result?.resultados || []).filter((item) => item.resultado === "guardarril-incumplido").map((item) => item.id)
  );
  if (!rejectedIds.size) return;
  escenarioMotorDecisions = escenarioMotorDecisions.map((decision) =>
    rejectedIds.has(decision.id) ? { ...decision, planificacion: { modo: "optimo" } } : decision
  );
  renderEscenarioSimular();
}

function handleEscenarioMotorGoApply() {
  if (!escenarioMotorDecisions.length) return;
  escenarioMotorNavigate("escenario-aplicar");
}

// ---------------------------------------------------------------------------------------------
// Pantalla 2 · Aplicar escenario (mockup 2d): diferencia línea a línea antes de confirmar. No
// muta los contratos de deuda — «aplicar» aquí significa registrar el escenario como el aplicado
// en la lista de guardados (pantalla 3), con motivo y fecha, de verdad reversible porque no toca
// ningún dato real. La única puerta que sí toca el contrato es Deuda › Contratos (D-2), y vive
// aparte de este flujo de decisiones.
// ---------------------------------------------------------------------------------------------
function renderEscenarioAplicar() {
  renderScenarioDependencyNotice("escenario-aplicar");
  if (!escenarioMotorDecisions.length) {
    escenarioMotorNavigate("escenario-simular");
    return;
  }
  const baseInput = escenarioMotorBaseInput();
  const baseResult = runEscenarioMotor(baseInput, [], null);
  const result = runEscenarioMotor(baseInput, escenarioMotorDecisions, escenarioMotorGuardrailValue);
  const debts = new Map(canonicalDebtContractRows().map((contract) => [contract.id, contract]));
  const resultadosById = new Map((result?.resultados || []).map((item) => [item.id, item]));

  const titleEl = qs("escenarioAplicarTitle");
  if (titleEl) titleEl.textContent = escenarioMotorDraftName();
  const changesTitle = qs("escenarioAplicarChangesTitle");
  if (changesTitle) changesTitle.textContent = `${escenarioMotorDecisions.length} cambio(s) en el plan`;

  const baseSummary = escenarioMotorSummaryFor(baseResult, baseInput.months);
  const scenarioSummary = escenarioMotorSummaryFor(result, baseInput.months);
  const kpis = qs("escenarioAplicarKpis");
  if (kpis) kpis.innerHTML = escenarioMotorKpiCardsHtml(baseSummary, scenarioSummary);
  const validationList = qs("escenarioAplicarValidationList");
  if (validationList) {
    validationList.innerHTML = escenarioMotorValidationChecklistHtml(
      escenarioMotorValidationChecks(result, scenarioSummary, escenarioMotorGuardrailValue)
    );
  }

  const body = qs("escenarioAplicarDiffBody");
  if (body) {
    body.innerHTML = escenarioMotorDecisions
      .map((decision) => {
        const resultado = resultadosById.get(decision.id);
        const info = (resultado && escenarioMotorRejectionInfo(resultado))
          || (resultado ? escenarioMotorResultInfo(resultado.resultado) : { text: "Sin calcular", badge: "e19-badge-neutral" });
        const efecto = resultado?.efecto ? escenarioMotorEfectoLabel(resultado.efecto) : info.text;
        const mesLabel = escenarioMotorMonthLabel(escenarioMotorDecisionMonthKey(decision, resultado));
        return `<tr>
          <td>${escapeHtml(escenarioMotorDecisionTitle(decision, debts))}</td>
          <td>${escapeHtml(efecto)}</td>
          <td>${escapeHtml(escenarioMotorDecisionAmountText(decision))}</td>
          <td>${escapeHtml(mesLabel)}</td>
        </tr>`;
      })
      .join("");
  }

  const confirmButton = qs("escenarioAplicarConfirm");
  const allApplied = (result?.resultados || []).length > 0 && (result?.resultados || []).every((item) => item.resultado === "aplicada");
  if (confirmButton) confirmButton.disabled = !allApplied;
}

function handleEscenarioAplicarBack() {
  escenarioMotorNavigate("escenario-simular");
}

function loadEscenarioMotorSaved() {
  try {
    const parsed = JSON.parse(storageGet(storageKey("escenario-motor-saved"), "[]"));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveEscenarioMotorSavedList(list) {
  storageSet(storageKey("escenario-motor-saved"), JSON.stringify(list));
}

// E-11 · la fecha de revisión es opcional (a diferencia del motivo): sin ella no se crea ningún
// recordatorio, «misma barra que Deuda» — homeEscenarioReviewReminders() la lee igual que
// homeDebtReviewReminders() ya hace con decision.e14Application.reviewDate.
function handleEscenarioAplicarConfirm(event) {
  event.preventDefault();
  const motivoInput = qs("escenarioAplicarMotivo");
  const motivo = (motivoInput?.value || "").trim();
  if (!motivo) {
    motivoInput?.focus();
    return;
  }
  const reviewDateInput = qs("escenarioAplicarReviewDate");
  const reviewDate = reviewDateInput?.value || "";
  const saved = loadEscenarioMotorSaved().map((entry) => (entry.estado === "aplicado" ? { ...entry, estado: "guardado" } : entry));
  escenarioMotorSavedSeq += 1;
  saved.unshift({
    id: `escenario-guardado-${Date.now()}-${escenarioMotorSavedSeq}`,
    nombre: escenarioMotorDraftName(),
    motivo,
    estado: "aplicado",
    fecha: new Date().toISOString(),
    decisiones: JSON.parse(JSON.stringify(escenarioMotorDecisions)),
    guardrailValue: escenarioMotorGuardrailValue,
    reviewDate,
  });
  saveEscenarioMotorSavedList(saved);
  escenarioMotorDecisions = [];
  if (motivoInput) motivoInput.value = "";
  if (reviewDateInput) reviewDateInput.value = "";
  escenarioMotorNavigate("escenario-guardados");
}

// ---------------------------------------------------------------------------------------------
// Pantalla 3 · Escenarios guardados (mockup 2e). Los KPIs de cada tarjeta se recalculan al vuelo
// con el motor real sobre el estado actual de las deudas — nunca se leen cifras congeladas del
// momento en que se guardó, para que no diverjan en silencio de la realidad. «Recomendado» y
// «Caducado» del mockup no se implementan: no hay todavía motor de recomendación ni concepto de
// oferta con vencimiento — solo «Aplicado» y «Guardado», que sí están respaldados por datos reales.
// ---------------------------------------------------------------------------------------------
function renderEscenarioGuardados() {
  renderScenarioDependencyNotice("escenario-guardados");
  const list = loadEscenarioMotorSaved();
  const container = qs("escenarioGuardadosList");
  const empty = qs("escenarioGuardadosEmpty");
  if (!container) return;
  if (!list.length) {
    container.innerHTML = "";
    if (empty) empty.hidden = false;
    return;
  }
  if (empty) empty.hidden = true;

  const baseInput = escenarioMotorBaseInput();
  container.innerHTML = list
    .map((entry) => {
      const result = runEscenarioMotor(baseInput, entry.decisiones || [], entry.guardrailValue ?? null);
      const summary = escenarioMotorSummaryFor(result, baseInput.months);
      // E-6b: un tercer estado, distinto de aplicado/guardado — el escenario no converge y se
      // guarda para no repetir el mismo intento sin darse cuenta.
      const estadoInfo = entry.estado === "aplicado"
        ? { text: "Aplicado", badge: "e19-badge-success" }
        : entry.estado === "aviso"
          ? { text: "Aviso", badge: "e19-badge-danger" }
          : { text: "Guardado", badge: "e19-badge-neutral" };
      const fecha = entry.fecha ? new Date(entry.fecha).toLocaleDateString("es-ES", { day: "numeric", month: "short", year: "numeric" }) : "";
      const cardClass = entry.estado === "aplicado" ? " is-aplicado" : entry.estado === "aviso" ? " is-aviso" : "";
      return `<article class="escenario-motor-saved-card${cardClass}">
        <div class="escenario-motor-saved-head">
          <span class="e19-badge ${estadoInfo.badge}">${estadoInfo.text}</span>
          <strong>${escapeHtml(entry.nombre || "Escenario")}</strong>
          <small>${escapeHtml(entry.motivo || "")}${fecha ? ` · ${escapeHtml(fecha)}` : ""}</small>
        </div>
        <div class="escenario-motor-saved-meta">
          <div><span>Libre de deuda</span><strong>${escapeHtml(escenarioMotorMonthLabel(summary.libreDeDeuda))}</strong></div>
          <div><span>Caja mínima</span><strong>${money(summary.minimoLiquidez ?? 0, true)}</strong></div>
          <div><span>Liquidez final</span><strong>${money(summary.liquidezFinal ?? 0, true)}</strong></div>
        </div>
        ${entry.estado === "aviso" ? `<p class="escenario-motor-saved-limite">límite conocido</p>` : ""}
        <div class="escenario-motor-saved-actions">
          <button type="button" class="e19-btn e19-btn-secondary" data-escenario-guardado-load="${escapeHtml(entry.id)}">Cargar en simulador</button>
          <button type="button" class="e19-btn e19-btn-secondary" data-escenario-guardado-delete="${escapeHtml(entry.id)}">Eliminar</button>
        </div>
      </article>`;
    })
    .join("");
}

function handleEscenarioGuardadosLoad(id) {
  const entry = loadEscenarioMotorSaved().find((item) => item.id === id);
  if (!entry) return;
  escenarioMotorDecisions = JSON.parse(JSON.stringify(entry.decisiones || []));
  escenarioMotorGuardrailValue = entry.guardrailValue ?? null;
  escenarioMotorNavigate("escenario-simular");
}

function handleEscenarioGuardadosDelete(id) {
  saveEscenarioMotorSavedList(loadEscenarioMotorSaved().filter((entry) => entry.id !== id));
  renderEscenarioGuardados();
}

function handleEscenarioGuardadosNew() {
  escenarioMotorDecisions = [];
  escenarioMotorGuardrailValue = null;
  escenarioMotorNavigate("escenario-simular");
}

// ---------------------------------------------------------------------------------------------
// E-12: "Tabla de tres columnas —plan, escenario A, escenario B— con los mismos seis indicadores."
// Sin color de dirección (a diferencia de E-3): comparar A contra B no tiene un «mejor» universal
// sin saber cuál de los dos se está defendiendo, así que se deja la lectura al usuario. Los avisos
// (E-6b) no entran en los selectores — no son escenarios viables que comparar, son un límite
// conocido.
// ---------------------------------------------------------------------------------------------
function escenarioMotorCompareThreeHtml(baseSummary, summaryA, summaryB, nameA, nameB) {
  const rows = [
    ["Reserva protegida", (s) => (s.liquidezFinal !== null ? money(s.liquidezFinal, true) : "—")],
    ["Meses de colchón", (s) => (s.mesesColchon !== null ? s.mesesColchon.toFixed(1) : "—")],
    ["Fecha libre de deuda", (s) => escenarioMotorMonthLabel(s.libreDeDeuda)],
    ["Ahorro anual", (s) => (s.ahorroAnual !== null ? money(s.ahorroAnual, true) : "—")],
    ["Peor mes", (s) => (s.peorMesClave ? `${escenarioMotorMonthLabel(s.peorMesClave)} · ${money(s.peorMesValor ?? 0, true)}` : "—")],
    ["Capacidad libre real", (s) => (s.capacidadLibre !== null ? money(s.capacidadLibre, true) : "—")],
  ];
  return `<table class="e19-table escenario-motor-compare-table">
    <thead><tr><th>Indicador</th><th>Plan</th><th>${escapeHtml(nameA)}</th><th>${escapeHtml(nameB)}</th></tr></thead>
    <tbody>${rows
      .map(([label, format]) => `<tr><td>${escapeHtml(label)}</td><td>${escapeHtml(format(baseSummary))}</td><td><strong>${escapeHtml(format(summaryA))}</strong></td><td><strong>${escapeHtml(format(summaryB))}</strong></td></tr>`)
      .join("")}</tbody>
  </table>`;
}

function escenarioMotorCompareCandidates() {
  return loadEscenarioMotorSaved().filter((entry) => entry.estado !== "aviso");
}

function renderEscenarioComparar() {
  renderScenarioDependencyNotice("escenario-comparar");
  const selectA = qs("escenarioCompararA");
  const selectB = qs("escenarioCompararB");
  const body = qs("escenarioCompararBody");
  const empty = qs("escenarioCompararEmpty");
  const layout = qs("escenarioCompararLayout");
  if (!selectA || !selectB || !body) return;

  const list = escenarioMotorCompareCandidates();
  if (list.length < 2) {
    if (empty) empty.hidden = false;
    if (layout) layout.hidden = true;
    body.innerHTML = "";
    return;
  }
  if (empty) empty.hidden = true;
  if (layout) layout.hidden = false;

  const options = list.map((entry) => `<option value="${escapeHtml(entry.id)}">${escapeHtml(entry.nombre || "Escenario")}</option>`).join("");
  if (selectA.dataset.count !== String(list.length)) {
    selectA.innerHTML = options;
    selectB.innerHTML = options;
    selectB.selectedIndex = Math.min(1, list.length - 1);
    selectA.dataset.count = String(list.length);
    selectB.dataset.count = String(list.length);
  }

  const entryA = list.find((entry) => entry.id === selectA.value) || list[0];
  const entryB = list.find((entry) => entry.id === selectB.value) || list[1];
  const baseInput = escenarioMotorBaseInput();
  const baseSummary = escenarioMotorSummaryFor(runEscenarioMotor(baseInput, [], null), baseInput.months);
  const summaryA = escenarioMotorSummaryFor(runEscenarioMotor(baseInput, entryA.decisiones || [], entryA.guardrailValue ?? null), baseInput.months);
  const summaryB = escenarioMotorSummaryFor(runEscenarioMotor(baseInput, entryB.decisiones || [], entryB.guardrailValue ?? null), baseInput.months);
  body.innerHTML = escenarioMotorCompareThreeHtml(baseSummary, summaryA, summaryB, entryA.nombre || "Escenario A", entryB.nombre || "Escenario B");
}

function handleEscenarioCompararSelect() {
  renderEscenarioComparar();
}

// ---------------------------------------------------------------------------------------------
// Comparador de estrategias + plan de deuda · ruta (mockups 1b/1c). Construidos sobre el mismo
// motor E20 (resolveEscenario) que #escenario-simular, no sobre el pipeline heredado de
// debt-liquidation-plan (DEBT_LIQUIDATION_ASSUMPTIONS, entidades hardcodeadas): cada estrategia es
// una lista de decisiones "amortizacion" (pago total, modo "optimo") sobre la cartera real
// (canonicalDebtContractRows), ordenada según el criterio de la estrategia.
//
// V3-3 · «Consolidar» como cuarta estrategia. Hasta el 10 de agosto de 2026 la pantalla declaraba
// que reunificar no se podía comparar «porque exigiría inventar unas condiciones de préstamo (TAE,
// plazo) que no existen todavía como oferta real en los datos». El diagnóstico era correcto y la
// salida también: no fabricar la oferta. Lo que faltaba era pedirla. Ahora la oferta se introduce
// —TIN, plazo y comisión de apertura— y la estrategia se simula con el mismo motor que las otras
// tres, mediante una única decisión `reunificacion`. Sin oferta introducida la tarjeta sigue sin
// dar cifras y dice qué falta: se compara una oferta real o no se compara nada.
// ---------------------------------------------------------------------------------------------
const DEBT_STRATEGY_DEFINITIONS = [
  { id: "avalancha", label: "Avalancha", desc: "Salda primero la deuda con mayor TAE." },
  { id: "bola-nieve", label: "Bola de nieve", desc: "Salda primero la deuda con menor saldo." },
  {
    id: "consolidar",
    label: "Consolidar",
    desc: "Cierra todas las deudas y las sustituye por un préstamo único con las condiciones que te ofrezcan.",
    // Las otras tres miden «coste ejecutado» = capital desembolsado para cerrar deudas. Consolidar
    // no desembolsa nada: su coste son los intereses del préstamo nuevo, que sí se pueden calcular
    // exactos a partir de la propia oferta. Cada tarjeta dice qué mide su cifra en vez de compartir
    // una etiqueta que sería falsa para una de ellas.
    costeLabel: "Intereses del nuevo préstamo",
  },
  { id: "no-tocar", label: "No tocar nada", desc: "Sigue el calendario actual de cada deuda, sin decisiones nuevas." },
];

const DEBT_STRATEGY_COSTE_LABEL = "Coste total ejecutado";

let debtStrategyReserveValue = null;
let deudaRutaSelectedStrategy = "avalancha";
// D-9: `applyE14bOffer()` escribe su resultado en #e14bStatus, que solo vive en #debt-roadmap —
// sin esto, aplicar desde la tarjeta de Ruta y que el motor bloquee (p. ej. la deuda ya tiene una
// decisión aplicada) no daría ninguna señal visible aquí. Se recuerda entre renders porque
// renderDeudaRutaOffer() reconstruye el HTML entero tras cada intento.
let deudaRutaOfferStatusMessage = "";

function debtStrategyReserveDefault() {
  const configured = Number(state?.operatingReserve || 0);
  return configured > 0 ? configured : null;
}

// El motor solo aplica guardarraíl si saldoMinimoAbsoluto > 0 (runEscenarioMotor): sin ninguno,
// "modo optimo" no comprueba nada y todas las decisiones caen en el primer mes del horizonte a la
// vez, sin importar cuánto quede la liquidez en negativo — inútil para secuenciar de verdad. Si el
// usuario no ha configurado una reserva real (ni aquí ni en Presupuesto de riesgo), se usa un suelo
// de 0 € por defecto (no permitir liquidez negativa) en vez de no comprobar nada; se etiqueta
// siempre cuál de los dos casos es, nunca se oculta.
function debtStrategyEffectiveReserve(reserveValue) {
  return Number.isFinite(reserveValue) && reserveValue > 0 ? reserveValue : 0.01;
}

function debtStrategyOrderedContracts(strategyId) {
  const contracts = escenarioMotorDebtOptions();
  if (strategyId === "avalancha") {
    return contracts.slice().sort((a, b) => (Number(b.apr) || -1) - (Number(a.apr) || -1));
  }
  if (strategyId === "bola-nieve") {
    return contracts.slice().sort((a, b) => Number(a.currentPrincipal) - Number(b.currentPrincipal));
  }
  return [];
}

// ---------------------------------------------------------------------------------------------
// V3-3 · la oferta de reunificación. Se guarda aparte del modelo del hogar (`state`) porque no es
// un dato del hogar: es una oferta de un tercero que puede caducar, cambiar o descartarse sin que
// nada de la contabilidad se mueva. Vive en el mismo almacén local que los escenarios guardados,
// con su propia clave, y persiste entre sesiones para no tener que reteclearla en cada visita.
// ---------------------------------------------------------------------------------------------
const DEBT_CONSOLIDATION_OFFER_KEY = "deuda-oferta-reunificacion";
const DEBT_CONSOLIDATION_MAX_TIN = 60;
const DEBT_CONSOLIDATION_MAX_PLAZO = 480;

function debtConsolidationOffer() {
  try {
    const parsed = JSON.parse(storageGet(storageKey(DEBT_CONSOLIDATION_OFFER_KEY), "{}"));
    if (!parsed || typeof parsed !== "object") return { tin: null, plazo: null, comision: null };
    // Ojo con el atajo `Number.isFinite(Number(value))`: `Number(null)` y `Number("")` valen 0, así
    // que un campo vacío se leería como un TIN del 0 % — una oferta sin intereses que nadie ha
    // hecho. Un hueco se distingue de un cero antes de convertir nada.
    const num = (value) => {
      if (value === null || value === undefined || value === "") return null;
      const parsedValue = Number(value);
      return Number.isFinite(parsedValue) ? parsedValue : null;
    };
    return { tin: num(parsed.tin), plazo: num(parsed.plazo), comision: num(parsed.comision) };
  } catch {
    return { tin: null, plazo: null, comision: null };
  }
}

function saveDebtConsolidationOffer(offer) {
  storageSet(storageKey(DEBT_CONSOLIDATION_OFFER_KEY), JSON.stringify(offer || {}));
}

// El TIN se acepta al 0 % (existen ofertas promocionales sin intereses) pero el plazo no: sin plazo
// no hay cuota que calcular. Los topes son los mismos que exige `canonical-scenario-schema.js` para
// `reunificacion`, comprobados aquí antes de construir la decisión para no mandar al motor algo que
// el esquema rechazaría.
function debtConsolidationOfferComplete(offer) {
  const tinOk = Number.isFinite(offer.tin) && offer.tin >= 0 && offer.tin <= DEBT_CONSOLIDATION_MAX_TIN;
  const plazoOk = Number.isFinite(offer.plazo) && Number.isInteger(offer.plazo) && offer.plazo >= 1 && offer.plazo <= DEBT_CONSOLIDATION_MAX_PLAZO;
  return tinOk && plazoOk;
}

// Cuota francesa: la misma fórmula que usa cualquier cuadro de amortización. Con TIN 0 % el límite
// de la fórmula es principal/plazo, que se calcula aparte para no dividir entre cero.
function debtConsolidationMonthlyPayment(principal, tinAnnualPct, months) {
  if (!(principal > 0) || !(months >= 1)) return null;
  const monthlyRate = Number(tinAnnualPct) / 100 / 12;
  if (!(monthlyRate > 0)) return round2(principal / months);
  return round2((principal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -months)));
}

// El plan de consolidación, o la razón exacta por la que todavía no hay ninguno. Nunca devuelve
// cifras a medias: o hay oferta y cartera suficiente, o `available: false` con un motivo que la
// pantalla enseña tal cual.
//
// El principal del préstamo nuevo es la suma de los saldos vivos más la comisión de apertura. Se
// financia la comisión (que es como se firman casi todas las reunificaciones) en vez de tratarla
// como pago en efectivo aparte: el motor no modela `comisiones` como flujo de caja —lo dice la
// cabecera de `canonical-scenario-engine.js`— así que pasarla por ese campo la haría desaparecer
// del cálculo sin avisar. Sumada al principal sí cuenta, y se dice en la pantalla.
function debtConsolidationPlan() {
  const offer = debtConsolidationOffer();
  const contracts = escenarioMotorDebtOptions();
  if (contracts.length < 2) {
    return { available: false, motivo: "cartera", offer, contracts };
  }
  if (!debtConsolidationOfferComplete(offer)) {
    return { available: false, motivo: "sin-oferta", offer, contracts };
  }
  const saldos = round2(contracts.reduce((sum, contract) => sum + Number(contract.currentPrincipal || 0), 0));
  const comision = Number.isFinite(offer.comision) && offer.comision > 0 ? round2(offer.comision) : 0;
  const principal = round2(saldos + comision);
  const cuota = debtConsolidationMonthlyPayment(principal, offer.tin, offer.plazo);
  if (!(cuota > 0)) {
    return { available: false, motivo: "sin-cuota", offer, contracts };
  }
  const totalDevuelto = round2(cuota * offer.plazo);
  return {
    available: true,
    offer,
    contracts,
    deudaIds: contracts.map((contract) => contract.id),
    saldos,
    comision,
    principal,
    cuota,
    plazo: offer.plazo,
    tin: offer.tin,
    totalDevuelto,
    intereses: round2(totalDevuelto - principal),
  };
}

function debtStrategyDecisions(strategyId) {
  if (strategyId === "consolidar") {
    const plan = debtConsolidationPlan();
    if (!plan.available) return [];
    return [
      {
        id: "deuda-estrategia-consolidar-0",
        tipo: "reunificacion",
        activa: true,
        orden: 0,
        planificacion: { modo: "optimo" },
        params: {
          deudaIds: plan.deudaIds,
          nuevoPrincipal: plan.principal,
          // El esquema quiere el TIN en fracción 0-0,60; la oferta se teclea en %.
          nuevoTIN: round2(plan.tin * 100) / 10000,
          nuevaCuota: plan.cuota,
          nuevoPlazo: plan.plazo,
        },
      },
    ];
  }
  return debtStrategyOrderedContracts(strategyId).map((contract, index) => ({
    id: `deuda-estrategia-${strategyId}-${index}`,
    tipo: "amortizacion",
    activa: true,
    orden: index,
    planificacion: { modo: "optimo" },
    params: { deudaId: contract.id, importe: Number(contract.currentPrincipal) },
  }));
}

function debtStrategyResult(strategyId, baseInput, reserveValue) {
  const decisions = debtStrategyDecisions(strategyId);
  const result = runEscenarioMotor(baseInput, decisions, debtStrategyEffectiveReserve(reserveValue));
  return { decisions, result };
}

function debtStrategySummary(strategyId, baseInput, reserveValue) {
  const { decisions, result } = debtStrategyResult(strategyId, baseInput, reserveValue);
  const consolidacion = strategyId === "consolidar" ? debtConsolidationPlan() : null;
  if (!result || !result.valid) return { decisions, result, consolidacion, libreDeDeuda: null, cajaMinima: null, costeTotal: 0, viable: false, aplicadas: 0, total: decisions.length };
  const resultadosById = new Map((result.resultados || []).map((item) => [item.id, item]));
  const aplicadas = decisions.filter((decision) => resultadosById.get(decision.id)?.resultado === "aplicada");
  // V3-3 · una reunificación no lleva `importe`: no desembolsa nada. Sumar su `params.importe`
  // daría 0 € y la haría parecer gratis frente a las demás, además de ganar cualquier empate por
  // coste en la recomendación. Su coste real —los intereses del préstamo nuevo— sale exacto de la
  // propia oferta, así que es esa cifra la que se compara, y la tarjeta dice que es eso lo que mide.
  const costeTotal = consolidacion
    ? (aplicadas.length && consolidacion.available ? consolidacion.intereses : 0)
    : aplicadas.reduce((sum, decision) => sum + Number(decision.params.importe || 0), 0);
  return {
    decisions,
    result,
    consolidacion,
    libreDeDeuda: escenarioMotorLibreDeDeuda(result.debtStateFinal, baseInput.months),
    cajaMinima: result.series.length ? Math.min(...result.series.map((row) => row.totalLiquidity)) : null,
    costeTotal: round2(costeTotal),
    viable: aplicadas.length === decisions.length,
    aplicadas: aplicadas.length,
    total: decisions.length,
  };
}

// V1-3 · «Deuda pendiente» y «Libre de deuda» para Hoy. Las dos cifras salen del mismo sitio que
// las de `#deuda-comparar` —los contratos que el motor considera accionables, `escenarioMotorDebtOptions`—
// para que Hoy y Deuda no puedan contar historias distintas sobre la misma deuda. Ojo: no coincide
// necesariamente con `debtPortfolioTotals().currentPrincipal`, que suma la cartera declarada
// incluyendo las líneas ya reunificadas; el motor las sustituye por el plan combinado sintético.
//
// Se usa «No tocar nada» a propósito. Hoy es de solo lectura y no debe insinuar una decisión que el
// usuario no ha tomado: la fecha que enseña es la de seguir el calendario actual, no la de la
// estrategia recomendada. Como esa estrategia no lleva decisiones, el guardarraíl de reserva no
// llega a evaluarse, así que la cifra tampoco depende de lo que haya escrito en la casilla del
// comparador —una pantalla no puede mover el número de otra sin querer—.
function homeDebtOutlook() {
  const key = simulationSignature || modelComputationSignature();
  if (homeDebtOutlookCache.key === key && homeDebtOutlookCache.value) return homeDebtOutlookCache.value;
  const contracts = escenarioMotorDebtOptions();
  const summary = debtStrategySummary("no-tocar", escenarioMotorBaseInput(), debtStrategyReserveDefault());
  const value = {
    pendingPrincipal: round2(contracts.reduce((sum, contract) => sum + Number(contract.currentPrincipal || 0), 0)),
    contracts: contracts.length,
    libreDeDeuda: summary.libreDeDeuda,
    libreDeDeudaLabel: escenarioMotorMonthLabel(summary.libreDeDeuda),
    estimable: /^\d{4}-\d{2}/.test(String(summary.libreDeDeuda || "")),
    settled: String(summary.libreDeDeuda || "") === "sin deuda pendiente",
  };
  homeDebtOutlookCache = { key, value };
  return value;
}

// escenarioMotorLibreDeDeuda no siempre devuelve una fecha "YYYY-MM": puede devolver "sin deuda
// pendiente", "sin fecha estimable · sin cuota activa" (nada queda con cuota activa que proyectar,
// típicamente porque esta estrategia ya saldó todo lo accionable y solo queda un registro fantasma
// sin cuota, como una reunificación histórica) o "fuera de horizonte" (sí queda cuota activa, pero
// su cierre cae más allá del horizonte modelado). Comparar estos textos como cadenas ordena mal
// ("sin..." va antes que cualquier fecha real por alfabeto, no porque sea mejor) — se traduce cada
// caso a un rango explícito antes de comparar: sin deuda pendiente/sin cuota que proyectar cuentan
// como lo mejor posible (nada más se puede acelerar), una fecha real ordena por su propio valor, y
// fuera de horizonte cuenta como lo peor (no se sabe cuándo termina).
function debtStrategyLibreDeDeudaRank(label) {
  const text = String(label || "");
  if (text === "sin deuda pendiente" || text.startsWith("sin fecha estimable")) return "0000-00";
  if (text === "fuera de horizonte") return "9999-99";
  const match = text.match(/^(\d{4}-\d{2})/);
  return match ? match[1] : "9999-98";
}

// Recomendada = la primera libre de deuda (por el rango de arriba) entre las estrategias que
// resolvieron TODAS sus decisiones (viable); en empate, la de menor coste total ejecutado. Si
// ninguna es viable, no se recomienda nada en vez de forzar una elección sobre un resultado a medias.
function debtStrategyRecommended(summaries) {
  const viable = summaries.filter((entry) => entry.viable && entry.total > 0);
  if (!viable.length) return null;
  return viable
    .slice()
    .sort((a, b) => debtStrategyLibreDeDeudaRank(a.libreDeDeuda).localeCompare(debtStrategyLibreDeDeudaRank(b.libreDeDeuda)) || a.costeTotal - b.costeTotal)
    .at(0).id;
}

function debtStrategyDecisionsToEscenario(strategyId) {
  escenarioMotorDecisions = debtStrategyDecisions(strategyId).map((decision) => ({ ...decision, id: escenarioMotorNewDecisionId() }));
  escenarioMotorGuardrailValue = debtStrategyReserveValue;
}

// ---------------------------------------------------------------------------------------------
// D-5 · los ocho modos de liquidación que solo existían en la heredada `#debt-control`
// (`debtModeLabel`/`debtPayoffMode`), migrados sobre el motor canónico en vez de reimplementados:
// son los cuatro tipos de decisión de deuda de un solo contrato que `canonical-scenario-engine.js`
// ya resuelve (`amortizacion`, `amortizacion_fraccionada`, `refinanciacion`, `retomar_pagos` —
// `reunificacion` ya vive en la estrategia «Consolidar» y `acuerdo_quita` no tenía equivalente en
// la heredada) cruzados con las dos planificaciones que el motor ya sabe resolver
// (`planificacion.modo`: óptimo busca el primer mes viable, manual usa el mes elegido). Los campos
// y el `params()`/`mes()`/`titulo()` de cada tipo son los mismos de `ESCENARIO_MOTOR_TYPES` —no hay
// un segundo constructor de decisiones de deuda— solo se les añade el interruptor óptimo/manual que
// ese catálogo no ofrece (siempre pide un mes porque es el mismo formulario para las once
// decisiones, con y sin deuda de por medio).
// D-6 · con eso ya construido, comparar «plan frente a modo» es aplicar los ocho a la vez sobre el
// contrato elegido y enseñar el resultado en una tabla, igual que las tarjetas de estrategia de
// arriba comparan avalancha/bola de nieve/consolidar/no tocar.
// ---------------------------------------------------------------------------------------------
const DEBT_MODE_DEFINITIONS = Object.freeze([
  { id: "optimize", tipoId: "amortizacion", planMode: "optimo", label: "Amortización óptima" },
  { id: "fixed", tipoId: "amortizacion", planMode: "manual", label: "Amortización manual" },
  { id: "spread-optimize", tipoId: "amortizacion_fraccionada", planMode: "optimo", label: "Fraccionada con inicio óptimo" },
  { id: "spread", tipoId: "amortizacion_fraccionada", planMode: "manual", label: "Fraccionada" },
  { id: "retomar-optimize", tipoId: "retomar_pagos", planMode: "optimo", label: "Retomar pagos con inicio óptimo" },
  { id: "retomar", tipoId: "retomar_pagos", planMode: "manual", label: "Retomar pagos" },
  { id: "refinance-optimize", tipoId: "refinanciacion", planMode: "optimo", label: "Refinanciación con inicio óptimo" },
  { id: "refinance", tipoId: "refinanciacion", planMode: "manual", label: "Refinanciación" },
]);

let debtModeContractId = null;
let debtModeId = DEBT_MODE_DEFINITIONS[0].id;
let debtModeValues = {};

function debtModeDefById(id) {
  return DEBT_MODE_DEFINITIONS.find((def) => def.id === id) || DEBT_MODE_DEFINITIONS[0];
}

function debtModeSelectedContract() {
  const contracts = escenarioMotorDebtOptions();
  return contracts.find((contract) => contract.id === debtModeContractId) || contracts[0] || null;
}

// Los campos del tipo real menos `deudaId` (lo elige el desplegable de contrato de esta pantalla,
// no el formulario de modo) y menos el mes manual cuando el modo es «óptimo» (lo busca el motor
// solo, como ya hace `debtStrategyDecisions` con avalancha/bola de nieve).
function debtModeVisibleCampos(def) {
  const type = escenarioMotorTypeById(def.tipoId);
  if (!type) return [];
  return type.campos.filter((field) => {
    if (field.key === "deudaId") return false;
    if (def.planMode === "optimo" && (field.key === "mes" || field.key === "mesInicio")) return false;
    return true;
  });
}

function debtModeDefaultValues(contract, def) {
  const principal = round2(Number(contract?.currentPrincipal || 0));
  const payment = round2(Number(contract?.currentPayment || 0));
  const firstMonth = escenarioMotorBaseInput().months[0]?.monthKey || "";
  const base = { deudaId: contract?.id || "" };
  if (def.tipoId === "amortizacion") return { ...base, importe: principal || undefined, mes: firstMonth };
  if (def.tipoId === "amortizacion_fraccionada") {
    const importeMensual = payment > 0 ? payment : principal > 0 ? round2(principal / 12) : undefined;
    const meses = importeMensual > 0 ? Math.max(1, Math.ceil(principal / importeMensual)) : undefined;
    return { ...base, importeMensual, meses, mes: firstMonth };
  }
  if (def.tipoId === "refinanciacion") return { ...base, nuevoPrincipal: principal || undefined, nuevaCuota: undefined, nuevoTIN: undefined, nuevoPlazo: undefined, mes: firstMonth };
  if (def.tipoId === "retomar_pagos") {
    // Una deuda suspendida trae `currentPayment: 0` (no hay cuota activa que leer): la cuota a
    // retomar por defecto es la original, la misma fuente que ya usaba `debtResumePlan` en la
    // heredada, no un cero que el usuario tendría que corregir a mano cada vez.
    const resumeCuota = payment > 0 ? payment : round2(Number(contract?.originalPayment || 0)) || undefined;
    return { ...base, cuota: resumeCuota, mesInicio: firstMonth };
  }
  return base;
}

// La única sugerencia que se calcula sola en vez de partir en blanco: con principal, TIN y plazo ya
// escritos, la cuota nueva sale de la misma fórmula francesa que usa «Consolidar»
// (`debtConsolidationMonthlyPayment`, genérica pese al nombre) — nunca sobrescribe lo que el usuario
// ya haya tecleado en esa casilla.
function debtModeEffectiveValues() {
  const contract = debtModeSelectedContract();
  const def = debtModeDefById(debtModeId);
  const merged = { ...debtModeDefaultValues(contract, def), ...debtModeValues, deudaId: contract?.id || "" };
  if (
    def.tipoId === "refinanciacion" &&
    !Number.isFinite(merged.nuevaCuota) &&
    Number.isFinite(merged.nuevoPrincipal) &&
    Number.isFinite(merged.nuevoTIN) &&
    Number.isFinite(merged.nuevoPlazo)
  ) {
    const computed = debtConsolidationMonthlyPayment(merged.nuevoPrincipal, merged.nuevoTIN, merged.nuevoPlazo);
    if (computed) merged.nuevaCuota = computed;
  }
  return merged;
}

// Construye la decisión sin pedirle nada al motor todavía: si falta un campo obligatorio para el
// tipo elegido (el caso normal nada más entrar en «Refinanciación», sin TIN ni plazo todavía) se
// dice que no hay nada que calcular, igual que «Consolidar» sin oferta — nunca se manda al motor un
// importe a medio escribir.
function debtModeDecisionForContract(contract, def, values) {
  const type = escenarioMotorTypeById(def?.tipoId);
  if (!type || !contract) return { available: false };
  const effectiveValues = { ...values, deudaId: contract.id };
  const requiredKeys = type.campos
    .map((field) => field.key)
    .filter((key) => key !== "parcial" && !(def.planMode === "optimo" && (key === "mes" || key === "mesInicio")));
  const missing = requiredKeys.some((key) => {
    const value = effectiveValues[key];
    return value === undefined || value === null || value === "" || (typeof value === "number" && !Number.isFinite(value));
  });
  if (missing) return { available: false };
  const mesManual = def.planMode === "manual" ? type.mes(effectiveValues) : null;
  if (def.planMode === "manual" && !mesManual) return { available: false };
  const params = type.params(effectiveValues);
  // `retomar_pagos` exige `mesInicio` en sus params incluso en modo óptimo: el motor lo sustituye
  // por cada mes candidato al buscar (`withResolvedMonth` en canonical-scenario-engine.js), pero el
  // valor de partida tiene que existir para que el objeto sea válido antes de esa búsqueda.
  if (def.tipoId === "retomar_pagos" && def.planMode === "optimo") {
    params.mesInicio = escenarioMotorBaseInput().months[0]?.monthKey || "";
  }
  const planificacion = def.planMode === "optimo" ? { modo: "optimo" } : { modo: "manual", mesManual };
  return {
    available: true,
    decision: {
      id: escenarioMotorNewDecisionId(),
      tipo: def.tipoId,
      titulo: escenarioMotorTrim(type.titulo(effectiveValues, { debtLabel: escenarioMotorDebtLabelById }) || type.label),
      activa: true,
      orden: 0,
      planificacion,
      params,
    },
  };
}

// Punto único que consultan tanto el panel de resultado del modo activo como cada fila de la
// comparativa de los ocho: mismas tres razones de "no disponible" en los dos sitios (sin motor
// cargado, retomar sobre una deuda que no está suspendida, o faltan datos), nunca un cálculo
// distinto según desde dónde se mire.
function debtModeResultForContract(contract, def, values, baseInput, reserveValue) {
  if (missingScenarioDependencies().length) return { available: false, reason: "sin-motor" };
  if (def.tipoId === "retomar_pagos" && contract && contract.paymentStatus !== "suspended") {
    return { available: false, reason: "no-suspendida" };
  }
  const built = debtModeDecisionForContract(contract, def, values);
  if (!built.available) return { available: false, reason: "faltan-datos" };
  const result = runEscenarioMotor(baseInput, [built.decision], debtStrategyEffectiveReserve(reserveValue));
  if (!result || !result.valid) return { available: false, reason: "sin-motor" };
  const resultado = (result.resultados || [])[0] || null;
  const cajaMinima = result.series?.length ? Math.min(...result.series.map((row) => row.totalLiquidity)) : null;
  return {
    available: true,
    decision: built.decision,
    resultado,
    cajaMinima,
    viable: resultado?.resultado === "aplicada",
    mesResuelto: resultado?.mesResuelto || null,
  };
}

function debtModeUnavailableNote(contract, result) {
  if (result.reason === "sin-motor") return "No se puede simular: falta el motor de Escenario.";
  if (result.reason === "no-suspendida") return `Retomar pagos solo aplica a una deuda con los pagos suspendidos; ${escenarioMotorDebtLabel(contract)} no lo está.`;
  return "Faltan datos para simular este modo: complétalos arriba.";
}

function debtModeContractOptionsHtml(contracts, selectedId) {
  return contracts
    .map((contract) => `<option value="${escapeHtml(contract.id)}"${contract.id === selectedId ? " selected" : ""}>${escapeHtml(escenarioMotorDebtLabel(contract))} · ${money(contract.currentPrincipal, true)}</option>`)
    .join("");
}

function renderDeudaCompararModes() {
  const contractSelect = qs("deudaCompararModeContract");
  const modeSelect = qs("deudaCompararModeSelect");
  const fieldsBox = qs("deudaCompararModeFields");
  const resultBox = qs("deudaCompararModeResult");
  const compareBody = qs("deudaCompararModeCompareBody");
  const applyButton = qs("deudaCompararModeApply");
  if (!contractSelect || !modeSelect || !fieldsBox || !resultBox) return;

  const contracts = escenarioMotorDebtOptions();
  if (!contracts.length) {
    contractSelect.innerHTML = '<option value="">Sin deudas vivas</option>';
    modeSelect.innerHTML = "";
    fieldsBox.innerHTML = "";
    resultBox.innerHTML = '<p class="e19-kpi-note">Sin deudas vivas: no hay ningún contrato al que aplicar un modo.</p>';
    if (compareBody) compareBody.innerHTML = "";
    if (applyButton) applyButton.disabled = true;
    return;
  }
  if (!debtModeContractId || !contracts.some((contract) => contract.id === debtModeContractId)) {
    debtModeContractId = contracts[0].id;
  }
  const contract = debtModeSelectedContract();
  const def = debtModeDefById(debtModeId);

  if (document.activeElement !== contractSelect) contractSelect.innerHTML = debtModeContractOptionsHtml(contracts, debtModeContractId);
  if (!modeSelect.childElementCount) {
    modeSelect.innerHTML = DEBT_MODE_DEFINITIONS.map((item) => `<option value="${escapeHtml(item.id)}">${escapeHtml(item.label)}</option>`).join("");
  }
  if (document.activeElement !== modeSelect) modeSelect.value = debtModeId;

  const baseInput = escenarioMotorBaseInput();
  if (!fieldsBox.contains(document.activeElement)) {
    const campos = debtModeVisibleCampos(def);
    const values = debtModeEffectiveValues();
    fieldsBox.innerHTML = campos
      .map((field) =>
        escenarioMotorFieldHtml(field, baseInput.months, values, {
          idPrefix: "debtModeField",
          dataAttr: "data-debt-mode-field",
          wrapAttr: "data-debt-mode-field-wrap",
        })
      )
      .join("");
  }

  const reserveValue = debtStrategyReserveValue;
  const activeResult = debtModeResultForContract(contract, def, debtModeEffectiveValues(), baseInput, reserveValue);
  if (!activeResult.available) {
    resultBox.innerHTML = `<p class="e19-kpi-note is-warn">${escapeHtml(debtModeUnavailableNote(contract, activeResult))}</p>`;
    if (applyButton) applyButton.disabled = true;
  } else {
    const info = escenarioMotorResultInfo(activeResult.resultado?.resultado);
    resultBox.innerHTML = `
      <div><span>Mes resuelto</span><strong>${escapeHtml(activeResult.mesResuelto ? escenarioMotorMonthLabel(activeResult.mesResuelto) : "—")}</strong></div>
      <div><span>Coste</span><strong>${escapeHtml(escenarioMotorDecisionAmountText(activeResult.decision))}</strong></div>
      <div><span>Caja mínima</span><strong>${money(activeResult.cajaMinima ?? 0, true)}</strong></div>
      <div><span>Resultado</span><strong><span class="e19-badge ${info.badge}">${escapeHtml(info.text)}</span></strong></div>
    `;
    if (applyButton) applyButton.disabled = !activeResult.viable;
  }

  // D-6 · los ocho a la vez sobre el mismo contrato. El modo activo usa sus valores editados en el
  // formulario de arriba (para que la fila se mueva mientras se teclea); el resto usa sus propios
  // valores por defecto, nunca los del modo activo — mezclar importes de un modo en otro daría una
  // comparación que no es la que cada modo ofrecería por sí solo.
  if (compareBody) {
    const planBaseline = debtModePlanBaseline(baseInput, reserveValue);
    const rows = DEBT_MODE_DEFINITIONS.map((item) => {
      const itemValues = item.id === debtModeId ? debtModeEffectiveValues() : debtModeDefaultValues(contract, item);
      const itemResult = debtModeResultForContract(contract, item, itemValues, baseInput, reserveValue);
      return { item, itemResult };
    });
    compareBody.innerHTML = rows
      .map(({ item, itemResult }) => {
        const rowClass = item.id === debtModeId ? ' class="is-active"' : "";
        if (!itemResult.available) {
          return `<tr${rowClass} data-deuda-comparar-mode-row="${escapeHtml(item.id)}">
            <td>${escapeHtml(item.label)}</td>
            <td colspan="5">${escapeHtml(debtModeUnavailableNote(contract, itemResult))}</td>
            <td><button type="button" class="e19-btn e19-btn-secondary" data-deuda-comparar-mode-usar="${escapeHtml(item.id)}">Usar</button></td>
          </tr>`;
        }
        return `<tr${rowClass} data-deuda-comparar-mode-row="${escapeHtml(item.id)}">
          <td>${escapeHtml(item.label)}</td>
          ${debtModeIndicatorsHtml(item, itemResult, contract, planBaseline)}
          <td><button type="button" class="e19-btn e19-btn-secondary" data-deuda-comparar-mode-usar="${escapeHtml(item.id)}">Usar</button></td>
        </tr>`;
      })
      .join("");
    renderDeudaCompararModeInsight(rows, contract);
  }
}

// D-6: "el plan" es el escenario sin ninguna decisión de deuda — el mismo concepto que "no tocar
// nada" ya usa la comparativa de las cuatro estrategias, aplicado aquí a los ocho modos de un solo
// contrato. Caja mínima es la única cifra directamente comparable contra ese plan (coste y cuota
// del plan son cero/las declaradas por definición, así que se colorean contra el propio contrato:
// coste frente al principal pendiente, cuota resultante frente a la cuota actual).
function debtModePlanBaseline(baseInput, reserveValue) {
  const result = runEscenarioMotor(baseInput, [], debtStrategyEffectiveReserve(reserveValue));
  if (!result || !result.valid) return null;
  const cajaMinima = result.series?.length ? Math.min(...result.series.map((row) => row.totalLiquidity)) : null;
  return { cajaMinima };
}

// La cuota que queda tras cada modo depende del tipo: una amortización única salda del todo (cuota
// futura: 0), refinanciar y retomar pagos declaran su propia cuota nueva, y la fraccionada añade un
// extra mensual sin tocar la cuota declarada del contrato (por eso devuelve la misma, no null: sigue
// siendo una cifra real y comparable, solo que no cambia con este modo).
function debtModeResultingPayment(def, itemResult, contract) {
  const params = itemResult.decision?.params || {};
  if (def.tipoId === "amortizacion") return 0;
  if (def.tipoId === "refinanciacion") return Number.isFinite(Number(params.nuevaCuota)) ? Number(params.nuevaCuota) : null;
  if (def.tipoId === "retomar_pagos") return Number.isFinite(Number(params.cuota)) ? Number(params.cuota) : null;
  if (def.tipoId === "amortizacion_fraccionada") return round2(Number(contract?.currentPayment || 0));
  return null;
}

function debtModeCosteNumeric(def, itemResult) {
  const params = itemResult.decision?.params || {};
  if (def.tipoId === "amortizacion") return round2(Number(params.importe || 0));
  if (def.tipoId === "amortizacion_fraccionada") return round2(Number(params.importeMensual || 0) * Number(params.meses || 0));
  if (def.tipoId === "refinanciacion") return round2(Number(params.nuevoPrincipal || 0));
  if (def.tipoId === "retomar_pagos") return round2(Number(params.cuota || 0));
  return 0;
}

function debtCompareToneClass(comparison) {
  return comparison === "mejor" ? "positive" : comparison === "peor" ? "negative" : "";
}

// Cinco indicadores del criterio: mes resuelto, caja mínima (vs el plan sin decisión), coste (vs el
// principal pendiente: pagar menos que la deuda entera es la única forma honesta de "mejor" sin
// inventar un coste de referencia para el plan, que por definición es cero), cuota resultante (vs
// la cuota actual) y el resultado viable/no viable.
function debtModeIndicatorsHtml(item, itemResult, contract, planBaseline) {
  const info = escenarioMotorResultInfo(itemResult.resultado?.resultado);
  const cajaComparison = planBaseline?.cajaMinima === null || planBaseline?.cajaMinima === undefined
    ? ""
    : (itemResult.cajaMinima ?? 0) >= planBaseline.cajaMinima
      ? "mejor"
      : "peor";
  const principal = Number(contract?.currentPrincipal || 0);
  const coste = debtModeCosteNumeric(item, itemResult);
  const costeComparison = principal > 0 ? (coste < principal ? "mejor" : "peor") : "";
  const cuotaActual = Number(contract?.currentPayment || 0);
  const cuotaResultante = debtModeResultingPayment(item, itemResult, contract);
  const cuotaComparison = cuotaResultante === null ? "" : cuotaResultante < cuotaActual ? "mejor" : cuotaResultante > cuotaActual ? "peor" : "";
  return `
    <td>${escapeHtml(itemResult.mesResuelto ? escenarioMotorMonthLabel(itemResult.mesResuelto) : "—")}</td>
    <td class="${debtCompareToneClass(cajaComparison)}">${money(itemResult.cajaMinima ?? 0, true)}</td>
    <td class="${debtCompareToneClass(costeComparison)}">${money(coste, true)}</td>
    <td class="${debtCompareToneClass(cuotaComparison)}">${cuotaResultante === null ? "—" : money(cuotaResultante, true)}</td>
    <td><span class="e19-badge ${info.badge}">${escapeHtml(info.text)}</span></td>
  `;
}

// D-6: veredicto en prosa que nombra el supuesto principal — mismo patrón que deudaCompararInsight
// para las estrategias, aplicado al modo con mejor caja mínima entre los viables de este contrato.
function renderDeudaCompararModeInsight(rows, contract) {
  const insight = qs("deudaCompararModeInsight");
  if (!insight) return;
  const viable = rows.filter(({ itemResult }) => itemResult.available && itemResult.viable);
  if (!viable.length || !contract) {
    insight.hidden = true;
    return;
  }
  const best = viable.reduce((top, current) => ((current.itemResult.cajaMinima ?? -Infinity) > (top.itemResult.cajaMinima ?? -Infinity) ? current : top));
  insight.hidden = false;
  insight.innerHTML = `<strong>${escapeHtml(best.item.label)} deja la mejor caja mínima para ${escapeHtml(escenarioMotorDebtLabel(contract))}</strong>
    <p>Caja mínima de ${money(best.itemResult.cajaMinima ?? 0, true)}, resuelta en ${escapeHtml(best.itemResult.mesResuelto ? escenarioMotorMonthLabel(best.itemResult.mesResuelto) : "—")}. Supuesto principal: TIN, cuota y plazo son los declarados en el contrato o los que se hayan escrito arriba — cambiarlos cambia esta comparación.</p>`;
}

function handleDeudaCompararModeContractChange(event) {
  debtModeContractId = event.target.value;
  debtModeValues = {};
  renderDeudaCompararModes();
}

function handleDeudaCompararModeSelectChange(event) {
  debtModeId = event.target.value;
  debtModeValues = {};
  renderDeudaCompararModes();
}

function handleDeudaCompararModeFieldChange(event) {
  const key = event.target?.dataset?.debtModeField;
  if (!key) return;
  const def = debtModeDefById(debtModeId);
  const type = escenarioMotorTypeById(def.tipoId);
  const field = type?.campos.find((item) => item.key === key);
  if (!field) return;
  debtModeValues[key] = escenarioMotorReadFieldValue(field, event.target);
  renderDeudaCompararModes();
}

function handleDeudaCompararModeCompareClick(event) {
  const button = event.target.closest("[data-deuda-comparar-mode-usar]");
  if (!button) return;
  debtModeId = button.dataset.deudaCompararModeUsar;
  debtModeValues = {};
  renderDeudaCompararModes();
}

function handleDeudaCompararModeApply() {
  const contract = debtModeSelectedContract();
  const def = debtModeDefById(debtModeId);
  const result = debtModeResultForContract(contract, def, debtModeEffectiveValues(), escenarioMotorBaseInput(), debtStrategyReserveValue);
  if (!result.available || !result.viable) return;
  escenarioMotorDecisions = [{ ...result.decision, id: escenarioMotorNewDecisionId() }];
  escenarioMotorGuardrailValue = debtStrategyReserveValue;
  escenarioMotorNavigate("escenario-aplicar");
}

// La nota al pie de cada tarjeta. Es el único sitio donde se explica por qué una estrategia no
// tiene cifras, así que nunca se queda en blanco cuando falta algo: o dice qué falta, o dice qué
// hace la estrategia, o no dice nada porque no hay nada que advertir.
function debtStrategyStatusNote(entry) {
  if (entry.id === "consolidar") {
    const plan = entry.consolidacion;
    if (!plan || !plan.available) {
      if (plan?.motivo === "cartera") {
        return `Reunificar exige al menos dos deudas vivas; ahora mismo el motor ve ${plan.contracts.length}.`;
      }
      return "Falta la oferta: escribe arriba el TIN y el plazo que te ofrecen y esta estrategia se simula como las otras tres.";
    }
    if (!entry.viable) return "Con esta oferta no hay ningún mes del horizonte en que la reunificación respete la reserva mínima.";
    return `Sustituye ${plan.contracts.length} deudas por un préstamo de ${money(plan.principal, true)} a ${plan.plazo} meses: ${money(plan.cuota, true)} al mes. No exige desembolso.`;
  }
  if (entry.total === 0) return "Referencia: nada cambia.";
  if (entry.viable) return "";
  return `${entry.aplicadas}/${entry.total} decisiones viables en este horizonte.`;
}

function renderDeudaComparar() {
  renderDeudaScreenTabs("deuda-comparar");
  renderScenarioDependencyNotice("deuda-comparar");
  const grid = qs("deudaCompararGrid");
  if (!grid) return;
  const reserveField = qs("deudaCompararReserve");
  if (debtStrategyReserveValue === null) debtStrategyReserveValue = debtStrategyReserveDefault();
  if (reserveField && document.activeElement !== reserveField) reserveField.value = debtStrategyReserveValue ?? "";
  renderDeudaCompararReserveNote();
  renderDeudaCompararOffer();
  renderDeudaCompararModes();

  const baseInput = escenarioMotorBaseInput();
  const summaries = DEBT_STRATEGY_DEFINITIONS.map((def) => ({ id: def.id, def, ...debtStrategySummary(def.id, baseInput, debtStrategyReserveValue) }));
  const recommendedId = debtStrategyRecommended(summaries);
  // T-5 · sin motor, `costeTotal` y `cajaMinima` valen 0 porque no se ha calculado nada, y «0,00 €»
  // se lee como una respuesta. Junto al aviso rojo sería además contradictorio: se escribe «—».
  const calculado = !missingScenarioDependencies().length;
  const cifra = (value) => (calculado ? money(value ?? 0, true) : "—");

  grid.innerHTML = summaries
    .map((entry) => {
      const isRecommended = entry.id === recommendedId;
      const statusNote = debtStrategyStatusNote(entry);
      // V3-3 · «Consolidar» sin oferta no es una estrategia sin cifras: es una estrategia que no se
      // ha podido simular. Sus KPI se escriben «—» por la misma razón que en modo degradado (T-5):
      // un «0,00 €» ahí se leería como un resultado calculado.
      const sinCalcular = entry.id === "consolidar" && entry.consolidacion && !entry.consolidacion.available;
      const kpi = (value) => (sinCalcular ? "—" : cifra(value));
      return `<article class="e19-card deuda-decidir-strategy-card${isRecommended ? " is-recommended" : ""}">
        ${isRecommended ? '<span class="e19-badge e19-badge-success deuda-decidir-strategy-flag">Recomendada</span>' : ""}
        <h3>${escapeHtml(entry.def.label)}</h3>
        <p class="e19-kpi-note">${escapeHtml(entry.def.desc)}</p>
        <div class="deuda-decidir-strategy-kpis">
          <div><span>Libre de deuda</span><strong>${escapeHtml(sinCalcular ? "—" : escenarioMotorMonthLabel(entry.libreDeDeuda))}</strong></div>
          <div><span>${escapeHtml(entry.def.costeLabel || DEBT_STRATEGY_COSTE_LABEL)}</span><strong>${kpi(entry.costeTotal)}</strong></div>
          <div><span>Caja mínima</span><strong>${kpi(entry.cajaMinima)}</strong></div>
        </div>
        ${statusNote ? `<p class="e19-kpi-note ${entry.viable && entry.total > 0 ? "" : "is-warn"}">${escapeHtml(statusNote)}</p>` : ""}
        <div class="deuda-decidir-strategy-actions">
          <button type="button" class="e19-btn e19-btn-secondary" data-deuda-comparar-ruta="${escapeHtml(entry.id)}">Ver ruta</button>
          ${isRecommended ? `<button type="button" class="e19-btn e19-btn-primary" data-deuda-comparar-aplicar="${escapeHtml(entry.id)}">Aplicar la recomendada</button>` : ""}
        </div>
      </article>`;
    })
    .join("");

  const insight = qs("deudaCompararInsight");
  const noTouch = summaries.find((entry) => entry.id === "no-tocar");
  const recommended = summaries.find((entry) => entry.id === recommendedId);
  if (insight) {
    if (recommended && noTouch && recommended.id !== "no-tocar") {
      const costeDelta = round2(noTouch.costeTotal - recommended.costeTotal);
      insight.hidden = false;
      insight.innerHTML = `<strong>${escapeHtml(recommended.def.label)} sale mejor que no tocar nada</strong>
        <p>Libre de deuda con ${escapeHtml(recommended.def.label.toLowerCase())}: ${escapeHtml(escenarioMotorMonthLabel(recommended.libreDeDeuda))} (sin tocar nada: ${escapeHtml(escenarioMotorMonthLabel(noTouch.libreDeDeuda))})${costeDelta ? `, con ${money(Math.abs(costeDelta), true)} ${costeDelta >= 0 ? "menos" : "más"} de coste ejecutado` : ""}.</p>`;
    } else {
      insight.hidden = true;
    }
  }
}

// V6-1 · de dónde sale la cifra que hay en la casilla: de la reserva operativa del hogar, de un
// valor escrito solo para esta comparación, o de nada. Se dice cuál de los tres, nunca se supone.
function renderDeudaCompararReserveNote() {
  const note = qs("deudaCompararReserveNote");
  if (!note) return;
  const household = cuadroMandosReserve();
  if (Number.isFinite(debtStrategyReserveValue) && household > 0 && round2(debtStrategyReserveValue) === round2(household)) {
    note.textContent = `Es tu reserva operativa (${money(household, true)}). Cámbiala aquí solo para esta comparación.`;
    return;
  }
  if (Number.isFinite(debtStrategyReserveValue)) {
    note.textContent = household > 0
      ? `Solo para esta comparación. Tu reserva operativa es ${money(household, true)}.`
      : "Solo para esta comparación: no se guarda como reserva del hogar.";
    return;
  }
  note.textContent = household > 0
    ? `Vacío usa un suelo de 0 €. Tu reserva operativa es ${money(household, true)}.`
    : "Sin reserva operativa configurada: se secuencia con un suelo de 0 €. Puedes fijarla en Ajustes.";
}

// V3-3 · las tres casillas de la oferta y la nota que dice qué se está comparando. La nota no
// repite lo que ya está escrito en las casillas: dice de qué se compone el principal —que es lo
// único que el usuario no teclea y podría malinterpretar— y qué pasa con la comisión.
function renderDeudaCompararOffer() {
  const offer = debtConsolidationOffer();
  const fields = [
    ["deudaCompararOfferTin", offer.tin],
    ["deudaCompararOfferPlazo", offer.plazo],
    ["deudaCompararOfferComision", offer.comision],
  ];
  fields.forEach(([id, value]) => {
    const field = qs(id);
    if (field && document.activeElement !== field) field.value = Number.isFinite(value) ? value : "";
  });

  const note = qs("deudaCompararOfferNote");
  if (!note) return;
  const plan = debtConsolidationPlan();
  if (plan.motivo === "cartera") {
    note.textContent = `Con ${plan.contracts.length} deuda(s) viva(s) no hay nada que reunificar: hacen falta al menos dos.`;
    return;
  }
  if (!plan.available) {
    note.textContent = "Sin TIN y plazo no se puede calcular la cuota, así que «Consolidar» no se compara. La comisión es opcional.";
    return;
  }
  const comisionTexto = plan.comision > 0
    ? ` (${money(plan.saldos, true)} de saldos + ${money(plan.comision, true)} de comisión, financiada dentro del préstamo)`
    : "";
  note.textContent = `Principal del préstamo nuevo: ${money(plan.principal, true)}${comisionTexto}. Devolverías ${money(plan.totalDevuelto, true)} en total, ${money(plan.intereses, true)} de intereses.`;
}

function handleDeudaCompararOfferInput() {
  const read = (id, { entero = false } = {}) => {
    const raw = (qs(id)?.value ?? "").trim();
    if (raw === "") return null;
    const value = Number(raw);
    if (!Number.isFinite(value) || value < 0) return null;
    return entero ? Math.round(value) : value;
  };
  saveDebtConsolidationOffer({
    tin: read("deudaCompararOfferTin"),
    plazo: read("deudaCompararOfferPlazo", { entero: true }),
    comision: read("deudaCompararOfferComision"),
  });
  renderDeudaComparar();
}

function handleDeudaCompararOfferClear() {
  saveDebtConsolidationOffer({ tin: null, plazo: null, comision: null });
  ["deudaCompararOfferTin", "deudaCompararOfferPlazo", "deudaCompararOfferComision"].forEach((id) => {
    const field = qs(id);
    if (field) field.value = "";
  });
  renderDeudaComparar();
  announceStatus("Oferta de reunificación borrada. «Consolidar» vuelve a quedarse sin cifras.");
}

function handleDeudaCompararReserveInput(event) {
  const value = Number(event.target.value);
  debtStrategyReserveValue = Number.isFinite(value) && value > 0 ? value : null;
  renderDeudaComparar();
}

function handleDeudaCompararVerRuta(strategyId) {
  deudaRutaSelectedStrategy = strategyId;
  escenarioMotorNavigate("deuda-ruta");
}

function handleDeudaCompararAplicar(strategyId) {
  debtStrategyDecisionsToEscenario(strategyId);
  escenarioMotorNavigate("escenario-aplicar");
}

// Deuda viva = principal pendiente de los contratos que la ruta todavía no ha resuelto en firme
// ("aplicada"). Como cada decisión es un pago total, es una función escalón exacta a partir de
// mesResuelto — no una aproximación de calendario de amortización mes a mes.
function buildDeudaVivaSeries(months, contracts, decisions, resultadosById) {
  const payoffMonthByDebt = new Map();
  // V3-3 · una reunificación no borra deuda: cierra varias y abre una. Si solo se descontaran las
  // cerradas, la gráfica enseñaría la deuda cayendo a cero el mes de la firma, que es exactamente
  // la mentira que hace atractiva a la reunificación. El préstamo nuevo entra en la serie con su
  // principal desde el mes en que se firma y sigue ahí hasta que se agota su plazo — la misma
  // función escalón que se usa para las demás, con la misma simplificación declarada.
  const prestamosNuevos = [];
  decisions.forEach((decision) => {
    const resultado = resultadosById.get(decision.id);
    if (resultado?.resultado !== "aplicada" || !resultado.mesResuelto) return;
    if (decision.tipo === "reunificacion") {
      (decision.params.deudaIds || []).forEach((deudaId) => payoffMonthByDebt.set(deudaId, resultado.mesResuelto));
      const startIndex = months.findIndex((month) => month.monthKey === resultado.mesResuelto);
      const lastIndex = startIndex < 0 ? -1 : startIndex + Math.max(1, Math.floor(Number(decision.params.nuevoPlazo) || 0)) - 1;
      prestamosNuevos.push({
        desde: resultado.mesResuelto,
        // Sin mes de cierre dentro del horizonte, el préstamo sigue vivo hasta el final del tramo
        // dibujado: se dice con `null`, no se inventa un cierre que no se ha calculado.
        hasta: lastIndex >= 0 && lastIndex < months.length ? months[lastIndex].monthKey : null,
        principal: Number(decision.params.nuevoPrincipal) || 0,
      });
      return;
    }
    payoffMonthByDebt.set(decision.params.deudaId, resultado.mesResuelto);
  });
  return months.map((month) => {
    const total = contracts.reduce((sum, contract) => {
      const payoffMonth = payoffMonthByDebt.get(contract.id);
      const alreadySettled = payoffMonth && payoffMonth <= month.monthKey;
      return alreadySettled ? sum : sum + Number(contract.currentPrincipal || 0);
    }, 0);
    const nuevos = prestamosNuevos.reduce((sum, prestamo) => {
      const vigente = prestamo.desde <= month.monthKey && (!prestamo.hasta || month.monthKey <= prestamo.hasta);
      return vigente ? sum + prestamo.principal : sum;
    }, 0);
    return { monthKey: month.monthKey, deudaViva: round2(total + nuevos) };
  });
}

// El horizonte completo del motor (hasta 10 años) hace que la liquidez proyectada crezca muy por
// encima del principal de deuda, que solo importa en los primeros años: en una escala compartida la
// deuda queda aplastada en un hilo casi invisible. Se recorta la ventana a los últimos 6 meses tras
// saldarse la última deuda (o 36 meses si nunca llega a saldarse del todo en este horizonte), igual
// que el mockup solo muestra ~3 años en vez de los 10 completos.
function deudaRutaChartWindow(deudaSeries, liquidezSeries, months) {
  const lastAliveIndex = deudaSeries.reduce((last, row, index) => (row.deudaViva > 0 ? index : last), -1);
  const end = lastAliveIndex === -1 ? Math.min(months.length, 36) : Math.min(months.length, lastAliveIndex + 7);
  return { deudaSeries: deudaSeries.slice(0, end), liquidezSeries: liquidezSeries.slice(0, end), months: months.slice(0, end) };
}

function renderDeudaRutaChart(deudaSeries, liquidezSeries, months) {
  const svg = qs("deudaRutaChart");
  if (!svg || !deudaSeries.length) return;
  const width = svg.clientWidth || 640;
  const height = 200;
  const pad = { left: 60, right: 16, top: 16, bottom: 26 };
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
  svg.innerHTML = "";

  const values = [...deudaSeries.map((row) => row.deudaViva), ...liquidezSeries.map((row) => row.totalLiquidity)];
  const minV = Math.min(...values, 0);
  const maxV = Math.max(...values, 1);
  const plotW = width - pad.left - pad.right;
  const plotH = height - pad.top - pad.bottom;
  const n = deudaSeries.length;
  const x = (i) => pad.left + (n <= 1 ? 0 : (i / (n - 1)) * plotW);
  const y = (value) => pad.top + plotH - ((value - minV) / Math.max(1, maxV - minV)) * plotH;

  const deudaLine = deudaSeries.map((row, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(2)} ${y(row.deudaViva).toFixed(2)}`).join(" ");
  const deudaArea = `${deudaLine} L ${x(n - 1).toFixed(2)} ${(pad.top + plotH).toFixed(2)} L ${x(0).toFixed(2)} ${(pad.top + plotH).toFixed(2)} Z`;
  const liquidezLine = liquidezSeries.map((row, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(2)} ${y(row.totalLiquidity).toFixed(2)}`).join(" ");

  let markup = `<path class="chart-area-deuda" d="${deudaArea}" />`;
  markup += `<path class="chart-line-deuda" d="${deudaLine}" />`;
  markup += `<path class="chart-line-liquidez" d="${liquidezLine}" />`;
  projectChartTickIndexes(months, width).forEach((idx) => {
    markup += `<text class="chart-label" x="${(x(idx) - 14).toFixed(2)}" y="${height - 6}">${escapeHtml(months[idx]?.month || "")}</text>`;
  });
  svg.insertAdjacentHTML("beforeend", markup);
}

// Una ruta vacía puede serlo por dos motivos muy distintos: porque la estrategia no propone nada
// («No tocar nada») o porque no se ha podido construir («Consolidar» sin oferta). Decir «sin
// decisiones» en los dos casos dejaría al usuario sin saber que le falta teclear algo.
function deudaRutaEmptyTimelineText(summary) {
  const plan = summary.consolidacion;
  if (plan && !plan.available) {
    return plan.motivo === "cartera"
      ? `Reunificar exige al menos dos deudas vivas; ahora mismo el motor ve ${plan.contracts.length}.`
      : "Sin la oferta de reunificación (TIN y plazo) no hay ruta que dibujar: se introduce en «Comparar estrategias».";
  }
  return "Sin decisiones: la deuda sigue su calendario actual.";
}

// D-9: los mismos cuatro requisitos que ya exige `E14DebtOperations.prepareApplication` antes de
// aceptar una aplicación — esta lista es solo su vista previa, no una segunda validación con
// criterio propio. El motivo no se comprueba aquí: lo exige el propio diálogo de confirmación al
// aplicar (`requestOperationConfirmation`), así que queda como nota informativa, no bloqueante.
function deudaRutaOfferChecklist(offer, simulation, reserve) {
  const requiredDocuments = E14DebtOperations?.REQUIRED_DOCUMENTS || [];
  const missingDocuments = requiredDocuments.filter((doc) => !(offer?.documents || []).includes(doc));
  const reserveSafe = simulation ? simulation.minimumLiquidity >= reserve : null;
  return [
    {
      ok: offer?.status === "accepted",
      label: offer?.status === "accepted" ? "Oferta registrada con sus condiciones" : "La oferta todavía no está marcada como aceptada",
    },
    {
      ok: requiredDocuments.length ? !missingDocuments.length : null,
      label: `Documentos: ${requiredDocuments.length - missingDocuments.length} de ${requiredDocuments.length || 3}`,
    },
    {
      ok: reserveSafe,
      label:
        reserveSafe === null
          ? "Reserva: sin poder calcular todavía"
          : reserveSafe
            ? "Reserva protegida tras aplicar"
            : "La reserva quedaría bajo el mínimo tras aplicar",
    },
    { ok: null, label: "Motivo de la decisión — se pide al confirmar" },
  ];
}

// V3-4 · la «oferta en curso» del mockup 4d vivía solo en #asesor-decision; esta tarjeta la trae a
// la propia vista de Deuda, reutilizando asesorDecisionOpenOffers() y asesorDecisionFundingHtml()
// tal cual — mismos datos, sin recalcular nada.
// D-8/D-9 (15 de agosto, sesión de seguimiento de la auditoría): la tarjeta dejó de enrutar a
// #debt-roadmap para "revisar y aplicar" — aplica in situ llamando a applyE14bOffer(), la misma
// puerta de escritura que ya usaba esa pantalla (regla transversal 01), tras seleccionar la oferta
// en el workspace de E14b (mismo gesto que ya hacía este botón). El enlace a #debt-roadmap se
// conserva como «Ver documentos y editar oferta», para completar o corregir la oferta antes de
// aplicar.
function renderDeudaRutaOffer() {
  const target = qs("deudaRutaOffer");
  if (!target) return;
  const offer = asesorDecisionOpenOffers()[0];
  if (!offer) {
    target.innerHTML = `<p class="e19-kpi-note">Sin ofertas de deuda abiertas ahora mismo.</p>`;
    return;
  }
  const contract = debtTargetById(offer.contractId, { includePlanned: true });
  const forecast = e14bForecast();
  const reserve = Math.max(0, Number(agentCaixaFloor?.() || 0));
  const simulation = forecast && E14DebtOperations ? E14DebtOperations.simulateStrategy(e14bStrategyForOffer(offer), forecast) : null;
  const checks = deudaRutaOfferChecklist(offer, simulation, reserve);
  // La deuda ya decidida no es uno de los cuatro requisitos del mockup — es un conflicto de estado
  // aparte, pero igual de bloqueante: sin esto el botón saldría habilitado y `applyE14bOffer()`
  // fallaría en silencio (su aviso vive en #e14bStatus, dentro de #debt-roadmap, invisible aquí).
  const alreadyDecided = debtLiquidations.some((item) => item.targetId === offer.contractId);
  const blocked = alreadyDecided || checks.some((check) => check.ok === false);
  target.innerHTML = `
    <p class="asesor-decision-subtitle"><strong>${escapeHtml(offer.counterpart || "Sin contraparte")}</strong>${contract ? ` · ${escapeHtml(contract.entity)}${contract.type ? ` ${escapeHtml(contract.type)}` : ""}` : ""}${offer.expiresAt ? ` · vence ${escapeHtml(escenarioMotorMonthLabel(offer.expiresAt))}` : ""}</p>
    <div class="asesor-decision-stats">
      <div class="asesor-decision-stat"><span>Importe</span><strong>${money(offer.amount, true)}</strong></div>
      <div class="asesor-decision-stat"><span>Ahorras</span><strong>${money(offer.discount, true)}</strong></div>
    </div>
    <div class="asesor-decision-funding">${asesorDecisionFundingHtml(offer.amount)}</div>
    <p class="panel-kicker">Requisitos para aplicar</p>
    <ul class="deuda-ruta-checklist" id="deudaRutaOfferChecklist">${checks
      .map((check) => `<li class="deuda-ruta-check${check.ok === false ? " is-danger" : check.ok === null ? " is-neutral" : " is-ok"}">${escapeHtml(check.label)}</li>`)
      .join("")}</ul>
    ${alreadyDecided ? `<p class="e19-kpi-note is-danger">Esta deuda ya tiene una decisión aplicada — revísala o deshazla antes de aplicar otra.</p>` : ""}
    ${deudaRutaOfferStatusMessage ? `<p class="e19-kpi-note" id="deudaRutaOfferStatus">${escapeHtml(deudaRutaOfferStatusMessage)}</p>` : ""}
    <button type="button" class="e19-btn e19-btn-primary" id="deudaRutaOfferApply"${blocked ? " disabled" : ""}>Aplicar al plan</button>
    <a class="e19-btn e19-btn-secondary" href="#debt-roadmap" id="deudaRutaOfferEdit">Ver documentos y editar oferta</a>
  `;
  const applyButton = qs("deudaRutaOfferApply");
  if (applyButton) {
    applyButton.addEventListener("click", async () => {
      e14bWorkspace().selectedOfferId = offer.id;
      await applyE14bOffer();
      deudaRutaOfferStatusMessage = qs("e14bStatus")?.textContent || "";
      renderDeudaRutaOffer();
    });
  }
  const editLink = qs("deudaRutaOfferEdit");
  if (editLink) {
    editLink.addEventListener("click", () => {
      e14bWorkspace().selectedOfferId = offer.id;
      queueRemoteSave();
    });
  }
}

function renderDeudaRuta() {
  renderDeudaScreenTabs("deuda-ruta");
  renderScenarioDependencyNotice("deuda-ruta");
  renderDeudaRutaOffer();
  if (debtStrategyReserveValue === null) debtStrategyReserveValue = debtStrategyReserveDefault();
  const tabs = qs("deudaRutaTabs");
  if (tabs) {
    tabs.innerHTML = DEBT_STRATEGY_DEFINITIONS.map(
      (def) => `<button type="button" class="deuda-decidir-tab${def.id === deudaRutaSelectedStrategy ? " is-active" : ""}" data-deuda-ruta-tab="${escapeHtml(def.id)}">${escapeHtml(def.label)}</button>`
    ).join("");
  }

  const baseInput = escenarioMotorBaseInput();
  const contracts = escenarioMotorDebtOptions();
  const summary = debtStrategySummary(deudaRutaSelectedStrategy, baseInput, debtStrategyReserveValue);
  const def = DEBT_STRATEGY_DEFINITIONS.find((item) => item.id === deudaRutaSelectedStrategy);
  const resultadosById = new Map((summary.result?.resultados || []).map((item) => [item.id, item]));

  const titleEl = qs("deudaRutaTitle");
  if (titleEl) {
    const esFecha = /^\d{4}-\d{2}/.test(String(summary.libreDeDeuda || ""));
    titleEl.textContent = esFecha
      ? `Sin deuda en ${escenarioMotorMonthLabel(summary.libreDeDeuda)}`
      : `Libre de deuda: ${escenarioMotorMonthLabel(summary.libreDeDeuda)}`;
  }
  const subtitleEl = qs("deudaRutaSubtitle");
  if (subtitleEl) {
    const costeLabel = (def?.costeLabel || DEBT_STRATEGY_COSTE_LABEL).toLowerCase();
    subtitleEl.textContent = `${def?.label || deudaRutaSelectedStrategy}: ${summary.total} decisión(es), ${money(summary.costeTotal, true)} de ${costeLabel}, caja mínima ${money(summary.cajaMinima ?? 0, true)}.`;
  }

  const deudaViva = buildDeudaVivaSeries(baseInput.months, contracts, summary.decisions, resultadosById);
  const chartWindow = deudaRutaChartWindow(deudaViva, summary.result?.series || [], baseInput.months);
  renderDeudaRutaChart(chartWindow.deudaSeries, chartWindow.liquidezSeries, chartWindow.months);

  const timeline = qs("deudaRutaTimeline");
  if (timeline) {
    const debts = new Map(contracts.map((contract) => [contract.id, contract]));
    const ordered = summary.decisions
      .map((decision) => ({ decision, resultado: resultadosById.get(decision.id) }))
      .sort((a, b) => String(a.resultado?.mesResuelto || "9999").localeCompare(String(b.resultado?.mesResuelto || "9999")));
    timeline.innerHTML = ordered.length
      ? ordered
          .map(({ decision, resultado }) => {
            const info = resultado ? escenarioMotorResultInfo(resultado.resultado) : { text: "Sin calcular", badge: "e19-badge-neutral" };
            // V3-3 · una reunificación no apunta a una deuda ni lleva `importe`: nombra varias y
            // abre un préstamo. Leer `params.deudaId`/`params.importe` para ella daría «undefined»
            // y «0,00 €» en la línea de tiempo.
            const esReunificacion = decision.tipo === "reunificacion";
            const contract = esReunificacion ? null : debts.get(decision.params.deudaId);
            const titulo = esReunificacion
              ? `Reunificar ${(decision.params.deudaIds || []).length} deudas`
              : contract
              ? escenarioMotorDebtLabel(contract)
              : decision.params.deudaId;
            const detalle = esReunificacion
              ? `${money(decision.params.nuevoPrincipal, true)} · ${money(decision.params.nuevaCuota, true)}/mes durante ${decision.params.nuevoPlazo} meses`
              : money(decision.params.importe, true);
            return `<li class="deuda-ruta-timeline-item">
              <span class="deuda-ruta-timeline-month">${escapeHtml(escenarioMotorMonthLabel(resultado?.mesResuelto))}</span>
              <div>
                <strong>${escapeHtml(titulo)}</strong>
                <p>${escapeHtml(detalle)} · <span class="e19-badge ${info.badge}">${escapeHtml(info.text)}</span></p>
              </div>
            </li>`;
          })
          .join("")
      : `<li class="deuda-ruta-timeline-item deuda-ruta-timeline-empty">${escapeHtml(deudaRutaEmptyTimelineText(summary))}</li>`;
  }

  const portfolio = qs("deudaRutaPortfolio");
  if (portfolio) {
    const maxPrincipal = Math.max(1, ...contracts.map((contract) => Number(contract.currentPrincipal) || 0));
    portfolio.innerHTML = contracts
      .slice()
      .sort((a, b) => Number(b.currentPrincipal) - Number(a.currentPrincipal))
      .map((contract) => `<div class="deuda-ruta-portfolio-row">
          <span>${escapeHtml(escenarioMotorDebtLabel(contract))}</span>
          <strong>${money(contract.currentPrincipal, true)}</strong>
          <div class="deuda-ruta-portfolio-bar"><span style="width:${Math.round((Number(contract.currentPrincipal) / maxPrincipal) * 100)}%"></span></div>
        </div>`)
      .join("");
  }

  const checklist = qs("deudaRutaChecklist");
  const applyButton = qs("deudaRutaApply");
  const reserveConfigured = Number.isFinite(debtStrategyReserveValue);
  const effectiveReserve = debtStrategyEffectiveReserve(debtStrategyReserveValue);
  const reserveOk = (summary.cajaMinima ?? 0) >= effectiveReserve;
  const checks = [
    {
      ok: reserveOk,
      label: reserveOk
        ? reserveConfigured
          ? "Reserva mínima protegida durante toda la ruta"
          : "No baja de 0 € en ningún mes (sin reserva mínima configurada)"
        : reserveConfigured
        ? "La ruta baja de la reserva mínima indicada"
        : "La ruta deja la caja en negativo en algún mes",
    },
    {
      ok: summary.total === 0 ? null : summary.viable,
      label: summary.total === 0
        ? deudaRutaEmptyTimelineText(summary)
        : summary.viable
        ? "Todas las decisiones tienen mes viable"
        : `${summary.total - summary.aplicadas} decisión(es) sin mes viable en este horizonte`,
    },
  ];
  if (checklist) {
    checklist.innerHTML = checks
      .map((check) => `<li class="deuda-ruta-check${check.ok === false ? " is-danger" : check.ok === null ? " is-neutral" : " is-ok"}">${escapeHtml(check.label)}</li>`)
      .join("");
  }
  if (applyButton) applyButton.disabled = summary.total === 0 || !summary.viable;

  // D-4 · en el mismo orden de ataque que la pestaña activa (avalancha/bola de nieve); consolidar y
  // no tocar no ordenan nada (`debtStrategyOrderedContracts` devuelve []), así que caen al orden
  // declarado de la cartera, igual que la tarjeta de «Cartera» de al lado.
  const orderedForCalendar = debtStrategyOrderedContracts(deudaRutaSelectedStrategy);
  const calendarContracts = orderedForCalendar.length ? orderedForCalendar : contracts;

  const aggregate = debtStrategyAggregateCalendar(summary.decisions, resultadosById, calendarContracts, baseInput.months);
  const baselineInterest = debtAmortizationTotalInterest(calendarContracts, baseInput.months.length);
  const amortChart = qs("deudaRutaAmortChart");
  if (amortChart) amortChart.innerHTML = debtRutaAmortChartHtml(aggregate.series);
  const amortStats = qs("deudaRutaAmortStats");
  if (amortStats) amortStats.innerHTML = debtRutaAmortStatsHtml(aggregate, baselineInterest);

  renderDeudaRutaCalendar(calendarContracts, baseInput.months);
}

// D-4 · calendario de amortización mes a mes, sobre el calendario declarado del contrato (cuota
// francesa fija a partir de TAE + cuota), no sobre las decisiones de una ruta: es la lectura que
// faltaba junto al escalón de «Deuda viva» del gráfico de arriba, que la propia pantalla avisa que
// no es un calendario mes a mes. Nunca aproxima en silencio: si la cuota no cubre ni el interés, o
// si el horizonte se acaba antes de llegar a saldo cero, lo dice en vez de fingir un cierre.
function debtAmortizationSchedule(contract, maxMonths) {
  const principal = round2(Number(contract?.currentPrincipal || 0));
  const payment = round2(Number(contract?.currentPayment || 0));
  const aprPct = Number(contract?.apr);
  const monthlyRate = Number.isFinite(aprPct) && aprPct > 0 ? aprPct / 100 / 12 : 0;
  const limit = Math.max(1, Math.min(Math.round(maxMonths) || 1, 600));
  const rows = [];
  let balance = principal;
  if (!(principal > 0)) return { rows, stalled: false, complete: true };
  for (let index = 0; index < limit && balance > 0.005; index += 1) {
    const interest = round2(balance * monthlyRate);
    const principalPaid = round2(payment - interest);
    if (!(payment > 0) || principalPaid <= 0) {
      rows.push({ month: index + 1, payment, interest, principal: 0, balance: round2(balance), stalled: true });
      return { rows, stalled: true, complete: false };
    }
    const appliedPrincipal = principalPaid > balance ? balance : principalPaid;
    balance = round2(balance - appliedPrincipal);
    rows.push({ month: index + 1, payment: round2(interest + appliedPrincipal), interest, principal: appliedPrincipal, balance });
  }
  return { rows, stalled: false, complete: balance <= 0.005 };
}

// D-4 · qué mes liquida esta ruta cada contrato de golpe (y con qué préstamo nuevo, si es una
// reunificación) — el mismo escaneo de decisiones que ya hace `buildDeudaVivaSeries` para su
// escalón, pero devolviendo los datos que hacen falta para amortizar de verdad el préstamo nuevo
// (cuota y TAE), no solo su magnitud plana.
function debtStrategyPayoffPlan(months, decisions, resultadosById) {
  const payoffMonthByDebt = new Map();
  const nuevosPrestamos = [];
  decisions.forEach((decision) => {
    const resultado = resultadosById.get(decision.id);
    if (resultado?.resultado !== "aplicada" || !resultado.mesResuelto) return;
    if (decision.tipo === "reunificacion") {
      (decision.params.deudaIds || []).forEach((deudaId) => payoffMonthByDebt.set(deudaId, resultado.mesResuelto));
      nuevosPrestamos.push({
        id: `reunificada-${decision.id}`,
        label: "Préstamo de reunificación",
        currentPrincipal: Number(decision.params.nuevoPrincipal) || 0,
        currentPayment: Number(decision.params.nuevaCuota) || 0,
        apr: round2((Number(decision.params.nuevoTIN) || 0) * 100),
        desde: resultado.mesResuelto,
      });
      return;
    }
    payoffMonthByDebt.set(decision.params.deudaId, resultado.mesResuelto);
  });
  return { payoffMonthByDebt, nuevosPrestamos };
}

// El calendario francés natural de debtAmortizationSchedule, más el mes (índice absoluto en
// `months`) en el que la estrategia liquida el contrato de golpe, si lo hace antes de que terminara
// por su cuenta — sin recortar `rows` aquí: una deuda «stalled» (sin cuota que cubra ni el interés)
// solo trae una fila por diseño, no porque el saldo desaparezca el mes siguiente, así que el corte
// real de meses vive en quien agrega (`debtStrategyAggregateCalendar`), no aquí. Sin mes de
// liquidación, o si llega después de que el contrato ya hubiera terminado solo, no hay nada que
// truncar.
function debtAmortizationScheduleForPlan(contract, months, payoffMonthKey) {
  const schedule = debtAmortizationSchedule(contract, months.length);
  if (!payoffMonthKey) return { ...schedule, payoffIndex: null };
  const payoffIndex = months.findIndex((month) => month.monthKey === payoffMonthKey);
  if (payoffIndex < 0 || (schedule.complete && payoffIndex >= schedule.rows.length)) return { ...schedule, payoffIndex: null };
  return { ...schedule, payoffIndex };
}

// D-4 · el calendario agregado que faltaba: capital vivo mes a mes sumando todos los contratos bajo
// la estrategia activa (cada uno con su calendario declarado, truncado si esta ruta lo liquida antes
// de golpe) más el préstamo nuevo de una reunificación desde el mes en que se firma. Con 0
// decisiones (Mín./no-tocar) coincide exactamente con solo mínimos: no hay nada que adelantar.
function debtStrategyAggregateCalendar(decisions, resultadosById, contracts, months) {
  const { payoffMonthByDebt, nuevosPrestamos } = debtStrategyPayoffPlan(months, decisions, resultadosById);
  const entries = contracts.map((contract) => ({
    label: escenarioMotorDebtLabel(contract),
    offset: 0,
    schedule: debtAmortizationScheduleForPlan(contract, months, payoffMonthByDebt.get(contract.id) || null),
  }));
  nuevosPrestamos.forEach((prestamo) => {
    const offset = months.findIndex((month) => month.monthKey === prestamo.desde);
    if (offset < 0) return;
    const remaining = months.slice(offset);
    entries.push({ label: prestamo.label, offset, schedule: { ...debtAmortizationSchedule(prestamo, remaining.length), payoffIndex: null } });
  });

  const capital = months.map(() => 0);
  let totalInterest = 0;
  let firstPayoff = null;
  entries.forEach((entry) => {
    const rows = entry.schedule.rows;
    // Una deuda «stalled» (cuota que no cubre ni el interés, o sin cuota declarada) solo genera UNA
    // fila — `debtAmortizationSchedule` corta ahí a propósito para no fingir una amortización que no
    // ocurre — pero su saldo no desaparece los meses siguientes: sigue ahí, congelado, hasta que la
    // ruta la liquide de golpe (si lo hace) o se acabe el horizonte. Sin este relleno, el agregado la
    // haría desaparecer del total a partir del mes 2, como si se hubiera pagado sola.
    const flatBalance = entry.schedule.stalled && rows.length ? rows[rows.length - 1].balance : null;
    // El corte real de la ruta (si lo hay) manda incluso sobre el relleno congelado: a partir de ahí
    // no queda saldo, se haya llegado ahí amortizando de verdad o estancado.
    const cutoff = entry.schedule.payoffIndex ?? Infinity;
    for (let index = entry.offset; index < capital.length && index < cutoff; index += 1) {
      const localIndex = index - entry.offset;
      if (localIndex < rows.length) {
        capital[index] += rows[localIndex].balance;
        totalInterest += rows[localIndex].interest;
      } else if (flatBalance !== null) {
        capital[index] += flatBalance;
      }
    }
    const completionIndex =
      entry.schedule.payoffIndex !== null && entry.schedule.payoffIndex !== undefined
        ? entry.schedule.payoffIndex
        : entry.schedule.complete && entry.schedule.rows.length
        ? entry.offset + entry.schedule.rows.length - 1
        : null;
    if (completionIndex !== null && completionIndex >= 0 && completionIndex < months.length && (!firstPayoff || completionIndex < firstPayoff.index)) {
      firstPayoff = { index: completionIndex, label: entry.label };
    }
  });
  // Recorta la cola de meses ya saldados (capital 0): el mockup deja de dibujar barras en cuanto la
  // deuda llega a cero, no arrastra el resto del horizonte del motor (hasta 10 años) en blanco.
  let lastActive = capital.length - 1;
  while (lastActive > 0 && capital[lastActive] <= 0.01) lastActive -= 1;
  return {
    series: capital.slice(0, lastActive + 1).map((value, index) => ({ monthKey: months[index].monthKey, month: months[index].month, capital: round2(Math.max(0, value)) })),
    totalInterest: round2(totalInterest),
    firstPayoff: firstPayoff ? { label: firstPayoff.label, month: months[firstPayoff.index]?.month, monthKey: months[firstPayoff.index]?.monthKey } : null,
  };
}

// El total de intereses «solo mínimos»: la misma cuota francesa de cada contrato, nunca tocada por
// ninguna decisión — el mismo cálculo que ya pinta cada `<details>` del calendario por contrato, solo
// que sumado. Es el baseline con el que D-4 compara la estrategia activa.
function debtAmortizationTotalInterest(contracts, maxMonths) {
  return round2(contracts.reduce((sum, contract) => sum + debtAmortizationSchedule(contract, maxMonths).rows.reduce((s, row) => s + row.interest, 0), 0));
}

function debtRutaAmortChartHtml(series) {
  if (!series.length) return '<p class="e19-kpi-note">Sin deuda viva: no hay calendario que proyectar.</p>';
  const max = Math.max(1, ...series.map((row) => row.capital));
  const bars = series
    .map(
      (row) =>
        `<div class="deuda-ruta-amort-bar" style="height:${Math.max(2, Math.round((row.capital / max) * 100))}%" title="${escapeHtml(row.month)} · ${money(row.capital, true)}"></div>`
    )
    .join("");
  const mid = series[Math.floor((series.length - 1) / 2)];
  return `<div class="deuda-ruta-amort-chart">${bars}</div>
    <div class="deuda-ruta-amort-axis"><span>${escapeHtml(series[0]?.month || "")}</span><span>${escapeHtml(mid?.month || "")}</span><span>${escapeHtml(series.at(-1)?.month || "")}</span></div>`;
}

function debtRutaAmortStatsHtml(aggregate, baselineInterest) {
  const delta = round2(baselineInterest - aggregate.totalInterest);
  const deltaText =
    Math.abs(delta) < 0.01
      ? "Igual que solo mínimos: esta ruta no adelanta ningún pago."
      : delta > 0
      ? `${money(delta, true)} menos que solo mínimos`
      : `${money(Math.abs(delta), true)} más que solo mínimos`;
  return `
    <div class="deuda-ruta-amort-stat"><span>Primer contrato liquidado</span><strong>${
      aggregate.firstPayoff ? `${escapeHtml(aggregate.firstPayoff.month)} · ${escapeHtml(aggregate.firstPayoff.label)}` : "Ninguno dentro de este horizonte"
    }</strong></div>
    <div class="deuda-ruta-amort-stat"><span>Intereses totales</span><strong>${money(aggregate.totalInterest, true)}</strong></div>
    <div class="deuda-ruta-amort-stat"><span>Frente a solo mínimos</span><strong>${escapeHtml(deltaText)}</strong></div>
  `;
}

function renderDeudaRutaCalendar(contracts, months) {
  const container = qs("deudaRutaCalendar");
  if (!container) return;
  if (!contracts.length) {
    container.innerHTML = '<p class="e19-kpi-note">Sin deudas vivas: no hay calendario que mostrar.</p>';
    return;
  }
  container.innerHTML = contracts
    .map((contract) => {
      const schedule = debtAmortizationSchedule(contract, months.length);
      const totalInterest = round2(schedule.rows.reduce((sum, row) => sum + row.interest, 0));
      const label = escenarioMotorDebtLabel(contract);
      const summary = schedule.stalled
        ? !(Number(contract.currentPayment) > 0)
          ? `${label} · sin cuota declarada: no hay calendario que proyectar`
          : `${label} · la cuota declarada no cubre ni el interés: no amortiza`
        : !schedule.complete
        ? `${label} · no llega a saldo cero dentro de los ${months.length} meses del horizonte`
        : `${label} · saldada en ${months[schedule.rows.length - 1]?.month || "—"} · ${money(totalInterest, true)} de interés total`;
      const rowsHtml = schedule.rows
        .map(
          (row) => `<tr>
            <td>${escapeHtml(months[row.month - 1]?.month || `Mes ${row.month}`)}</td>
            <td>${money(row.payment, true)}</td>
            <td>${money(row.interest, true)}</td>
            <td>${money(row.principal, true)}</td>
            <td>${money(row.balance, true)}</td>
          </tr>`
        )
        .join("");
      return `<details class="deuda-ruta-calendar-item">
          <summary>${escapeHtml(summary)}</summary>
          <div class="table-wrap">
            <table class="e19-table">
              <thead><tr><th>Mes</th><th>Cuota</th><th>Interés</th><th>Capital</th><th>Saldo</th></tr></thead>
              <tbody>${rowsHtml}</tbody>
            </table>
          </div>
        </details>`;
    })
    .join("");
}

function handleDeudaRutaTab(strategyId) {
  deudaRutaSelectedStrategy = strategyId;
  renderDeudaRuta();
}

function handleDeudaRutaApply() {
  debtStrategyDecisionsToEscenario(deudaRutaSelectedStrategy);
  escenarioMotorNavigate("escenario-aplicar");
}

// D-1 · Ruta, Comparar y Contratos comparten una misma barra de pestañas de pantalla (distinta de
// `deudaRutaTabs`, que son las cuatro estrategias dentro de Ruta). No se fusionan en una sola
// sección: Ruta y Comparar ya eran pantallas completas del epic V3, y Contratos es la única de las
// tres que se construye desde cero ahora — cada una sigue siendo su propio `view-section` con su
// propio hash, solo se enlazan visualmente como pestañas.
const DEUDA_SCREEN_TABS = [
  { id: "deuda-ruta", label: "Ruta" },
  { id: "deuda-comparar", label: "Comparar" },
  { id: "deuda-contratos", label: "Contratos" },
];
const DEUDA_SCREEN_TAB_NAV_IDS = {
  "deuda-ruta": "deudaRutaScreenTabs",
  "deuda-comparar": "deudaCompararScreenTabs",
  "deuda-contratos": "deudaContratosScreenTabs",
};

function deudaScreenTabsHtml(activeId) {
  return DEUDA_SCREEN_TABS.map(
    (tab) =>
      `<a class="e19-registrar-tab${tab.id === activeId ? " is-active" : ""}" href="#${tab.id}" aria-selected="${tab.id === activeId}">${escapeHtml(tab.label)}</a>`
  ).join("");
}

function renderDeudaScreenTabs(activeId) {
  const nav = qs(DEUDA_SCREEN_TAB_NAV_IDS[activeId]);
  if (nav) nav.innerHTML = deudaScreenTabsHtml(activeId);
}

// D-2 · Contratos como dato canónico editable. DEBT_PORTFOLIO es la cartera de ejemplo; aquí se
// corrige capital pendiente, TAE o cuota cuando no coinciden con el contrato real. La corrección
// se guarda por contrato en `debtContractOverrides` y pasa por `debtContractBundle()` — la misma
// puerta que ya leen Ruta, Comparar, Hoy y el motor de escenarios, así que no hace falta avisar a
// nadie más: en cuanto se guarda, todo lo que lee la cartera ve el valor corregido la próxima vez
// que se renderiza.
function deudaContratosStatusBadge(paymentStatus) {
  const map = {
    active: { label: "Activa", tone: "e19-badge-neutral" },
    suspended: { label: "Pagos suspendidos", tone: "e19-badge-warning" },
    reunified: { label: "Reunificada", tone: "e19-badge-neutral" },
    settled: { label: "Liquidada", tone: "e19-badge-success" },
  };
  return map[paymentStatus] || { label: paymentStatus || "—", tone: "e19-badge-neutral" };
}

function deudaContratosQualityBadge(quality) {
  const missing = quality?.missing?.length || 0;
  if (!missing) return { label: "Dato completo", tone: "e19-badge-success" };
  if (quality?.confidence === "medium") return { label: `Falta ${missing} dato(s)`, tone: "e19-badge-warning" };
  return { label: `Faltan ${missing} dato(s)`, tone: "e19-badge-danger" };
}

function deudaContratosRowHtml(contract) {
  const edited = Boolean(debtContractOverrides[contract.id]);
  const status = deudaContratosStatusBadge(contract.paymentStatus);
  const quality = deudaContratosQualityBadge(contract.dataQuality);
  const aprValue = contract.apr === null || contract.apr === undefined ? "" : contract.apr;
  return `<tr data-deuda-contrato-row="${escapeHtml(contract.id)}">
      <td class="deuda-contratos-entity">
        <strong>${escapeHtml(contract.entity)}</strong>
        <small>${escapeHtml(contract.type)}${contract.number ? ` · ${escapeHtml(contract.number)}` : ""}</small>
      </td>
      <td><input type="number" min="0" step="0.01" inputmode="decimal" data-deuda-contrato-id="${escapeHtml(contract.id)}" data-deuda-contrato-field="currentPrincipal" value="${round2(contract.currentPrincipal)}" aria-label="Capital pendiente de ${escapeHtml(contract.entity)}" /></td>
      <td><input type="number" min="0" max="60" step="0.01" inputmode="decimal" data-deuda-contrato-id="${escapeHtml(contract.id)}" data-deuda-contrato-field="apr" value="${aprValue}" placeholder="sin dato" aria-label="TAE de ${escapeHtml(contract.entity)}" /></td>
      <td><input type="number" min="0" step="0.01" inputmode="decimal" data-deuda-contrato-id="${escapeHtml(contract.id)}" data-deuda-contrato-field="currentPayment" value="${round2(contract.currentPayment)}" aria-label="Cuota mensual de ${escapeHtml(contract.entity)}" /></td>
      <td><span class="e19-badge ${status.tone}">${escapeHtml(status.label)}</span></td>
      <td><span class="e19-badge ${quality.tone}">${escapeHtml(quality.label)}</span>${edited ? ' <span class="e19-badge e19-badge-neutral">Editado</span>' : ""}</td>
    </tr>`;
}

function renderDeudaContratos() {
  renderDeudaScreenTabs("deuda-contratos");
  const body = qs("deudaContratosTable");
  if (!body) return;
  const contracts = debtContractSourceRows();
  body.innerHTML = `<thead><tr>
        <th>Entidad</th><th>Capital pendiente</th><th>TAE</th><th>Cuota mensual</th><th>Estado</th><th>Calidad del dato</th>
      </tr></thead>
      <tbody>${contracts.map(deudaContratosRowHtml).join("")}</tbody>`;
  const overriddenCount = contracts.filter((contract) => debtContractOverrides[contract.id]).length;
  const note = qs("deudaContratosNote");
  if (note) {
    note.textContent = overriddenCount
      ? `${overriddenCount} de ${contracts.length} contrato(s) con capital, TAE o cuota corregidos a mano. Se usan en Ruta, Comparar y en las cifras de deuda de Hoy.`
      : `Valores declarados de ejemplo (${contracts.length} contrato(s)). Corrige capital, TAE o cuota si no coinciden con el contrato real — se guardan en este navegador y no en ningún sitio más.`;
  }
}

// Vacío = «sin corregir», nunca cero: borra el override y vuelve al valor declarado en vez de
// clavar un 0 que se leería como «no debe nada». Un valor fuera de rango no se guarda ni se avisa
// aparte — el redibujado siguiente vuelve a enseñar el último valor válido, la misma disciplina que
// ya usan los demás campos numéricos de la app.
function deudaContratosParseFieldValue(field, raw) {
  const trimmed = String(raw ?? "").trim();
  if (trimmed === "") return { clear: true };
  const value = Number(trimmed.replace(",", "."));
  if (!Number.isFinite(value) || value < 0) return { invalid: true };
  if (field === "apr" && value > 60) return { invalid: true };
  return { value: round2(value) };
}

function handleDeudaContratosFieldChange(input) {
  const id = input.dataset.deudaContratoId;
  const field = input.dataset.deudaContratoField;
  if (!id || !DEBT_CONTRACT_EDITABLE_FIELDS.includes(field)) return;
  const parsed = deudaContratosParseFieldValue(field, input.value);
  if (parsed.invalid) {
    renderDeudaContratos();
    return;
  }
  const nextContract = { ...(debtContractOverrides[id] || {}) };
  if (parsed.clear) delete nextContract[field];
  else nextContract[field] = parsed.value;
  const nextOverrides = { ...debtContractOverrides };
  if (Object.keys(nextContract).length) nextOverrides[id] = nextContract;
  else delete nextOverrides[id];
  debtContractOverrides = nextOverrides;
  saveDebtContractOverrides();
  renderDeudaContratos();
}

// ---------------------------------------------------------------------------------------------
// Conciliación (E20-2, mockup 1g). No reimplementa nada: llama a las mismas funciones reales que
// ya usa la pantalla heredada #reconciliation (refreshCanonicalLedger, E11bInbox.reconciliationTasks,
// FinanceCanonicalE5.latestMonthOperation) y solo cambia la presentación — una lectura enfocada en
// "qué falta para cerrar el mes" en vez del panel operativo completo (paridad histórica, auditoría
// diaria, barrera de publicación...) que #reconciliation sigue ofreciendo intacto para quien lo
// necesite.
// ---------------------------------------------------------------------------------------------
function conciliarMonthHistory(monthRows) {
  return monthRows.map((row) => {
    const latest = window.FinanceCanonicalE5?.latestMonthOperation({ monthClosures }, row.monthKey);
    const reopenCount = monthClosures.filter((op) => op.monthKey === row.monthKey && op.operation === "month-reopen").length;
    return { monthKey: row.monthKey, closed: latest?.status === "closed", reopenCount };
  });
}

// =================================================================================================
// Fase 5 · Cierre — pantalla 08 (Cierre.pdf, auditado el 16 de agosto): ritual secuencial de tres
// pasos reales (Conciliar cuentas → Resolver diferencias → Firmar y archivar). El mockup describe
// cuatro pasos con «Liquidar sobres» como el tercero, pero Sobres (P-14/P-15/P-16, Fase 4) no existe
// todavía — el propio mockup contempla este caso explícitamente: «con la fase 6 apagada el cierre
// tiene tres pasos y lo dice» (nota bajo el inventario de Cierre.pdf). No se inventa un paso a medias.
//
// Reutiliza toda la infraestructura ya construida para #conciliar/#reconciliation en vez de
// duplicarla: `FinanceCanonicalLedger` para las entradas del extracto, `E11bInbox.reconciliationTasks`
// para las tareas por causa, `closeCurrentMonthTransaction()`/`reopenLatestMonthTransaction()` para
// firmar y reabrir (misma puerta de escritura transaccional que ya usa #reconciliation, con Supabase
// y `FinanceCanonicalMonthClose`/E5 detrás), `accountBalancesFromState()` para el saldo declarado.
// Ningún cálculo financiero nuevo se fabrica aquí.
// =================================================================================================

let cierreActiveStep = 1;
let cierreEvidenceContext = null;

const CIERRE_ACCOUNT_LABELS = { caixabank: "CaixaBank", mediolanum: "Mediolanum" };

const CIERRE_TASK_CAUSE_LABELS = {
  unclassified: "Clasificación",
  "bank-actual-difference": "Diferencias banco/real",
  "balance-gap": "Continuidad de saldo",
};

// C-2: saldo declarado (lo que escribiste en Registrar, `accountBalancesFromState`) frente al saldo
// calculado (el `balanceAfter` más reciente del extracto ya incorporado para esa cuenta). Una cuenta
// sin ningún movimiento de extracto — Mediolanum no trae extracto bancario en este modelo, ya
// documentado en `conciliarAccountConfidence` — se marca «sin-conciliar», nunca «cuadra»: no hay
// nada que comparar, y compararla con cero sería inventar un dato (regla transversal 04).
function cierreAccountReconciliation(entries) {
  const declared = accountBalancesFromState();
  return Object.entries(CIERRE_ACCOUNT_LABELS).map(([accountId, label]) => {
    const declaredValue = round2(accountId === "caixabank" ? declared.caixa : declared.mediolanum);
    const accountEntries = (entries || []).filter(
      (entry) => entry.accountId === accountId && !entry.duplicateOf && entry.balanceAfter !== null && entry.balanceAfter !== undefined
    );
    const latest = accountEntries
      .slice()
      .sort((a, b) => String(a.date || "").localeCompare(String(b.date || "")) || (a.sourceRow ?? 0) - (b.sourceRow ?? 0))
      .at(-1);
    const calculated = latest ? round2(latest.balanceAfter) : null;
    const diff = calculated === null ? null : round2(declaredValue - calculated);
    const status = calculated === null ? "sin-conciliar" : Math.abs(diff) <= 0.02 ? "cuadra" : "descuadra";
    return { id: accountId, label, declared: declaredValue, calculated, diff, status, latestDate: latest?.date || null };
  });
}

function cierreAccountsSettled(rows) {
  return rows.every((row) => row.status !== "descuadra");
}

// C-1: tres pasos secuenciales — cada uno permanece bloqueado hasta que el anterior está completo.
// Un paso ya completado se puede volver a abrir para consultarlo; nunca se puede saltar hacia
// delante uno todavía pendiente.
function cierreStepsStatus(accountRows, tasks) {
  const step1Done = cierreAccountsSettled(accountRows);
  const step2Done = step1Done && tasks.length === 0;
  return [
    { step: 1, label: "Conciliar cuentas", sublabel: "Declarado frente a calculado", unlocked: true, done: step1Done },
    { step: 2, label: "Resolver diferencias", sublabel: "Tareas agrupadas por causa", unlocked: step1Done, done: step2Done },
    { step: 3, label: "Firmar y archivar", sublabel: "Comprobaciones antes de firmar", unlocked: step2Done, done: false },
  ];
}

function cierreStepsHtml(steps, activeStep) {
  return steps
    .map((item) => {
      const classes = ["cierre-step"];
      if (item.step === activeStep) classes.push("is-active");
      if (item.done) classes.push("is-done");
      if (!item.unlocked) classes.push("is-locked");
      const sublabel = item.unlocked ? item.sublabel : "Se abre al completar el paso anterior";
      return `<li class="${classes.join(" ")}" data-cierre-step="${item.step}">
        <span class="cierre-step-index">${item.done ? "✓" : item.step}</span>
        <div><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(sublabel)}</small></div>
      </li>`;
    })
    .join("");
}

// C-5: cuatro comprobaciones del mockup, reducidas a las tres reales de este modelo mientras no hay
// sobres — «Ningún sobre sin destino» no se muestra fingiendo un estado que cumple; se documenta
// como paso inexistente, igual que el paso 3 (regla transversal 04).
function cierreFirmChecks(accountRows, tasks, monthMovementCount) {
  return [
    { id: "cuentas", label: "Las cuentas cuadran", met: cierreAccountsSettled(accountRows) },
    { id: "diferencias", label: "Ninguna diferencia abierta", met: tasks.length === 0 },
    { id: "extracto", label: `Extracto incorporado · ${monthMovementCount} movimiento(s)`, met: monthMovementCount > 0 },
  ];
}

function cierreFirmChecksHtml(checks) {
  return checks.map((check) => `<li class="deuda-ruta-check${check.met ? " is-ok" : " is-danger"}">${escapeHtml(check.label)}</li>`).join("");
}

// C-3: tareas agrupadas por causa — cuentas, clasificación y saldo — en vez de la lista plana que
// ya usa `#conciliar`. C-4: abrir una tarea solo navega a la pantalla de origen; nunca la marca
// resuelta por sí sola, así que no hay botón «marcar hecho» — la tarea desaparece cuando el dato
// real cuadra, porque `tasks` se recalcula en cada render desde los mismos datos.
function cierreGroupTasksByCause(tasks) {
  return Object.keys(CIERRE_TASK_CAUSE_LABELS)
    .map((cause) => ({ cause, label: CIERRE_TASK_CAUSE_LABELS[cause], items: tasks.filter((task) => task.cause === cause) }))
    .filter((group) => group.items.length);
}

function cierreTaskActionLabel(task) {
  if (task.action === "classify") return "Clasificar";
  if (task.action === "adjust-balance") return "Revisar saldo";
  return "Corregir real";
}

function cierreStep1Html(accountRows) {
  const descuadres = accountRows.filter((row) => row.status === "descuadra").length;
  const statusBadge = { cuadra: "e19-badge-success", descuadra: "e19-badge-danger", "sin-conciliar": "e19-badge-neutral" };
  const statusLabel = { cuadra: "Cuadra", descuadra: "Descuadra", "sin-conciliar": "Sin conciliar" };
  const rows = accountRows
    .map(
      (row) => `<tr>
        <td><strong>${escapeHtml(row.label)}</strong></td>
        <td>${money(row.declared, true)}</td>
        <td>${row.calculated === null ? "—" : money(row.calculated, true)}</td>
        <td>${row.diff === null ? "—" : money(row.diff, true)}</td>
        <td><span class="e19-badge ${statusBadge[row.status]}">${statusLabel[row.status]}</span>${
        row.status === "descuadra" ? ` <button type="button" class="e19-btn e19-btn-secondary cierre-inline-button" data-cierre-task-target="update-hub">Crear tarea</button>` : ""
      }</td>
      </tr>`
    )
    .join("");
  return `<article class="e19-card cierre-step-card">
    <div class="section-title with-action">
      <div><h3 class="escenario-motor-panel-title">Conciliar cuentas</h3><p class="e19-kpi-note">Saldo declarado frente a saldo calculado.</p></div>
      ${descuadres ? `<span class="e19-badge e19-badge-danger">${descuadres} cuenta(s) descuadran</span>` : ""}
    </div>
    <div class="table-wrap"><table class="e19-table cierre-accounts-table">
      <thead><tr><th>Cuenta</th><th>Declarado</th><th>Calculado</th><th>Diferencia</th><th>Estado</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>
    <p class="e19-kpi-note">El saldo calculado sale del último movimiento del extracto incorporado; el declarado, de lo que escribiste en Registrar. Una diferencia no se corrige sola: revisa el saldo en Datos.</p>
  </article>`;
}

function cierreStep2Html(tasks) {
  const groups = cierreGroupTasksByCause(tasks);
  if (!groups.length) {
    return `<article class="e19-card cierre-step-card"><h3 class="escenario-motor-panel-title">Resolver diferencias</h3><p class="e19-kpi-note">Sin diferencias abiertas: clasificación, saldos e importes reales están conciliados.</p></article>`;
  }
  const groupsHtml = groups
    .map(
      (group) => `<div class="cierre-task-group">
        <h4>${escapeHtml(group.label)} · ${group.items.length}</h4>
        <ol class="conciliar-task-list">${group.items
          .map(
            (task) => `<li class="conciliar-task-item">
              <div><strong>${escapeHtml(task.label)}</strong><p>Abrir no modifica nada.</p></div>
              <button type="button" class="e19-btn e19-btn-secondary" data-cierre-task-target="${escapeHtml(task.target)}">${cierreTaskActionLabel(task)}</button>
            </li>`
          )
          .join("")}</ol>
      </div>`
    )
    .join("");
  return `<article class="e19-card cierre-step-card">
    <h3 class="escenario-motor-panel-title">Resolver diferencias</h3>
    <p class="e19-kpi-note">Cada tarea nombra la pantalla y el dato que la generó. Abrir una tarea no corrige nada por sí sola: se cierra cuando el dato cuadra, no cuando se pulsa.</p>
    ${groupsHtml}
  </article>`;
}

// C-8: efectos reales de firmar, escritos antes de pulsar — solo los tres que
// `closeCurrentMonthTransaction`/`FinanceCanonicalMonthClose` ejecutan de verdad hoy. El mockup
// enumera cinco (incluidos «se liquidan los sobres» y «el gasto diario aprendido recalcula la
// cobertura»); ninguno de los dos existe todavía en el motor, así que no se anuncian.
function cierreEffectsHtml(monthLabel) {
  return `<ol class="cierre-effects-list">
    <li>Los reales de ${escapeHtml(monthLabel)} quedan congelados: dejan de aceptar cambios sin reabrir el mes.</li>
    <li>Se crea una versión nueva del cierre, con su fecha y su motivo.</li>
    <li>El mes se puede reabrir después: la reapertura pide un motivo y queda registrada como una versión más.</li>
  </ol>`;
}

function cierreStep3Html(accountRows, tasks, monthMovementCount, currentMonthKey) {
  const checks = cierreFirmChecks(accountRows, tasks, monthMovementCount);
  const unmet = checks.filter((check) => !check.met).length;
  const monthLabel = ledgerMonthLabel(currentMonthKey);
  const syncReady = Boolean(remoteUser) && Boolean(supabaseClient);
  const canSign = unmet === 0 && syncReady;
  return `<div class="cierre-step3-layout">
    <article class="e19-card">
      <h3 class="escenario-motor-panel-title">Antes de firmar</h3>
      <ul class="deuda-ruta-checklist">${cierreFirmChecksHtml(checks)}</ul>
      ${syncReady ? "" : `<p class="e19-kpi-note is-warn">Inicia sesión y sincroniza una versión antes de firmar.</p>`}
      <button type="button" class="e19-btn e19-btn-primary" id="cierreSignButton" ${canSign ? "" : "disabled"}>${unmet ? `Firmar · ${unmet} sin cumplir` : "Firmar cierre"}</button>
    </article>
    <article class="e19-card">
      <h3 class="escenario-motor-panel-title">Al firmar el cierre</h3>
      ${cierreEffectsHtml(monthLabel)}
    </article>
  </div>`;
}

// C-9: cuatro contadores con enlace al inventario completo (`#conciliar`, que conserva la lista
// detallada por movimiento). Los IDs de las tareas ya son estables — `E11bInbox.reconciliationTasks`
// los construye a partir del propio dato (`classify-${id}`, no de su posición en la lista).
function cierreCountersHtml(accountRows, tasks, unclassifiedCount) {
  const closedCount = monthClosures.filter((op) => op.status === "closed").length;
  return [
    ["Cuentas descuadradas", String(accountRows.filter((row) => row.status === "descuadra").length)],
    ["Tareas pendientes", String(tasks.length)],
    ["Movimientos sin clasificar", String(unclassifiedCount)],
    ["Meses cerrados", String(closedCount)],
  ]
    .map(([label, value]) => `<div class="e19-kpi"><span class="e19-kpi-label">${escapeHtml(label)}</span><span class="e19-kpi-value">${escapeHtml(value)}</span></div>`)
    .join("");
}

// C-10 (Cierre.pdf): "Una fila por versión con fecha, autor, resumen y estado. La vigente se
// distingue; ninguna versión se sobrescribe." Cada cierre/reapertura de `monthClosures` ya es una
// entrada inmutable (C-9); esto solo lee esa lista completa, nunca solo el mes actual, y nunca
// borra ni reescribe una fila — reabrir añade, no sustituye.
function cierreVersionRows(closures) {
  const list = Array.isArray(closures) ? closures : [];
  const timeOf = (op) => op.occurredAt || op.closedAt || op.reopenedAt || "";
  const latestByMonth = new Map();
  list.forEach((op) => {
    const current = latestByMonth.get(op.monthKey);
    if (!current || timeOf(op) > timeOf(current)) latestByMonth.set(op.monthKey, op);
  });
  return list
    .slice()
    .sort((a, b) => timeOf(b).localeCompare(timeOf(a)))
    .map((op) => ({
      id: op.id,
      monthKey: op.monthKey,
      fecha: timeOf(op),
      autor: op.author || "Sin identificar",
      resumen: `${op.operation === "month-reopen" ? "Reapertura" : "Cierre"} de ${ledgerMonthLabel(op.monthKey)} · ${op.reason || "Sin motivo registrado"}`,
      estado: op.status,
      vigente: latestByMonth.get(op.monthKey) === op,
    }));
}

function cierreVersionsHtml(rows) {
  if (!rows.length) return `<p class="e19-kpi-note">Todavía no hay ninguna versión firmada.</p>`;
  const estadoBadge = { closed: "e19-badge-success", reopened: "e19-badge-warning" };
  const estadoLabel = { closed: "Cerrado", reopened: "Reabierto" };
  return `<div class="table-wrap"><table class="e19-table cierre-versions-table">
    <thead><tr><th>Fecha</th><th>Mes</th><th>Autor</th><th>Resumen</th><th>Estado</th></tr></thead>
    <tbody>${rows
      .map(
        (row) => `<tr class="${row.vigente ? "is-vigente" : ""}">
          <td>${escapeHtml(row.fecha ? formatIsoDate(row.fecha.slice(0, 10)) : "—")}</td>
          <td>${escapeHtml(ledgerMonthLabel(row.monthKey))}</td>
          <td>${escapeHtml(row.autor)}</td>
          <td>${escapeHtml(row.resumen)}${row.vigente ? ` <span class="e19-badge e19-badge-neutral">Vigente</span>` : ""}</td>
          <td><span class="e19-badge ${estadoBadge[row.estado] || "e19-badge-neutral"}">${estadoLabel[row.estado] || row.estado}</span></td>
        </tr>`
      )
      .join("")}</tbody>
  </table></div>`;
}

// C-11: "Reabrir un mes cerrado exige motivo y crea una versión nueva [...] Además notifica a las
// pantallas que dependían de ese mes." El motivo y la versión ya los daba
// `reopenLatestMonthTransaction()`/E5; esto añade el aviso cruzado. De los tres dependientes que
// nombra el criterio, solo Análisis tiene una relación mes→dato verificable hoy (la banda de A-2 es
// literalmente una serie por mes): la cobertura aprendida de Hoy se calcula sobre una ventana de
// movimientos sin un mes único al que atribuirla, y A-7 («fiabilidad del plan») no existe todavía —
// forzar cualquiera de los dos habría sido inventar una relación que no se puede verificar (regla
// transversal 04), así que quedan fuera del aviso, documentado aquí en vez de en silencio.
function cierreMonthsCurrentlyReopened() {
  const timeOf = (op) => op.occurredAt || op.closedAt || op.reopenedAt || "";
  const latestByMonth = new Map();
  monthClosures.forEach((op) => {
    const current = latestByMonth.get(op.monthKey);
    if (!current || timeOf(op) > timeOf(current)) latestByMonth.set(op.monthKey, op);
  });
  const reopened = new Set();
  latestByMonth.forEach((op, monthKey) => { if (op.status === "reopened") reopened.add(monthKey); });
  return reopened;
}

// C-12: "PDF firmado de una página con el estado de las cuentas, las tareas resueltas, los
// asientos de sobres y la versión [...] CSV con los mismos datos en filas [...] Los dos llevan la
// misma fecha y el mismo identificador de versión." Sobres (Fase 6) no existe todavía — sus
// asientos no se listan, igual que C-1/C-8 ya declaran los tres pasos reales en vez de fingir un
// cuarto. "Tareas resueltas" se representa como el recuento de diferencias abiertas en el momento
// de la descarga (0 si el mes ya se firmó): no existe un registro histórico de qué tarea concreta
// se resolvió cuándo, así que no se inventa uno.
function cierreEvidenceRows(accountRows, tasks, closure, currentMonthKey) {
  const version = closure ? { id: closure.id, fecha: closure.closedAt || closure.occurredAt || "", autor: closure.author || "Sin identificar", motivo: closure.reason || "" } : null;
  return {
    monthKey: currentMonthKey,
    monthLabel: ledgerMonthLabel(currentMonthKey),
    version,
    accounts: accountRows.map((row) => ({ label: row.label, declarado: row.declared, calculado: row.calculated, diferencia: row.diff, estado: row.status })),
    diferenciasAbiertas: tasks.length,
  };
}

function cierreEvidenceCsvContent(evidence) {
  const header = ["Sección", "Cuenta", "Declarado", "Calculado", "Diferencia", "Estado", "Versión", "Fecha", "Autor", "Motivo"];
  const versionCols = [evidence.version?.id || "", evidence.version?.fecha ? evidence.version.fecha.slice(0, 10) : "", evidence.version?.autor || "", evidence.version?.motivo || ""];
  const lines = evidence.accounts.map((row) =>
    ["Cuentas", row.label, row.declarado, row.calculado ?? "", row.diferencia ?? "", row.estado, ...versionCols].map(csvValue).join(";")
  );
  lines.push(["Diferencias", `${evidence.diferenciasAbiertas} abierta(s) en el momento de la descarga`, "", "", "", "", ...versionCols].map(csvValue).join(";"));
  lines.push(["Sobres", "Fase 6 desactivada: sin asientos que exportar", "", "", "", "", ...versionCols].map(csvValue).join(";"));
  return `﻿${[header.map(csvValue).join(";"), ...lines].join("\r\n")}`;
}

function cierreEvidencePrintHtml(evidence) {
  const statusLabel = { cuadra: "Cuadra", descuadra: "Descuadra", "sin-conciliar": "Sin conciliar" };
  return `<h1>Cierre de ${escapeHtml(evidence.monthLabel)}</h1>
    <p>${evidence.version ? `Versión ${escapeHtml(evidence.version.id)} · firmado el ${escapeHtml(formatIsoDate((evidence.version.fecha || "").slice(0, 10)))} · ${escapeHtml(evidence.version.autor)} · ${escapeHtml(evidence.version.motivo)}` : "Mes todavía sin firmar en el momento de esta descarga."}</p>
    <table>
      <thead><tr><th>Cuenta</th><th>Declarado</th><th>Calculado</th><th>Diferencia</th><th>Estado</th></tr></thead>
      <tbody>${evidence.accounts
        .map((row) => `<tr><td>${escapeHtml(row.label)}</td><td>${money(row.declarado, true)}</td><td>${row.calculado === null ? "—" : money(row.calculado, true)}</td><td>${row.diferencia === null ? "—" : money(row.diferencia, true)}</td><td>${statusLabel[row.estado] || row.estado}</td></tr>`)
        .join("")}</tbody>
    </table>
    <p>Diferencias abiertas en el momento de la descarga: ${evidence.diferenciasAbiertas}.</p>
    <p>Sobres: Fase 6 desactivada, sin asientos que archivar.</p>`;
}

function downloadCierreEvidenceCsv(evidence) {
  const blob = new Blob([cierreEvidenceCsvContent(evidence)], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `cierre-${evidence.monthKey}${evidence.version ? `-${evidence.version.id}` : ""}.csv`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function handleCierreDownloadEvidence(kind, accountRows, tasks, closure, currentMonthKey) {
  const evidence = cierreEvidenceRows(accountRows, tasks, closure, currentMonthKey);
  if (kind === "csv") {
    downloadCierreEvidenceCsv(evidence);
    return;
  }
  const container = qs("cierrePrintEvidence");
  if (!container) return;
  container.innerHTML = cierreEvidencePrintHtml(evidence);
  document.body.classList.add("is-printing-cierre-evidence");
  window.print();
  document.body.classList.remove("is-printing-cierre-evidence");
}

function renderCierre() {
  if (!window.FinanceCanonicalLedger) return;
  const snapshot = refreshCanonicalLedger("cierre-view");
  if (!snapshot) return;
  const entries = snapshot.entries || [];
  const checks = snapshot.balanceChecks || [];
  const lines = snapshot.reconciliation?.lines || [];
  const currentMonthKey = openMonthCutoffKey();
  const currentClosure = isClosedMonthKey(currentMonthKey)
    ? window.FinanceCanonicalE5?.latestMonthOperation({ monthClosures }, currentMonthKey)
    : null;

  const titleEl = qs("cierreTitle");
  const subtitleEl = qs("cierreSubtitle");
  const sobresNote = qs("cierreSobresNote");
  if (sobresNote) sobresNote.textContent = "Sobres todavía no está disponible en la app: mientras tanto el cierre tiene tres pasos, no cuatro.";

  const unclassified = entries.filter((entry) => !entry.duplicateOf && entry.mapping?.status !== "classified");
  const differences = lines.filter((line) => Math.abs(Number(line.delta || 0)) > 0.02);
  const balanceGaps = checks.flatMap((check) => (check.gaps || []).map((gap, index) => ({ ...gap, id: `${check.accountId}-${index}`, accountId: check.accountId })));
  const tasks = E11bInbox ? E11bInbox.reconciliationTasks({ unclassified, differences, balanceGaps }) : [];
  const accountRows = cierreAccountReconciliation(entries);
  const countersEl = qs("cierreCounters");
  if (countersEl) countersEl.innerHTML = cierreCountersHtml(accountRows, tasks, unclassified.length);

  // C-10: el historial vive fuera del wizard/estado-cerrado — se ve igual en los dos, es la lista
  // completa de versiones, no solo la del mes en curso.
  const versionsEl = qs("cierreVersions");
  if (versionsEl) versionsEl.innerHTML = cierreVersionsHtml(cierreVersionRows(monthClosures));
  // C-12: el contexto que necesitan los botones de descarga se guarda aquí, no se recalcula al
  // pulsar — mismo dato que ya se ve en pantalla en ese momento.
  cierreEvidenceContext = { accountRows, tasks, closure: currentClosure, currentMonthKey };

  if (currentClosure) {
    if (titleEl) titleEl.textContent = `${ledgerMonthLabel(currentMonthKey)} cerrado`;
    if (subtitleEl) subtitleEl.textContent = "Los reales de este mes están congelados. Reábrelo si necesitas corregir algo.";
    qs("cierreWizard")?.setAttribute("hidden", "");
    qs("cierreClosedState")?.removeAttribute("hidden");
    const closedInfo = qs("cierreClosedInfo");
    if (closedInfo) {
      closedInfo.innerHTML = `<p><strong>Firmado</strong> el ${formatIsoDate((currentClosure.closedAt || currentClosure.occurredAt || "").slice(0, 10))} · ${escapeHtml(currentClosure.reason || "Sin motivo registrado")}</p>`;
    }
    const reopenButton = qs("cierreReopen");
    if (reopenButton) reopenButton.disabled = !remoteUser || !supabaseClient;
    return;
  }
  qs("cierreWizard")?.removeAttribute("hidden");
  qs("cierreClosedState")?.setAttribute("hidden", "");

  if (titleEl) titleEl.textContent = `Cierre de ${ledgerMonthLabel(currentMonthKey)}`;
  if (subtitleEl) subtitleEl.textContent = "Las diferencias se resuelven como tareas: abrir una no corrige nada por sí sola. Al firmar, los reales quedan congelados y se crea una versión nueva.";

  const monthMovementCount = entries.filter((entry) => entry.monthKey === currentMonthKey && !entry.duplicateOf).length;
  const steps = cierreStepsStatus(accountRows, tasks);
  const highestUnlocked = steps.filter((item) => item.unlocked).map((item) => item.step).pop() || 1;
  if (cierreActiveStep > highestUnlocked) cierreActiveStep = highestUnlocked;

  const stepsEl = qs("cierreSteps");
  if (stepsEl) stepsEl.innerHTML = cierreStepsHtml(steps, cierreActiveStep);

  const body = qs("cierreStepBody");
  if (body) {
    if (cierreActiveStep === 1) body.innerHTML = cierreStep1Html(accountRows);
    else if (cierreActiveStep === 2) body.innerHTML = cierreStep2Html(tasks);
    else body.innerHTML = cierreStep3Html(accountRows, tasks, monthMovementCount, currentMonthKey);
  }
}

function handleCierreStepSelect(step) {
  cierreActiveStep = step;
  renderCierre();
}

function handleCierreDownload(kind) {
  if (!cierreEvidenceContext) return;
  const { accountRows, tasks, closure, currentMonthKey } = cierreEvidenceContext;
  handleCierreDownloadEvidence(kind, accountRows, tasks, closure, currentMonthKey);
}

async function handleCierreSign() {
  await closeCurrentMonthTransaction();
  const statusEl = qs("cierreStatus");
  if (statusEl) statusEl.textContent = qs("monthCloseStatus")?.textContent || "";
  renderCierre();
}

async function handleCierreReopen() {
  await reopenLatestMonthTransaction();
  const statusEl = qs("cierreStatus");
  if (statusEl) statusEl.textContent = qs("monthCloseStatus")?.textContent || "";
  renderCierre();
}

function renderConciliar() {
  if (!window.FinanceCanonicalLedger) return;
  const snapshot = refreshCanonicalLedger("conciliar-view");
  if (!snapshot) return;
  const quality = snapshot.quality || {};
  const months = snapshot.reconciliation?.months || [];
  const lines = snapshot.reconciliation?.lines || [];
  const entries = snapshot.entries || [];
  const checks = snapshot.balanceChecks || [];
  const differenceTotal = ledgerDifferenceTotal(snapshot);

  const unclassified = entries.filter((entry) => !entry.duplicateOf && entry.mapping?.status !== "classified");
  const differences = lines.filter((line) => Math.abs(Number(line.delta || 0)) > 0.02);
  const balanceGaps = checks.flatMap((check) => (check.gaps || []).map((gap, index) => ({ ...gap, id: `${check.accountId}-${index}`, accountId: check.accountId })));
  const tasks = E11bInbox ? E11bInbox.reconciliationTasks({ unclassified, differences, balanceGaps }) : [];

  const currentMonthKey = openMonthCutoffKey();
  const currentClosure = isClosedMonthKey(currentMonthKey) ? window.FinanceCanonicalE5?.latestMonthOperation({ monthClosures }, currentMonthKey) : null;
  const isClosed = Boolean(currentClosure);

  const titleEl = qs("conciliarTitle");
  if (titleEl) {
    titleEl.textContent = isClosed
      ? `${ledgerMonthLabel(currentMonthKey)} cerrado`
      : tasks.length
      ? `Faltan ${tasks.length} cosa(s) para cerrar ${ledgerMonthLabel(currentMonthKey)}`
      : `Nada pendiente para cerrar ${ledgerMonthLabel(currentMonthKey)}`;
  }
  const subtitleEl = qs("conciliarSubtitle");
  if (subtitleEl) subtitleEl.textContent = `Diferencia total banco vs. real: ${money(differenceTotal, true)}. Abrir una tarea no corrige nada por sí solo.`;

  const kpis = qs("conciliarKpis");
  if (kpis) {
    const gapCount = Number(quality.balanceGapCount || 0);
    kpis.innerHTML = [
      ["Movimientos del banco", String(Number(quality.transactionCount || 0)), ""],
      ["Clasificados", String(Number(quality.classifiedCount || 0)), ""],
      ["Diferencia banco vs. real", money(differenceTotal, true), differenceTotal > 0.02 ? " is-warn" : ""],
      ["Continuidad de saldos", gapCount ? `${gapCount} salto(s)` : "Correcta", gapCount ? " is-warn" : ""],
    ]
      .map(([label, value, tone]) => `<div class="e19-kpi${tone}"><span class="e19-kpi-label">${escapeHtml(label)}</span><span class="e19-kpi-value">${escapeHtml(value)}</span></div>`)
      .join("") + `<div class="e19-kpi${isClosed ? "" : " is-warn"}"><span class="e19-kpi-label">Estado</span><span class="e19-kpi-value">${isClosed ? "Cerrado" : "Abierto"}</span></div>`;
  }

  const taskList = qs("conciliarTasks");
  if (taskList) {
    taskList.innerHTML = tasks.length
      ? tasks
          .slice(0, 12)
          .map(
            (task, index) => `<li class="conciliar-task-item">
              <span class="conciliar-task-index">${index + 1}</span>
              <div>
                <strong>${escapeHtml(task.label)}</strong>
                <p>${task.cause === "unclassified" ? "Movimiento sin partida" : task.cause === "balance-gap" ? "Salto en la continuidad del saldo" : "Banco y real no coinciden"}. Abrir no modifica nada.</p>
              </div>
              <button type="button" class="e19-btn e19-btn-secondary" data-conciliar-task-target="${escapeHtml(task.target)}">${task.action === "classify" ? "Clasificar" : task.action === "adjust-balance" ? "Revisar saldo" : "Corregir real"}</button>
            </li>`
          )
          .join("")
      : `<li class="conciliar-task-item conciliar-task-empty">Sin tareas pendientes: clasificación, saldos e importes reales están conciliados.</li>`;
  }

  const checklist = qs("conciliarChecklist");
  if (checklist) {
    const checkItems = [
      { ok: unclassified.length === 0, label: unclassified.length === 0 ? "Todos los movimientos están clasificados" : `${unclassified.length} movimiento(s) sin clasificar` },
      { ok: Number(quality.balanceGapCount || 0) === 0, label: Number(quality.balanceGapCount || 0) === 0 ? "Continuidad de saldos correcta" : `${quality.balanceGapCount} salto(s) de saldo` },
      { ok: !isClosed, label: isClosed ? `Ya cerrado el ${escenarioMotorMonthLabel(currentMonthKey)}` : "Los reales quedarán congelados en una versión recuperable" },
    ];
    checklist.innerHTML = checkItems.map((check) => `<li class="deuda-ruta-check${check.ok ? " is-ok" : " is-danger"}">${escapeHtml(check.label)}</li>`).join("");
  }

  const history = qs("conciliarHistory");
  if (history) {
    const previousMonths = months.filter((row) => row.monthKey !== currentMonthKey).slice(-3).reverse();
    const rows = conciliarMonthHistory(previousMonths);
    history.innerHTML = rows.length
      ? rows
          .map(
            (row) => `<div class="conciliar-history-row"><span>${escapeHtml(ledgerMonthLabel(row.monthKey))}</span><strong class="${row.closed ? "is-ok" : "is-warn"}">${row.closed ? `Cerrado${row.reopenCount ? ` · reabierto ${row.reopenCount} vez${row.reopenCount > 1 ? "es" : ""}` : ""}` : "Abierto"}</strong></div>`
          )
          .join("")
      : `<p class="e19-kpi-note">Sin meses anteriores con extracto importado.</p>`;
  }

  const closeButton = qs("conciliarClose");
  if (closeButton) {
    closeButton.disabled = isClosed;
    closeButton.textContent = isClosed ? "Mes cerrado" : "Cerrar mes";
  }

  renderConciliarConfidence(entries, checks);
}

// V5-2 · «Confianza del dato» por cuenta (mockup 4f): las dos cuentas reales del hogar, no las
// «tres cuentas, una tarjeta» del mockup — este modelo no tiene tarjeta de crédito separada.
// «Descuadra» prioriza el error de continuidad de saldo (`check.totalError`) cuando existe, porque
// es literalmente un desajuste de saldo; si el saldo cuadra pero quedan movimientos sin clasificar
// de esa cuenta, «Descuadra» usa la suma de esos importes en su lugar, para no decir «Cuadra»
// mientras algo de la cuenta sigue sin decidir. Las diferencias banco-vs-real de `#conciliar` son
// mensuales, no por cuenta, así que no entran en esta cifra — omisión real, no un olvido.
const CONCILIAR_ACCOUNT_LABELS = { caixabank: "CaixaBank", mediolanum: "Mediolanum" };

function conciliarAccountConfidence(entries, checks) {
  return Object.entries(CONCILIAR_ACCOUNT_LABELS).map(([accountId, label]) => {
    const check = (checks || []).find((item) => item.accountId === accountId);
    const unclassified = (entries || []).filter(
      (entry) => entry.accountId === accountId && !entry.duplicateOf && entry.mapping?.status !== "classified",
    );
    if (!check) return { accountId, label, status: "sin-conciliar", amount: 0, unclassifiedCount: unclassified.length };
    if (check.gaps?.length) {
      return { accountId, label, status: "descuadra", amount: round2(Math.abs(Number(check.totalError || 0))), unclassifiedCount: unclassified.length };
    }
    if (unclassified.length) {
      const amount = round2(unclassified.reduce((sum, entry) => sum + Math.abs(Number(entry.amount || 0)), 0));
      return { accountId, label, status: "descuadra", amount, unclassifiedCount: unclassified.length };
    }
    return { accountId, label, status: "cuadra", amount: 0, unclassifiedCount: 0 };
  });
}

function conciliarConfidenceStateLabel(row) {
  if (row.status === "cuadra") return "Cuadra";
  if (row.status === "sin-conciliar") return "Sin conciliar";
  return `Descuadra ${money(row.amount, true)}`;
}

function renderConciliarConfidence(entries, checks) {
  const target = qs("conciliarConfidence");
  if (!target) return;
  target.innerHTML = conciliarAccountConfidence(entries, checks)
    .map(
      (row) => `<li class="conciliar-confidence-item is-${row.status}">
        <strong>${escapeHtml(row.label)}</strong>
        <span class="conciliar-confidence-state">${escapeHtml(conciliarConfidenceStateLabel(row))}</span>
      </li>`,
    )
    .join("");
}

// ---------------------------------------------------------------------------------------------
// Asesor ejecutivo (E20-2, mockup 1d). "La decisión abierta" = la oferta de deuda registrada más
// urgente en E14b (Plan de deuda) sin decisión aplicada todavía. No existe un motor de
// recomendación genérico capaz de fabricar una decisión con importe y vencimiento reales de la
// nada — a petición del usuario, se construye sobre las ofertas reales que el propio usuario
// registra en #debt-roadmap en vez de inventar una. Sin ninguna oferta abierta, la pantalla lo
// dice explícitamente en vez de simular una decisión que no existe.
// ---------------------------------------------------------------------------------------------
function asesorDecisionOpenOffers() {
  const workspace = e14bWorkspace();
  return workspace.offers
    .filter((offer) => offer.status !== "rejected" && !debtLiquidations.some((item) => item.targetId === offer.contractId))
    .slice()
    .sort((a, b) => String(a.expiresAt || "9999-99").localeCompare(String(b.expiresAt || "9999-99")));
}

// Cobertura estimada con los saldos reales de cada cuenta (accountBalancesFromState) — no un
// reparto ya decidido: solo muestra de dónde saldría el dinero si se pagara hoy con lo que hay.
function asesorDecisionFundingHtml(amount) {
  const balances = accountBalancesFromState();
  const sources = [
    { label: "Mediolanum", available: balances.mediolanum },
    { label: "CaixaBank", available: balances.caixa },
  ].filter((source) => source.available > 0);
  let remaining = amount;
  const rows = sources.map((source) => {
    const used = Math.max(0, Math.min(remaining, source.available));
    remaining = round2(remaining - used);
    return { ...source, used };
  });
  if (remaining > 0.01) rows.push({ label: "Sin cobertura con los saldos actuales", used: remaining, short: true });
  const total = Math.max(1, amount);
  return rows
    .filter((row) => row.used > 0)
    .map(
      (row) => `<div class="asesor-decision-funding-row${row.short ? " is-danger" : ""}">
        <span>${escapeHtml(row.label)}</span>
        <strong>${money(row.used, true)}</strong>
        <div class="asesor-decision-funding-bar"><span style="width:${Math.round((row.used / total) * 100)}%"></span></div>
      </div>`
    )
    .join("");
}

function renderAsesorDecision() {
  const offers = asesorDecisionOpenOffers();
  const emptyEl = qs("asesorDecisionEmpty");
  const contentEl = qs("asesorDecisionContent");
  if (!offers.length || !E14DebtOperations) {
    if (emptyEl) emptyEl.hidden = false;
    if (contentEl) contentEl.hidden = true;
    return;
  }
  if (emptyEl) emptyEl.hidden = true;
  if (contentEl) contentEl.hidden = false;

  const offer = offers[0];
  const contract = debtTargetById(offer.contractId, { includePlanned: true });
  const forecast = e14bForecast();
  const strategy = e14bStrategyForOffer(offer);
  const simulation = forecast?.valid && strategy ? E14DebtOperations.simulateStrategy(strategy, forecast) : null;
  const reserve = agentCaixaFloor();

  const deadline = qs("asesorDecisionDeadline");
  if (deadline) deadline.textContent = offer.expiresAt ? `Decisión abierta · vence ${escenarioMotorMonthLabel(offer.expiresAt)}` : "Decisión abierta · sin vencimiento indicado";
  const titleEl = qs("asesorDecisionTitle");
  if (titleEl) titleEl.textContent = `Pagar la oferta de ${offer.counterpart || "sin contraparte"}${contract ? ` · ${contract.entity}${contract.type ? ` ${contract.type}` : ""}` : ""}`;
  const amountEl = qs("asesorDecisionAmount");
  if (amountEl) amountEl.textContent = money(offer.amount, true);

  const statsEl = qs("asesorDecisionStats");
  if (statsEl) {
    statsEl.innerHTML = [
      ["Ahorras", money(offer.discount, true)],
      ["Cuota liberada", `${money(contract?.payment ?? 0, true)}/mes`],
      ["Caja mínima tras pagar", simulation ? money(simulation.minimumLiquidity, true) : "Sin forecast"],
    ]
      .map(([label, value]) => `<div class="asesor-decision-stat"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`)
      .join("");
  }

  const fundingEl = qs("asesorDecisionFunding");
  if (fundingEl) fundingEl.innerHTML = asesorDecisionFundingHtml(offer.amount);

  const applyLink = qs("asesorDecisionApply");
  if (applyLink) {
    applyLink.onclick = () => {
      e14bWorkspace().selectedOfferId = offer.id;
      queueRemoteSave();
    };
  }

  const limitsEl = qs("asesorDecisionLimits");
  if (limitsEl) {
    const p2Input = window.FinanceP2Bridge?.e16Input?.() || {};
    const maxDebtRatio = Number(p2Input.riskBudget?.maximumDebtRatio || 0);
    const debtRatio = Number(p2Input.debtRatio || 0);
    const next12 = lastSimulation.slice(0, Math.min(12, lastSimulation.length));
    const monthlyOutflow = next12.length ? next12.reduce((sum, row) => sum + row.coreSpend + row.car + row.refi, 0) / next12.length : 0;
    const bufferMonths = safeCoverageMonths(state.initialCash, monthlyOutflow);
    const bufferTarget = Number(state.emergencyBufferMonths || 0);
    const cajaOk = simulation ? simulation.minimumLiquidity >= reserve : null;
    const items = [
      { ok: cajaOk, label: `Reserva CaixaBank ${money(reserve, true)} mín.${simulation ? ` · queda en ${money(simulation.minimumLiquidity, true)}` : ""}` },
      { ok: bufferMonths === null ? null : bufferMonths >= bufferTarget, label: `Colchón ${bufferTarget} mes(es) obj. · ahora ${coverageMonthsText(bufferMonths)}` },
      { ok: maxDebtRatio ? debtRatio <= maxDebtRatio : null, label: maxDebtRatio ? `Deuda/ingresos ${maxDebtRatio}% máx. · ahora ${debtRatio}%` : `Deuda/ingresos ahora ${debtRatio}% (sin límite configurado en Presupuesto de riesgo)` },
    ];
    limitsEl.innerHTML = items.map((item) => `<li class="deuda-ruta-check${item.ok === false ? " is-danger" : item.ok ? " is-ok" : ""}">${escapeHtml(item.label)}</li>`).join("");
  }

  const queueEl = qs("asesorDecisionQueue");
  if (queueEl) {
    const rest = offers.slice(1);
    queueEl.innerHTML = rest.length
      ? rest
          .map(
            (item) => `<div class="conciliar-history-row"><span>${escapeHtml(item.counterpart || "Sin contraparte")}</span><strong>${money(item.amount, true)}${item.expiresAt ? ` · vence ${escapeHtml(escenarioMotorMonthLabel(item.expiresAt))}` : ""}</strong></div>`
          )
          .join("")
      : `<p class="e19-kpi-note">Sin más ofertas abiertas ahora mismo.</p>`;
  }

  const dataEl = qs("asesorDecisionData");
  if (dataEl) {
    const snapshot = window.FinanceCanonicalLedger ? refreshCanonicalLedger("asesor-decision-view") : null;
    const coverage = snapshot?.quality?.coverage;
    const items = [
      "Saldos: hoy, cuenta corriente + ahorro",
      Number.isFinite(coverage) ? `Conciliación: ${coverage}% de movimientos clasificados` : "Conciliación: sin datos de extracto",
      `Forecast: ${forecast?.valid ? "disponible" : "no disponible todavía"}`,
    ];
    dataEl.innerHTML = items.map((text) => `<li class="deuda-ruta-check">${escapeHtml(text)}</li>`).join("");
  }
}

// R-1 a R-4 · Registrar: única puerta de escritura de datos reales. Solo la pestaña «Saldo de
// cuentas» tiene contenido propio por ahora (R-3/R-4); Reales del mes/Importar extracto/Lote y
// Excel (R-5/R-8/R-9) enlazan de vuelta a su pantalla heredada hasta que se construyan. No se
// fabrica un recuento de pendientes para esas tres — mostrarían un cero que no es tal (regla
// transversal 04) — así que su insignia queda en HOME_MISSING_VALUE.
const REGISTRAR_TABS = [
  { id: "balances", label: "Saldo de cuentas" },
  { id: "actuals", label: "Reales del mes" },
  { id: "import", label: "Importar extracto" },
  { id: "batch", label: "Lote y Excel" },
];

function registrarBalanceStale() {
  if (!state) return false;
  return state.balanceMode === "manual" && (state.balanceDate || "") !== isoLocalDate(new Date());
}

// R-2 (auditoría del 15 de agosto, Prioridad 4): el criterio pide un recuento vivo en las cuatro
// pestañas; «import» y «batch» llevaban un marcador de «ausente» permanente, nunca un número.
// «import» sí tiene un recuento real que ofrecer — los movimientos de la sesión de importación en
// curso que piden decisión, el mismo `datosImportarCounters` que ya usa `homeImportSessionCandidate`
// (H-5) —; «batch» (pegar tabla/Excel) es una acción de un solo paso sin sesión que dejar a medias,
// así que no hay pendiente real que contar todavía: se deja vacío, igual que «balances» cuando no
// hay nada que avisar, en vez de fabricar un cero (regla transversal 04).
function registrarTabBadges() {
  const month = registrarActualsSelectedMonth();
  const pendingActuals = registrarActualsEntries(month).filter((entry) => !entry.hasActual).length;
  const importPending = datosImportarSession ? datosImportarCounters(datosImportarSession.rows).pidenDecision : 0;
  return {
    balances: registrarBalanceStale() ? "1 desactualizada" : "",
    actuals: !month ? HOME_MISSING_VALUE : pendingActuals ? `${pendingActuals} sin real` : "Al día",
    import: importPending ? `${importPending} por decidir` : "",
    batch: "",
  };
}

// R-5: la tabla de Reales del mes reutiliza el mismo modelo de datos y la misma puerta de
// escritura que ya usaba «Registrar el mes» (registrarMesCollect/actualsForKind/
// saveActualsForKind) — solo cambia la presentación: una tabla única (ingresos + gastos), filtro
// por bloque en vez de por estado, y una fila de totales que registrar-mes no tenía.
let registrarActualsBlockFilter = "todos";

function registrarActualsMonths() {
  return (baseData?.monthlyPlanning?.months || []).map((month) => ({
    key: month.key,
    label: month.label,
    closed: isClosedMonthKey(month.key),
  }));
}

function registrarActualsDefaultMonthKey() {
  const months = registrarActualsMonths();
  return months.find((month) => !month.closed)?.key || months[months.length - 1]?.key || "";
}

function registrarActualsSelectedMonth() {
  const months = baseData?.monthlyPlanning?.months || [];
  if (!months.length) return null;
  const key = qs("registrarActualsMonth")?.value || registrarActualsDefaultMonthKey();
  return months.find((month) => month.key === key) || months[0];
}

function registrarActualsEntries(month) {
  if (!month) return [];
  const collected = registrarMesCollect(month);
  return [...collected.income, ...collected.expense];
}

function registrarActualsBlocks(entries) {
  return [...new Set(entries.map((entry) => entry.sectionName))].sort((a, b) => a.localeCompare(b, "es"));
}

function registrarActualsStatus(entry) {
  if (!entry.hasActual) return { label: "Sin real", tone: "warn" };
  if (registrarMesIsBad(entry)) return { label: "Desviación", tone: "danger" };
  if (registrarMesIsOff(entry)) return { label: "A favor", tone: "good" };
  return { label: "Registrado", tone: "good" };
}

function registrarActualsTotals(entries) {
  const captured = entries.filter((entry) => entry.hasActual);
  const sum = (list, field) => round2(list.reduce((total, item) => total + Number(item[field] || 0), 0));
  return {
    planned: sum(entries, "planned"),
    used: sum(entries, "used"),
    variance: sum(captured, "variance"),
    lines: entries.length,
    captured: captured.length,
  };
}

// R-6b: el previsto de esta fila no se edita aquí (celda de solo lectura, ninguna escritura de
// `planned` en toda la pestaña) — el enlace lleva a Plan, la única pantalla donde se edita.
function registrarActualsRowHtml(entry, monthClosed) {
  const status = registrarActualsStatus(entry);
  return `<tr data-registrar-actuals-key="${escapeHtml(entry.key)}">
    <td>${escapeHtml(entry.sectionName)}</td>
    <td>${escapeHtml(entry.label)}<button type="button" class="registrar-actuals-plan-link" data-home-nav="cuadro-mandos">Ver en Plan</button></td>
    <td>${money(entry.planned, true)}</td>
    <td><input type="number" step="0.01" inputmode="decimal" data-registrar-actuals-actual="${escapeHtml(entry.key)}" data-registrar-actuals-kind="${escapeHtml(entry.kind)}" aria-label="Real de ${escapeHtml(entry.label)}" value="${entry.hasActual ? entry.actual : ""}" placeholder="sin real"${monthClosed ? " disabled" : ""} /></td>
    <td><strong>${money(entry.used, true)}</strong></td>
    <td class="${varianceClassForKind(entry.kind, entry.hasActual ? entry.variance : "")}">${entry.hasActual ? registrarMesSignedMoney(entry.variance) : "—"}</td>
    <td><span class="status-pill ${status.tone}">${escapeHtml(status.label)}</span></td>
  </tr>`;
}

function renderRegistrarActuals() {
  const select = qs("registrarActualsMonth");
  if (!select) return;
  const months = registrarActualsMonths();
  const previous = select.value;
  select.innerHTML = months
    .map((month) => `<option value="${escapeHtml(month.key)}">${escapeHtml(month.label)}${month.closed ? " · cerrado" : ""}</option>`)
    .join("");
  select.value = months.some((month) => month.key === previous) ? previous : registrarActualsDefaultMonthKey();

  const month = registrarActualsSelectedMonth();
  const monthClosed = Boolean(month && isClosedMonthKey(month.key));
  if (qs("registrarActualsClosedNote")) qs("registrarActualsClosedNote").hidden = !monthClosed;

  const allEntries = registrarActualsEntries(month);
  const blocks = registrarActualsBlocks(allEntries);
  if (registrarActualsBlockFilter !== "todos" && !blocks.includes(registrarActualsBlockFilter)) {
    registrarActualsBlockFilter = "todos";
  }
  const filtersEl = qs("registrarActualsFilters");
  if (filtersEl) {
    filtersEl.innerHTML = ["todos", ...blocks]
      .map((value) => {
        const count = value === "todos" ? allEntries.length : allEntries.filter((entry) => entry.sectionName === value).length;
        const isActive = registrarActualsBlockFilter === value;
        return `<button type="button" class="registrar-actuals-filter${isActive ? " is-active" : ""}" data-registrar-actuals-block="${escapeHtml(value)}" aria-pressed="${isActive ? "true" : "false"}">${escapeHtml(value === "todos" ? "Todos" : value)} (${count})</button>`;
      })
      .join("");
  }

  const visible = registrarActualsBlockFilter === "todos"
    ? allEntries
    : allEntries.filter((entry) => entry.sectionName === registrarActualsBlockFilter);

  if (qs("registrarActualsBody")) {
    qs("registrarActualsBody").innerHTML = visible.length
      ? visible.map((entry) => registrarActualsRowHtml(entry, monthClosed)).join("")
      : `<tr><td colspan="7" class="registrar-mes-empty">Este bloque no tiene partidas este mes.</td></tr>`;
  }

  const totals = registrarActualsTotals(visible);
  if (qs("registrarActualsTotals")) {
    qs("registrarActualsTotals").innerHTML = `<tr class="registrar-actuals-totals-row">
      <td colspan="2">Total (${totals.captured}/${totals.lines} con real)</td>
      <td>${money(totals.planned, true)}</td>
      <td></td>
      <td><strong>${money(totals.used, true)}</strong></td>
      <td>${totals.captured ? registrarMesSignedMoney(totals.variance) : "—"}</td>
      <td></td>
    </tr>`;
  }
}

function handleRegistrarActualsChange(input) {
  const month = registrarActualsSelectedMonth();
  if (!month || isClosedMonthKey(month.key)) return;
  const kind = input.dataset.registrarActualsKind;
  const key = input.dataset.registrarActualsActual;
  if (!kind || !key) return;
  const actuals = actualsForKind(kind);
  const previous = Object.prototype.hasOwnProperty.call(actuals, key) ? actuals[key] : null;
  if (input.value === "") delete actuals[key];
  else actuals[key] = Number(input.value);
  const next = Object.prototype.hasOwnProperty.call(actuals, key) ? actuals[key] : null;
  if (next !== previous) registrarRecordSessionChange({ kind: "actual", actualsKind: kind, key, previous });
  saveActualsForKind(kind)();
  render();
}

function setRegistrarTab(tabId) {
  registrarActiveTab = REGISTRAR_TABS.some((tab) => tab.id === tabId) ? tabId : "balances";
  renderRegistrarTabs();
  // R-8: la pestaña Importar extracto pinta el asistente de cuatro pasos al entrar, igual que
  // #datos-importar lo hace al abrirse — sin esto, la primera visita mostraría el panel vacío
  // hasta el siguiente cambio de datos.
  if (registrarActiveTab === "import") renderDatosImportar();
}

function renderRegistrarTabs() {
  const nav = qs("registrarTabs");
  if (!nav) return;
  const badges = registrarTabBadges();
  nav.querySelectorAll("[data-registrar-tab]").forEach((button) => {
    const isActive = button.dataset.registrarTab === registrarActiveTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  nav.querySelectorAll("[data-registrar-badge]").forEach((badge) => {
    badge.textContent = badges[badge.dataset.registrarBadge] || "";
  });
  document.querySelectorAll("[data-registrar-panel]").forEach((panel) => {
    panel.hidden = panel.dataset.registrarPanel !== registrarActiveTab;
  });
  const activeTab = REGISTRAR_TABS.find((tab) => tab.id === registrarActiveTab);
  if (qs("registrarCrumb")) qs("registrarCrumb").textContent = `Registrar › ${activeTab?.label || ""}`;
}

function renderRegistrarHeaderMeta() {
  const meta = qs("registrarSourceNote");
  if (!meta) return;
  const source = state?.balanceMode === "manual" ? "saldos declarados a mano" : "libro canónico calculado";
  const savedAt = lastLocalSaveAt
    ? `guardado hace poco, a las ${new Date(lastLocalSaveAt).toLocaleTimeString("es-ES", { hour: "2-digit", minute: "2-digit" })}`
    : "sin guardar todavía en esta sesión";
  meta.innerHTML = `<span class="e19-registrar-meta-item">Fuente del libro: ${escapeHtml(source)} · ${escapeHtml(savedAt)}</span>
    <span class="e19-registrar-meta-item">Flujo: Saldo de cuentas → Reales del mes → Importar extracto → Lote y Excel</span>`;
}

// R-4: mismas cuatro cifras que ya calcula Hoy (unifiedActionCenterModel/homeDebtOutlook), más el
// peor mes del horizonte completo con FinanceCanonicalCushion.worstMonthOf — sin recalcular nada
// por su cuenta, solo se leen aquí para que se vean también mientras se registra.
function registrarRecalcFigures() {
  const actionCenter = unifiedActionCenterModel();
  const ctx = actionCenter.context || {};
  const today = ctx.today || {};
  const protectedReserve = round2(Number(today.requiredReserve || ctx.immediateTransfer?.reserve || agentCaixaFloor()));
  const coverage = actionCenter.coverage || {};
  const debtOutlook = homeDebtOutlook();
  const worst = FinanceCanonicalCushion.worstMonthOf(openSimulationRows(lastSimulation));
  return [
    { label: "Reserva protegida", value: money(protectedReserve, true) },
    {
      label: "Cobertura hasta el siguiente ingreso",
      value: coverage.days === null || coverage.days === undefined ? HOME_MISSING_VALUE : `${coverage.days} día(s)`,
    },
    { label: "Fecha libre de deuda", value: debtOutlook.libreDeDeudaLabel || HOME_MISSING_VALUE },
    {
      label: "Peor mes del horizonte",
      value: worst ? `${escenarioMotorMonthLabel(worst.key)} · ${money(worst.value, true)}` : HOME_MISSING_VALUE,
    },
  ];
}

function renderRegistrarRecalcCard() {
  const grid = qs("registrarRecalcGrid");
  if (!grid) return;
  grid.innerHTML = registrarRecalcFigures()
    .map((item) => `<div class="e19-registrar-recalc-item"><span>${escapeHtml(item.label)}</span><strong>${escapeHtml(item.value)}</strong></div>`)
    .join("");
}

// R-3: "delta frente al guardado por cuenta" — no una cifra pendiente escondida, sino el hueco
// vivo entre lo que hay tecleado y lo último que de verdad se guardó. La foto se retoma cada vez
// que se guarda (resetRegistrarBalanceBaseline) para que el delta vuelva a cero al confirmar.
function resetRegistrarBalanceBaseline() {
  const balances = accountBalancesFromState();
  registrarBalanceBaseline = { caixa: balances.caixa, mediolanum: balances.mediolanum };
  renderRegistrarBalanceDelta();
}

function registrarDeltaText(current, baseline) {
  if (!Number.isFinite(current) || !Number.isFinite(baseline)) return "";
  const delta = round2(current - baseline);
  if (delta === 0) return "Sin cambios frente al guardado.";
  return `${delta > 0 ? "+" : ""}${money(delta, true)} frente al guardado.`;
}

function renderRegistrarBalanceDelta() {
  if (!registrarBalanceBaseline) return;
  const caixaEl = document.querySelector('[data-registrar-delta="caixa"]');
  const mediolanumEl = document.querySelector('[data-registrar-delta="mediolanum"]');
  if (caixaEl) caixaEl.textContent = registrarDeltaText(parseAmount(qs("registrarCaixaBalance")?.value), registrarBalanceBaseline.caixa);
  if (mediolanumEl) {
    mediolanumEl.textContent = registrarDeltaText(parseAmount(qs("registrarMediolanumBalance")?.value), registrarBalanceBaseline.mediolanum);
  }
}

// R-7: mismas fuentes que registrarRecalcFigures (unifiedActionCenterModel/homeDebtOutlook/
// FinanceCanonicalCushion), pero en crudo — para poder compararlas contra la foto del inicio de la
// sesión. No se duplica registrarRecalcFigures en sí (queda intacta, con sus pruebas) porque esta
// función necesita números, no las cadenas ya formateadas para la tarjeta de R-4.
function registrarSessionMetrics() {
  const actionCenter = unifiedActionCenterModel();
  const ctx = actionCenter.context || {};
  const today = ctx.today || {};
  const balances = ctx.balances || accountBalancesFromState();
  const protectedReserve = round2(Number(today.requiredReserve || ctx.immediateTransfer?.reserve || agentCaixaFloor()));
  const currentLiquidity = round2(Number(balances.total || 0));
  const coverage = actionCenter.coverage || {};
  const debtOutlook = homeDebtOutlook();
  const worst = FinanceCanonicalCushion.worstMonthOf(openSimulationRows(lastSimulation));
  return {
    reserveMargin: round2(currentLiquidity - protectedReserve),
    coverageDays: coverage.days === null || coverage.days === undefined ? null : Number(coverage.days),
    debtFreeDateRank: debtStrategyLibreDeDeudaRank(debtOutlook.libreDeDeuda),
    debtFreeDateLabel: debtOutlook.libreDeDeudaLabel || HOME_MISSING_VALUE,
    worstMonthValue: worst ? round2(Number(worst.value || 0)) : null,
    worstMonthLabel: worst ? `${escenarioMotorMonthLabel(worst.key)} · ${money(worst.value, true)}` : HOME_MISSING_VALUE,
  };
}

// Cuatro cifras de la sesión completa (no de la última casilla tocada): cada una compara el valor
// actual contra la foto tomada antes del primer cambio sin consolidar.
function registrarImpactRows(baseline, current) {
  const reserveDelta = round2(current.reserveMargin - baseline.reserveMargin);
  const coverageDelta = current.coverageDays === null || baseline.coverageDays === null ? null : current.coverageDays - baseline.coverageDays;
  const worstDelta = current.worstMonthValue === null || baseline.worstMonthValue === null ? null : round2(current.worstMonthValue - baseline.worstMonthValue);
  return [
    {
      label: "Reserva sobre el mínimo",
      value: money(current.reserveMargin, true),
      note: reserveDelta === 0 ? "Sin cambios en la sesión" : `${reserveDelta > 0 ? "+" : ""}${money(reserveDelta, true)} en la sesión`,
      warn: current.reserveMargin < 0,
    },
    {
      label: "Cobertura hasta el siguiente ingreso",
      value: current.coverageDays === null ? HOME_MISSING_VALUE : `${current.coverageDays} día(s)`,
      note: !coverageDelta ? "Sin cambios en la sesión" : `${coverageDelta > 0 ? "+" : ""}${coverageDelta} día(s) en la sesión`,
    },
    {
      label: "Fecha libre de deuda",
      value: current.debtFreeDateLabel,
      note: current.debtFreeDateRank === baseline.debtFreeDateRank ? "Sin cambios en la sesión" : "Cambia frente al inicio de la sesión",
    },
    {
      label: "Peor mes del horizonte",
      value: current.worstMonthLabel,
      note: !worstDelta ? "Sin cambios en la sesión" : `${worstDelta > 0 ? "+" : ""}${money(worstDelta, true)} en la sesión`,
    },
  ];
}

function registrarBeginSessionTrackingIfNeeded() {
  if (registrarSessionChanges.length === 0) registrarSessionBaselineMetrics = registrarSessionMetrics();
}

// Un cambio por casilla, no uno por pulsación: si la misma casilla ya está en el registro, se
// conserva el valor anterior de la primera vez que se tocó en la sesión (para que "Descartar todo"
// devuelva lo que había al empezar, no lo que había hace un segundo).
function registrarRecordSessionChange(entry) {
  const matches = (change) => {
    if (change.kind !== entry.kind) return false;
    if (change.kind === "balance") return change.field === entry.field;
    return change.actualsKind === entry.actualsKind && change.key === entry.key;
  };
  if (registrarSessionChanges.some(matches)) return;
  registrarBeginSessionTrackingIfNeeded();
  registrarSessionChanges.push(entry);
}

function registrarClearSessionTracking() {
  registrarSessionChanges = [];
  registrarSessionBaselineMetrics = null;
}

// "Descartar todo" revierte cada casilla tocada a su valor anterior a la sesión, escribiendo por
// los mismos caminos que ya usa el guardado normal (setStateAccountBalances/actualsForKind) — no
// es un segundo mecanismo de escritura, es el mismo aplicado hacia atrás.
function registrarDiscardSessionChanges() {
  if (!registrarSessionChanges.length) return;
  const balanceChanges = registrarSessionChanges.filter((change) => change.kind === "balance");
  if (balanceChanges.length) {
    const current = accountBalancesFromState();
    const restored = { caixa: current.caixa, mediolanum: current.mediolanum };
    balanceChanges.forEach((change) => {
      restored[change.field] = change.previous;
    });
    setStateAccountBalances(restored);
    saveBalanceSettings();
  }
  const actualChanges = registrarSessionChanges.filter((change) => change.kind === "actual");
  const actualsKindsTouched = new Set();
  actualChanges.forEach((change) => {
    const actuals = actualsForKind(change.actualsKind);
    if (change.previous === null) delete actuals[change.key];
    else actuals[change.key] = change.previous;
    actualsKindsTouched.add(change.actualsKind);
  });
  actualsKindsTouched.forEach((kind) => saveActualsForKind(kind)());
  registrarClearSessionTracking();
  render();
}

// "Guardar cambios" no escribe nada nuevo (cada casilla ya se guardó al salir de ella, regla
// transversal de R-6) — solo cierra el seguimiento de la sesión. Si la reserva sobre el mínimo
// queda en negativo, pide una confirmación explícita antes de cerrar.
function registrarConsolidateSessionChanges() {
  if (!registrarSessionChanges.length) return;
  const current = registrarSessionMetrics();
  if (current.reserveMargin < 0 && !window.confirm("La reserva queda por debajo del mínimo con estos cambios. ¿Seguro que quieres consolidarlos?")) {
    return;
  }
  registrarClearSessionTracking();
  registrarSessionConsolidatedNote = "Cambios de la sesión consolidados.";
  renderRegistrarImpactFooter();
  window.setTimeout(() => {
    registrarSessionConsolidatedNote = "";
    renderRegistrarImpactFooter();
  }, 2000);
}

function renderRegistrarImpactFooter() {
  const bar = qs("registrarImpactBar");
  if (!bar) return;
  if (registrarSessionConsolidatedNote) {
    bar.hidden = false;
    bar.classList.remove("is-warning");
    bar.innerHTML = `<p class="e19-registrar-impact-note">${escapeHtml(registrarSessionConsolidatedNote)}</p>`;
    return;
  }
  if (!registrarSessionChanges.length || !registrarSessionBaselineMetrics) {
    bar.hidden = true;
    bar.innerHTML = "";
    return;
  }
  const current = registrarSessionMetrics();
  const rows = registrarImpactRows(registrarSessionBaselineMetrics, current);
  const belowMinimum = current.reserveMargin < 0;
  bar.hidden = false;
  bar.classList.toggle("is-warning", belowMinimum);
  bar.innerHTML = `
    <div class="e19-registrar-impact-head">
      <p class="e19-eyebrow">Impacto de la sesión</p>
      <small>${registrarSessionChanges.length} cambio(s) sin consolidar${belowMinimum ? " · reserva bajo el mínimo" : ""}</small>
    </div>
    ${rows
      .map(
        (row) => `<dl><dt>${escapeHtml(row.label)}</dt><dd${row.warn ? " class=\"is-warning\"" : ""}>${escapeHtml(row.value)}</dd><small>${escapeHtml(row.note)}</small></dl>`
      )
      .join("")}
    <div class="e19-registrar-impact-actions">
      <button type="button" class="e19-btn e19-btn-secondary" data-registrar-impact-discard>Descartar todo</button>
      <button type="button" class="e19-btn e19-btn-primary" data-registrar-impact-save>Guardar cambios</button>
    </div>`;
}

function renderRegistrar() {
  if (!qs("registrarBalancePanel")) return;
  renderRegistrarHeaderMeta();
  renderRegistrarActuals();
  renderRegistrarTabs();
  renderRegistrarRecalcCard();
  resetRegistrarBalanceBaseline();
  renderRegistrarImpactFooter();
}

/* --------------------------------------------------------------------------------------------- */
/* P-1 a P-7 · Plan: pestaña Mes (mockups 04, Fase 2)                                              */
/*                                                                                                 */
/* Pantalla nueva `#plan`, junto a `#cuadro-mandos` (que sigue intacta y accesible desde           */
/* «Herramientas avanzadas»), no en su lugar — mismo patrón que Registrar con `#update-data`. Solo */
/* la pestaña «Mes» tiene contenido propio: «Previsión» y «Ahorro» enlazan de vuelta a sus         */
/* pantallas heredadas (`#prevision`, `#savings-plan`) hasta que se construyan.                    */
/*                                                                                                 */
/* El previsto editable reutiliza tal cual `visualDraftCells`/`cuadroMandosStageCell` — el mismo   */
/* borrador de sesión que ya usa Cuadro de mandos desde E11 (regla transversal 01): un cambio aquí */
/* aparece también allí y en Cambios pendientes, y «Guardar cambios» es literalmente               */
/* `saveVisualChanges`. El pie de impacto (P-6) reutiliza el mismo componente `.e19-impact-bar` que */
/* ya usa Registrar (R-7) y el mismo cálculo de antes/después que ya usaba Cuadro de mandos         */
/* (`cuadroMandosImpact`) — no un tercer motor de comparación.                                     */
/* --------------------------------------------------------------------------------------------- */

const PLAN_TABS = [
  { id: "mes", label: "Mes" },
  { id: "prevision", label: "Previsión" },
  { id: "ahorro", label: "Ahorro" },
];
let planActiveTab = "mes";
let planMesCopyPending = false;

function setPlanTab(tabId) {
  planActiveTab = PLAN_TABS.some((tab) => tab.id === tabId) ? tabId : "mes";
  renderPlanTabs();
}

function renderPlanTabs() {
  const nav = qs("planTabs");
  if (!nav) return;
  nav.querySelectorAll("[data-plan-tab]").forEach((button) => {
    const isActive = button.dataset.planTab === planActiveTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  document.querySelectorAll("[data-plan-panel]").forEach((panel) => {
    panel.hidden = panel.dataset.planPanel !== planActiveTab;
  });
  const activeTab = PLAN_TABS.find((tab) => tab.id === planActiveTab);
  if (qs("planCrumb")) qs("planCrumb").textContent = `Plan › ${activeTab?.label || ""}`;
}

function planMesSelectedMonth() {
  const months = cuadroMandosAllMonths();
  if (!months.length) return null;
  const select = qs("planMesMonth");
  const match = months.find((month) => month.key === select?.value);
  return match || months.find((month) => !isClosedMonthKey(month.key)) || months[0];
}

function planMesPopulateMonths(months, selected) {
  const select = qs("planMesMonth");
  if (!select) return;
  const previous = select.value;
  select.innerHTML = months
    .map((month) => `<option value="${escapeHtml(month.key)}">${escapeHtml(month.label)}${isClosedMonthKey(month.key) ? " · cerrado" : ""}</option>`)
    .join("");
  const keep = months.some((month) => month.key === previous) ? previous : selected?.key;
  if (keep) select.value = keep;
}

// P-2/P-3/P-4: una fila por partida, mismo patrón que `registrarMesCollect`, pero sobre el
// previsto (editable vía `cuadroMandosCellValue`, draft-aware) en vez del real. «Usado» y
// «Desviación» se recalculan con el previsto en borrador, no solo con el ya guardado, para que el
// impacto de editar se vea antes de guardar.
function planMesCollect(month) {
  const result = { income: [], expense: [] };
  if (!month) return result;
  ["income", "expense"].forEach((kind) => {
    planningSectionsForMonth(kind, month).forEach((section) => {
      section.rows.forEach((row) => {
        const cell = cuadroMandosCellValue(row, month);
        const info = actualAwareInfo(row, month);
        const hasActual = Boolean(info.hasActual);
        const usado = hasActual ? Number(info.actual || 0) : cell.value;
        result[kind].push({
          kind,
          row,
          sectionName: section.name,
          label: displayLabelForRow(row),
          planned: cell.value,
          plannedDraft: cell.draft,
          hasActual,
          usado,
          variance: hasActual ? round2(usado - cell.value) : null,
          key: `${kind}:${seriesKeyForRow(row)}`,
        });
      });
    });
  });
  return result;
}

function planMesTotals(entries) {
  const sum = (list, field) => list.reduce((total, item) => total + Number(item[field] || 0), 0);
  return {
    incomePlanned: round2(sum(entries.income, "planned")),
    expensePlanned: round2(sum(entries.expense, "planned")),
    lines: entries.income.length + entries.expense.length,
  };
}

// P-3: las cuotas de deuda son de solo lectura en Plan · Mes — su puerta canónica ya es
// Deuda › Contratos (D-2). La auditoría del 15 de agosto encontró que aquí seguían siendo
// editables, una segunda puerta para el mismo dato (regla transversal 01).
// P-4 (auditoría del 15 de agosto, Prioridad 4): el criterio pide que «Usado» diga al pasar por
// encima de dónde sale y cuántos movimientos lo componen. Cuenta contra `baseData.transactions` del
// mes con el mismo diccionario `mappingForMovement` que ya usa la detección de partida anual
// (`registrarMesAnnualMatch`) — no un segundo camino de correspondencia. Un real sin movimientos
// mapeados es un ajuste a mano en Registrar (override o real suelto), no un error.
function planMesUsadoMovementCount(entry, monthKey) {
  return (baseData?.transactions || []).filter(
    (transaction) => transaction.month === monthKey && mappingForMovement(transaction)?.row === entry.row,
  ).length;
}

function planMesUsadoTitle(entry, monthKey) {
  const monthLabel = ledgerMonthLabel(monthKey);
  if (!entry.hasActual) return `Previsto: sin movimientos registrados en ${monthLabel} todavía.`;
  const count = planMesUsadoMovementCount(entry, monthKey);
  return count
    ? `Real: ${count} movimiento${count === 1 ? "" : "s"} de ${monthLabel}.`
    : "Real: importe introducido a mano en Registrar › Reales del mes.";
}

function planMesIsFinancingRowKey(rowKey) {
  const section = baseData?.monthlyPlanning?.sections?.find((item) => item.name === "Financiaciones");
  if (!section) return false;
  return section.rows.some((row) => seriesKeyForRow(row) === rowKey);
}

// P-2 (auditoría del 15 de agosto, Prioridad 3): con la tabla agrupada por bloque (más abajo), el
// nombre de sección de cada fila ya lo dice la cabecera de bloque — repetirlo en una columna propia
// era ruido. Se retira la celda «Bloque»; `data-plan-mes-block` sigue en la fila para que el
// plegado (`handlePlanMesBlockToggle`) sepa a qué bloque pertenece.
function planMesRowHtml(entry, monthClosed, monthKey, collapsed = false) {
  const rowKey = seriesKeyForRow(entry.row);
  const isFinancing = entry.sectionName === "Financiaciones";
  const plannedCell = isFinancing
    ? `<span class="plan-mes-financing-readonly">${money(entry.planned, true)}<small>se cambia en <button type="button" class="registrar-actuals-plan-link" data-home-nav="deuda-contratos">Deuda</button></small></span>`
    : `<input type="number" step="0.01" inputmode="decimal" data-plan-mes-planned="${escapeHtml(rowKey)}" data-plan-mes-month="${escapeHtml(monthKey)}" aria-label="Previsto de ${escapeHtml(entry.label)}" value="${entry.planned}"${monthClosed ? " disabled" : ""} />`;
  return `<tr data-plan-mes-key="${escapeHtml(entry.key)}" data-plan-mes-block="${escapeHtml(entry.sectionName)}"${entry.plannedDraft ? ' class="plan-mes-row-draft"' : ""}${collapsed ? " hidden" : ""}>
    <td class="registrar-mes-concept">${escapeHtml(entry.label)}</td>
    <td>${plannedCell}</td>
    <td data-plan-mes-cell="usado"><strong>${money(entry.usado, true)}</strong> <small class="e19-kpi-meta" title="${escapeHtml(planMesUsadoTitle(entry, monthKey))}">${entry.hasActual ? "real" : "previsto"}</small></td>
    <td data-plan-mes-cell="variance" class="${varianceClassForKind(entry.kind, entry.hasActual ? entry.variance : "")}">${entry.hasActual ? registrarMesSignedMoney(entry.variance) : "—"}</td>
  </tr>`;
}

// P-2: bloques en el orden real en que aparecen las filas (baseData.monthlyPlanning.sections —
// Gastos fijos, Gastos variables, Financiaciones —, no una taxonomía inventada como la del mockup),
// con el subtotal de previsto de cada uno. `Set` de nombre de sección, no de índice, para que
// colapsar/expandir sobreviva a que cambien las partidas del mes.
let planMesCollapsedBlocks = new Set();

function planMesGroupBySection(list) {
  const order = [];
  const bySection = new Map();
  list.forEach((entry) => {
    if (!bySection.has(entry.sectionName)) {
      bySection.set(entry.sectionName, []);
      order.push(entry.sectionName);
    }
    bySection.get(entry.sectionName).push(entry);
  });
  return order.map((sectionName) => {
    const sectionEntries = bySection.get(sectionName);
    return { sectionName, entries: sectionEntries, subtotal: round2(sectionEntries.reduce((sum, entry) => sum + Number(entry.planned || 0), 0)) };
  });
}

function planMesBlockRowHtml(block) {
  const collapsed = planMesCollapsedBlocks.has(block.sectionName);
  return `<tr class="plan-mes-block-row">
    <td colspan="3">
      <button type="button" class="plan-mes-block-toggle" data-plan-mes-block-toggle="${escapeHtml(block.sectionName)}" aria-expanded="${collapsed ? "false" : "true"}">
        <span class="plan-mes-block-caret" aria-hidden="true"></span>${escapeHtml(block.sectionName)}
      </button>
    </td>
    <td class="plan-mes-block-subtotal">${money(block.subtotal, true)}</td>
  </tr>`;
}

// P-2: «una sola tabla «Presupuesto de [mes]» con cabeceras de sección... y subtotal por bloque,
// plegable». Sustituye la tarjeta plana de Gastos; Ingresos se queda como estaba (el mockup tampoco
// la itemiza dentro de esta tabla — su previsto ya vive en los KPI de arriba, en
// `planMesKpis`/`INGRESO PREVISTO`).
function planMesBudgetTableHtml(list, month, monthClosed) {
  const blocks = planMesGroupBySection(list);
  const body = blocks.length
    ? blocks
        .map((block) => {
          const collapsed = planMesCollapsedBlocks.has(block.sectionName);
          const rows = block.entries.map((entry) => planMesRowHtml(entry, monthClosed, month.key, collapsed)).join("");
          return `${planMesBlockRowHtml(block)}${rows}`;
        })
        .join("")
    : `<tr><td colspan="4" class="registrar-mes-empty">Este mes no tiene partidas de este tipo.</td></tr>`;
  return `<article class="e19-card registrar-mes-card">
    <div class="registrar-mes-card-head"><h3 class="escenario-motor-panel-title">Presupuesto de ${escapeHtml(month.label)}</h3></div>
    <div class="table-wrap">
      <table class="e19-table registrar-mes-table plan-mes-budget-table">
        <thead><tr><th>Partida</th><th>Previsto</th><th>Usado</th><th>Desviación</th></tr></thead>
        <tbody>${body}</tbody>
      </table>
    </div>
  </article>`;
}

function handlePlanMesBlockToggle(sectionName) {
  if (!sectionName) return;
  if (planMesCollapsedBlocks.has(sectionName)) planMesCollapsedBlocks.delete(sectionName);
  else planMesCollapsedBlocks.add(sectionName);
  renderPlanMes();
}

function planMesPreviousMonth(month) {
  const months = cuadroMandosAllMonths();
  const index = months.findIndex((item) => item.key === month.key);
  return index > 0 ? months[index - 1] : null;
}

// P-7: copia el previsto (ya con sus posibles overrides) del mes anterior al actual, solo para las
// partidas donde de verdad cambia — mismo `cuadroMandosStageCell` que un cambio manual, así que se
// revisa en el pie de impacto antes de guardar, nunca se escribe directo.
function planMesCopyCandidates(month) {
  const previous = planMesPreviousMonth(month);
  if (!previous) return [];
  const entries = planMesCollect(month);
  const previousEntries = planMesCollect(previous);
  const previousByKey = new Map();
  [...previousEntries.income, ...previousEntries.expense].forEach((entry) => previousByKey.set(seriesKeyForRow(entry.row), entry.planned));
  const candidates = [];
  [...entries.income, ...entries.expense].forEach((entry) => {
    const rowKey = seriesKeyForRow(entry.row);
    if (!previousByKey.has(rowKey)) return;
    const previousValue = previousByKey.get(rowKey);
    if (Math.abs(previousValue - entry.planned) < 0.005) return;
    candidates.push({ rowKey, monthKey: month.key, value: previousValue });
  });
  return candidates;
}

function planMesCopyHtml(month) {
  const previous = planMesPreviousMonth(month);
  if (!previous) return `<p class="e19-kpi-note">No hay un mes anterior en el plan.</p>`;
  if (!planMesCopyPending) {
    return `<button type="button" class="registrar-mes-link" data-plan-mes-copy>Copiar previsto de ${escapeHtml(previous.label)}</button>`;
  }
  const candidates = planMesCopyCandidates(month);
  return `<p class="e19-kpi-note">Se copiarán ${candidates.length} previsto(s) de ${escapeHtml(previous.label)} a este mes.</p>
    <button type="button" class="e19-btn e19-btn-primary" data-plan-mes-copy-confirm>Confirmar copia</button>
    <button type="button" class="e19-btn e19-btn-secondary" data-plan-mes-copy-cancel>Cancelar</button>`;
}

function planMesCardHtml(label, list, month, monthClosed) {
  const body = list.length
    ? list.map((entry) => planMesRowHtml(entry, monthClosed, month.key)).join("")
    : `<tr><td colspan="4" class="registrar-mes-empty">Este mes no tiene partidas de este tipo.</td></tr>`;
  return `<article class="e19-card registrar-mes-card">
    <div class="registrar-mes-card-head"><h3 class="escenario-motor-panel-title">${escapeHtml(label)}</h3></div>
    <div class="table-wrap">
      <table class="e19-table registrar-mes-table">
        <thead><tr><th>Concepto</th><th>Previsto</th><th>Usado</th><th>Desviación</th></tr></thead>
        <tbody>${body}</tbody>
      </table>
    </div>
  </article>`;
}

function renderPlanMes() {
  if (!qs("planMesTables") || !baseData?.monthlyPlanning?.months?.length) return;
  const months = cuadroMandosAllMonths();
  const month = planMesSelectedMonth();
  planMesPopulateMonths(months, month);
  if (!month) return;
  const monthClosed = isClosedMonthKey(month.key);
  const entries = planMesCollect(month);
  const totals = planMesTotals(entries);

  // P-5: techo de asignación — el previsto de gastos no puede superar, en la lectura de esta
  // pantalla, el previsto de ingresos del mismo mes. No bloquea nada por sí solo (regla
  // transversal 02: nada se aplica sin guardar), solo avisa.
  const overCeiling = totals.expensePlanned > totals.incomePlanned;
  const kpis = qs("planMesKpis");
  if (kpis) {
    kpis.innerHTML = [
      `<div class="e19-kpi"><span class="e19-kpi-label">Previsto ingresos</span><span class="e19-kpi-value">${money(totals.incomePlanned, true)}</span></div>`,
      `<div class="e19-kpi${overCeiling ? " is-danger" : ""}"><span class="e19-kpi-label">Previsto gastos</span><span class="e19-kpi-value">${money(totals.expensePlanned, true)}</span></div>`,
      `<div class="e19-kpi${overCeiling ? " is-danger" : ""}"><span class="e19-kpi-label">Techo de asignación</span><span class="e19-kpi-value">${money(round2(totals.incomePlanned - totals.expensePlanned), true)}</span><span class="e19-kpi-meta">${overCeiling ? "Previsto gastos supera previsto ingresos" : "Previsto ingresos menos previsto gastos"}</span></div>`,
      `<div class="e19-kpi"><span class="e19-kpi-label">Partidas</span><span class="e19-kpi-value">${totals.lines}</span></div>`,
    ].join("");
  }

  const container = qs("planMesTables");
  container.innerHTML = `${planMesCardHtml("Ingresos", entries.income, month, monthClosed)}${planMesBudgetTableHtml(entries.expense, month, monthClosed)}
    <div class="registrar-mes-card-foot">${monthClosed ? `<p class="e19-kpi-note">El mes está cerrado: el previsto queda congelado tal y como se cerró.</p>` : planMesCopyHtml(month)}</div>`;

  renderPlanMesImpactBar();
}

function handlePlanMesPlannedChange(input) {
  const month = planMesSelectedMonth();
  if (!month || isClosedMonthKey(month.key)) return;
  const rowKey = input.dataset.planMesPlanned;
  const monthKey = input.dataset.planMesMonth;
  if (!rowKey || !monthKey) return;
  if (planMesIsFinancingRowKey(rowKey)) return;
  const parsed = parseAmount(input.value);
  cuadroMandosStageCell(rowKey, monthKey, input.value === "" || parsed === null ? 0 : parsed);
  renderPlanMes();
}

function handlePlanMesCopy() {
  const month = planMesSelectedMonth();
  if (!month || isClosedMonthKey(month.key)) return;
  if (!planMesCopyCandidates(month).length) {
    announceStatus("No hay diferencias con el mes anterior que copiar.");
    return;
  }
  planMesCopyPending = true;
  renderPlanMes();
}

function handlePlanMesCopyConfirm() {
  const month = planMesSelectedMonth();
  if (!month || isClosedMonthKey(month.key)) return;
  const candidates = planMesCopyCandidates(month);
  candidates.forEach((candidate) => cuadroMandosStageCell(candidate.rowKey, candidate.monthKey, candidate.value));
  planMesCopyPending = false;
  const previous = planMesPreviousMonth(month);
  announceStatus(`${candidates.length} previsto(s) copiados de ${previous?.label || "el mes anterior"}. Revisa el pie de impacto antes de guardar.`);
  renderPlanMes();
}

function handlePlanMesCopyCancel() {
  planMesCopyPending = false;
  renderPlanMes();
}

// P-6: mismo componente `.e19-impact-bar` que ya usa Registrar (R-7) y el mismo cálculo de
// antes/después que ya usaba Cuadro de mandos (`cuadroMandosImpact`, sobre `cuadroMandosPlannedDrafts`
// — los mismos borradores que edita esta pestaña). Las cifras son las que de verdad se mueven al
// editar previsto (mínimo, meses bajo reserva, liquidez final y peor mes del horizonte) — no las
// cuatro de Registrar, que dependen de saldo y deuda, ajenos a un cambio de previsto.
function renderPlanMesImpactBar() {
  const bar = qs("planMesImpactBar");
  if (!bar) return;
  const impact = cuadroMandosImpact();
  if (!impact.drafts.length) {
    bar.hidden = true;
    bar.innerHTML = "";
    return;
  }
  bar.hidden = false;
  if (!impact.ok) {
    bar.innerHTML = `<div class="e19-registrar-impact-head"><p class="e19-eyebrow">Impacto del cambio</p><strong>No se ha podido calcular</strong><small>El motor no acepta esta combinación; los cambios siguen sin guardar.</small></div>
      <div class="e19-registrar-impact-actions"><button type="button" class="e19-btn e19-btn-secondary" data-plan-mes-impact-discard>Descartar todo</button></div>`;
    return;
  }
  const { before, after, drafts } = impact;
  const worstBefore = FinanceCanonicalCushion.worstMonthOf(openSimulationRows(impact.rowsBefore));
  const worstAfter = FinanceCanonicalCushion.worstMonthOf(openSimulationRows(impact.rowsAfter));
  const worstDelta = worstBefore && worstAfter ? round2(Number(worstAfter.value || 0) - Number(worstBefore.value || 0)) : null;
  const last = drafts.at(-1);
  bar.innerHTML = `
    <div class="e19-registrar-impact-head">
      <p class="e19-eyebrow">Impacto del cambio</p>
      <strong>${escapeHtml(last?.label || "Cambio")}${last?.monthLabel ? ` · ${escapeHtml(last.monthLabel)}` : ""}</strong>
      <small>${drafts.length} cambio(s) sin guardar</small>
    </div>
    <dl><dt>Mínimo de liquidez del horizonte</dt>${cuadroMandosBeforeAfter(before.minimo, after.minimo, (value) => money(value, true))}</dl>
    <dl><dt>Meses ${escapeHtml(cuadroMandosReserveLabel(after))}</dt>${cuadroMandosBeforeAfter(before.bajoReserva, after.bajoReserva, (value) => `${Math.round(Number(value || 0))}`, false)}</dl>
    <dl><dt>Liquidez al final del horizonte</dt>${cuadroMandosBeforeAfter(before.final, after.final, (value) => money(value, true))}</dl>
    <dl><dt>Peor mes del horizonte</dt><dd>${worstAfter ? `${escapeHtml(escenarioMotorMonthLabel(worstAfter.key))} · ${money(worstAfter.value, true)}` : "—"}${worstDelta ? ` <span class="${worstDelta > 0 ? "is-up" : "is-down"}">${worstDelta > 0 ? "+" : ""}${money(worstDelta, true)}</span>` : ""}</dd></dl>
    <div class="e19-registrar-impact-actions">
      <button type="button" class="e19-btn e19-btn-secondary" data-plan-mes-impact-discard>Descartar todo</button>
      <button type="button" class="e19-btn e19-btn-primary" data-plan-mes-impact-save>Guardar cambios</button>
    </div>`;
}

/* -------------------------------------------------------------------------------------------- */
/* P-8/P-9 · Plan › pestaña Previsión — matriz bloque × mes, de solo lectura                      */
/*                                                                                                */
/* Backlog_Global.pdf (V4, 14 de agosto de 2026) especifica P-8 así: "Una fila por bloque y una   */
/* columna por mes del horizonte. Los meses cerrados se distinguen visualmente y llevan candado." */
/* No es el titular/selector de horizonte/banda/tabla de 5 columnas/panel día a día que se        */
/* construyó antes a partir del mockup 2c en `#prevision` — ese screen cumple su propio mockup y  */
/* se queda tal cual («envolver, no sustituir»). El destino real de P-8 es esta pestaña, hasta     */
/* ahora un enlace de vuelta a `#prevision`.                                                      */
/*                                                                                                */
/* Los bloques son los mismos que ya agrupa Cuadro de mandos (`cuadroMandosSections`), más una     */
/* fila sintética de Ahorro — no hay partidas de "ahorro" en `monthlyPlanning`, así que se lee de  */
/* `row.saving` del motor, igual que ya hace `previsionMetric` — y el Resultado del mes. Los       */
/* importes son el previsto **guardado**, no los borradores de sesión de Cuadro de mandos: esta    */
/* pestaña es de solo lectura y su previsto se edita en Mes (P-3), no aquí; mezclar borradores      */
/* obligaría a recalcular la simulación completa en cada tecla sin que esta vista pueda guardarlos.*/
/*                                                                                                 */
/* P-9 añade la fila final de colchón con `cushionLevel` (escala de tres niveles, compartida con   */
/* A-2 de Análisis cuando se construya — ver canonical-cushion.js) y marca el peor mes también en  */
/* la fila de Resultado, tal como pide su criterio.                                                */
/* --------------------------------------------------------------------------------------------- */

const PLAN_PREVISION_HORIZONS = {
  "12m": { label: "12 meses", months: 12 },
  "24m": { label: "24 meses", months: 24 },
  "48m": { label: "48 meses", months: 48 },
  full: { label: "Horizonte completo", months: Infinity },
};
let planPrevisionHorizonKey = "12m";

function planPrevisionMonths(horizonKey = planPrevisionHorizonKey) {
  const all = cuadroMandosAllMonths();
  const config = PLAN_PREVISION_HORIZONS[horizonKey] || PLAN_PREVISION_HORIZONS["12m"];
  return Number.isFinite(config.months) ? all.slice(0, config.months) : all;
}

function planPrevisionSimulationByMonth(months) {
  const byKey = new Map(lastSimulation.map((row) => [row.detailMonthKey, row]));
  return months.map((month) => byKey.get(month.key) || null);
}

function planPrevisionSectionTotal(section, month) {
  return section.rows.reduce(
    (sum, row) => (cuadroMandosRowExists(row, month) ? sum + Number(plannedValueForVisualRow(row, month) || 0) : sum),
    0,
  );
}

function planPrevisionResultByMonth(months, sections, savingByMonth) {
  return months.map((month, index) => {
    const net = sections.reduce((sum, section) => {
      const total = planPrevisionSectionTotal(section, month);
      return sum + (section.kind === "income" ? total : -total);
    }, 0);
    return round2(net - savingByMonth[index]);
  });
}

function planPrevisionRowHtml(label, values, months, options = {}) {
  const { emphasize = false, negativeClass = true, worstKey = "", cellHtml = null } = options;
  const cells = values
    .map((value, index) => {
      const month = months[index];
      const closed = isClosedMonthKey(month.key);
      const isWorst = Boolean(worstKey) && month.key === worstKey;
      const classes = [closed ? "cuadro-mandos-closed" : "", negativeClass && value < 0 ? "negative" : "", isWorst ? "plan-prevision-worst" : ""]
        .filter(Boolean)
        .join(" ");
      const content = cellHtml ? cellHtml(value, month) : money(value, true);
      return `<td class="${classes}">${emphasize ? `<strong>${content}</strong>` : content}</td>`;
    })
    .join("");
  return `<tr><td>${escapeHtml(label)}</td>${cells}</tr>`;
}

function planPrevisionHeaderHtml(months) {
  return `<thead><tr><th>Bloque</th>${months
    .map(
      (month) =>
        `<th class="${isClosedMonthKey(month.key) ? "cuadro-mandos-closed" : ""}">${escapeHtml(month.label)}${
          isClosedMonthKey(month.key)
            ? ' <span class="plan-prevision-lock" role="img" aria-label="Mes cerrado" title="Mes cerrado">🔒</span>'
            : ""
        }</th>`,
    )
    .join("")}</tr></thead>`;
}

function renderPlanPrevision() {
  const table = qs("planPrevisionTable");
  if (!table || !lastSimulation.length || !baseData?.monthlyPlanning?.months?.length) return;
  const months = planPrevisionMonths();
  if (!months.length) {
    table.innerHTML = "";
    return;
  }
  const sections = cuadroMandosSections(months);
  const simRows = planPrevisionSimulationByMonth(months);
  const savingByMonth = simRows.map((row) => Number(row?.saving || 0));
  const liquidityByMonth = simRows.map((row) => Number(row?.totalLiquidity ?? 0));
  const resultByMonth = planPrevisionResultByMonth(months, sections, savingByMonth);

  const floor = mapaCalorFloor(simRows.filter(Boolean));
  const worst = FinanceCanonicalCushion.worstMonthOf(
    months.map((month, index) => ({ key: month.key, totalLiquidity: liquidityByMonth[index] })),
    { monthKeyField: "key" },
  );
  const worstKey = worst?.key || "";

  const sectionRows = sections
    .map((section) => {
      const values = months.map((month) => round2(planPrevisionSectionTotal(section, month)));
      return planPrevisionRowHtml(section.name, values, months, { negativeClass: false });
    })
    .join("");

  const savingRow = planPrevisionRowHtml("Ahorro", savingByMonth, months, { negativeClass: false });
  const resultRow = planPrevisionRowHtml("Resultado del mes", resultByMonth, months, { emphasize: true, worstKey });
  const cushionRow = planPrevisionRowHtml("Colchón", liquidityByMonth, months, {
    emphasize: true,
    worstKey,
    cellHtml: (value) => {
      const level = FinanceCanonicalCushion.cushionLevel(value, floor.value);
      return `<span class="plan-prevision-cushion is-${level}">${money(value, true)}</span>`;
    },
  });

  table.innerHTML = `${planPrevisionHeaderHtml(months)}<tbody>${sectionRows}${savingRow}${resultRow}${cushionRow}</tbody>`;

  const legend = qs("planPrevisionLegend");
  if (legend) {
    legend.textContent = `Colchón: liquidez al cierre de cada mes frente a ${floor.source}.${
      worstKey ? ` Peor mes: ${escenarioMotorMonthLabel(worstKey)}, marcado en Resultado y Colchón.` : ""
    }`;
  }
}

function handlePlanPrevisionHorizon(horizonKey) {
  if (!PLAN_PREVISION_HORIZONS[horizonKey] || horizonKey === planPrevisionHorizonKey) return;
  planPrevisionHorizonKey = horizonKey;
  document.querySelectorAll("[data-plan-prevision-horizon]").forEach((button) => {
    const active = button.dataset.planPrevisionHorizon === horizonKey;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  renderPlanPrevision();
}

// =================================================================================================
// Fase 6 · Análisis — pantalla 07 (Analisis.pdf, auditado el 16 de agosto): «la sección ejecutiva
// que faltaba». Primer incremento real: A-1 (pantalla de solo lectura, ninguna casilla editable),
// A-2 (banda de doce meses de colchón, la misma escala de tres niveles que P-9) y A-6 (selector de
// ventana). El resto del backlog (A-3 a A-13) se deja documentado como pendiente: varias dependen de
// Cierre/E-2/A-7, que este incremento no cubre.
//
// A-2 pide el colchón EN MESES, no la liquidez absoluta que ya colorea `#mapa-calor`/P-9 — esa serie
// mensual no existía todavía. Se calcula una sola vez, reutilizando piezas ya construidas: el gasto
// medio mensual con `escenarioMotorAverageCoreSpend` (mismo cálculo que el resumen de Escenarios),
// el objetivo con `state.emergencyBufferMonths` (el mismo «colchón objetivo» que ya usa Deuda y el
// estadillo de la barra lateral) y el color con `FinanceCanonicalCushion.cushionLevel`, la función de
// tres niveles que el propio comentario de P-9 ya señalaba como compartida con A-2 «cuando se
// construya». Ningún cálculo financiero nuevo: solo una serie mensual que faltaba montar.
// =================================================================================================

const ANALISIS_WINDOWS = {
  "12m": { label: "12 meses", months: 12 },
  "24m": { label: "24 meses", months: 24 },
  full: { label: "Todo el plan", months: Infinity },
};
let analisisWindowKey = "12m";

function analisisWindowMonths(windowKey = analisisWindowKey) {
  const all = cuadroMandosAllMonths();
  // Une cada mes visible con su fila de la simulación activa (lastSimulation) para que las
  // lecturas de Análisis lean ingreso, gasto, ahorro y liquidez reales, no solo el planning.
  const simByKey = new Map(lastSimulation.map((row) => [row.detailMonthKey, row]));
  const merged = all.map((month) => {
    const row = simByKey.get(month.key);
    return row ? { ...month, ...row } : month;
  });
  const config = ANALISIS_WINDOWS[windowKey] || ANALISIS_WINDOWS["12m"];
  return Number.isFinite(config.months) ? merged.slice(0, config.months) : merged;
}

// A-2: una fila por mes con el colchón en meses (liquidez ÷ gasto medio), nunca «cuadra por
// definición» — si no hay gasto medio con el que dividir, el mes queda sin dato (`monthsValue:
// null`), no en cero (regla transversal 04).
function analisisCushionBand(months, simRows, targetMonths) {
  const avgCoreSpend = escenarioMotorAverageCoreSpend(simRows);
  const byKey = new Map(simRows.map((row) => [row.detailMonthKey, row]));
  return months.map((month) => {
    const row = byKey.get(month.key);
    const liquidity = row ? Number(row.totalLiquidity ?? 0) : null;
    const monthsValue = liquidity === null || avgCoreSpend <= 0 ? null : round2(liquidity / avgCoreSpend);
    const level = monthsValue === null ? "sin-dato" : FinanceCanonicalCushion.cushionLevel(monthsValue, targetMonths);
    return { key: month.key, label: month.label, monthsValue, level, closed: isClosedMonthKey(month.key) };
  });
}

function analisisCushionWorst(band) {
  const withData = band.filter((item) => item.monthsValue !== null);
  if (!withData.length) return null;
  return withData.reduce((worst, item) => (item.monthsValue < worst.monthsValue ? item : worst));
}

const ANALISIS_CUSHION_LEVEL_LABELS = {
  negativo: "Bajo el mínimo",
  ajustado: "A vigilar",
  holgado: "Sobre objetivo",
  "sin-dato": "Sin dato",
};

function analisisCushionBandHtml(band, worstKey) {
  const values = band.map((item) => item.monthsValue).filter((value) => value !== null);
  const maxValue = Math.max(1, ...values);
  return band
    .map((item) => {
      const heightPct = item.monthsValue === null ? 4 : Math.max(6, Math.round((Math.max(0, item.monthsValue) / maxValue) * 100));
      const isWorst = Boolean(worstKey) && item.key === worstKey;
      return `<div class="analisis-cushion-col${isWorst ? " is-worst" : ""}">
        <span class="analisis-cushion-value">${item.monthsValue === null ? "—" : item.monthsValue.toFixed(1)}</span>
        <span class="analisis-cushion-bar is-${item.level}" style="height:${heightPct}%" title="${escapeHtml(ANALISIS_CUSHION_LEVEL_LABELS[item.level])}"></span>
        <small>${escapeHtml(item.label)}</small>
      </div>`;
    })
    .join("");
}

function renderAnalisis() {
  const band = qs("analisisCushionBand");
  if (!band || !lastSimulation.length) return;

  document.querySelectorAll("[data-analisis-window]").forEach((button) => {
    const active = button.dataset.analisisWindow === analisisWindowKey;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });

  const months = analisisWindowMonths();
  const targetMonths = Number(state.emergencyBufferMonths || 0);
  const cushion = analisisCushionBand(months, lastSimulation, targetMonths);
  const worst = analisisCushionWorst(cushion);

  band.innerHTML = analisisCushionBandHtml(cushion, worst?.key || "");

  const legend = qs("analisisCushionLegend");
  if (legend) {
    legend.textContent = `Meses de gasto que cubre la liquidez, mes a mes · objetivo ${targetMonths} mes(es). Se calcula sobre lo simulado, con la fecha de cálculo de hoy.`;
  }

  const worstNote = qs("analisisCushionWorst");
  if (worstNote) {
    worstNote.innerHTML = worst
      ? `<span class="e19-badge e19-badge-danger">Peor mes · ${escapeHtml(worst.label)}</span> ${worst.monthsValue.toFixed(1)} meses de colchón.`
      : `<span class="e19-kpi-note">Sin datos suficientes para calcular el peor mes en esta ventana.</span>`;
  }

  // C-11: Análisis es uno de los dependientes que el criterio de reapertura nombra explícitamente
  // — se avisa mientras alguno de los meses visibles esté reabierto (sin volver a cerrarse todavía).
  const reopenNotice = qs("analisisReopenNotice");
  if (reopenNotice) {
    const reopenedMonths = cierreMonthsCurrentlyReopened();
    const affected = months.filter((month) => reopenedMonths.has(month.key));
    if (affected.length) {
      reopenNotice.hidden = false;
      reopenNotice.textContent = `${affected.map((month) => month.label).join(", ")} se reabrió en Cierre y todavía no se ha vuelto a firmar: estas cifras pueden no reflejar la versión definitiva de ese mes.`;
    } else {
      reopenNotice.hidden = true;
      reopenNotice.textContent = "";
    }
  }

  // A-4: Cascada del resultado por periodo
  const resultGrid = qs("analisisResultGrid");
  if (resultGrid) resultGrid.innerHTML = analisisResultGrid(months);

  // A-5: Patrimonio neto proyectado
  renderAnalisisNetWorthChart(months);

  // A-8: En qué se va · reparto completo del ingreso
  const incomeGrid = qs("analisisIncomeGrid");
  if (incomeGrid) incomeGrid.innerHTML = analisisIncomeGrid(months);

  // A-9: Qué se repite
  const patternsList = qs("analisisPatternsList");
  if (patternsList) patternsList.innerHTML = analisisPatternsList(months);
}

function handleAnalisisWindow(windowKey) {
  if (!ANALISIS_WINDOWS[windowKey] || windowKey === analisisWindowKey) return;
  analisisWindowKey = windowKey;
  renderAnalisis();
}

// A-4: Cascada del resultado por periodo — reutiliza el mismo cálculo que la tabla ejecutiva de
// #cashflow (summarizeCashflowYear), solo cambia el destino. Ninguna cifra nueva: misma simulación.
function analisisResultGrid(months) {
  // Filtra solo los meses con datos de simulación (income finito)
  const validMonths = months.filter((month) => Number.isFinite(month.income));
  const groups = [];
  validMonths.forEach((month) => {
    const year = String(month.key || "").slice(0, 4) || "Sin año";
    let group = groups.find((item) => item.year === year);
    if (!group) {
      group = { year, items: [] };
      groups.push(group);
    }
    group.items.push({ row: month });
  });
  return groups
    .map((group) => {
      const summary = summarizeCashflowYear({ items: group.items.map((item) => ({ row: item.row, base: item.row })) });
      const savingRate = summary.income ? ((summary.saving / summary.income) * 100).toFixed(0) : "0";
      return `<article>
        <span>${escapeHtml(group.year)}</span>
        <strong>${money(summary.income, true)}</strong>
        <p>Ingresos. Gasto ${money(summary.outflow, true)} (${money(summary.coreSpend, true)} fijo + ${money(summary.debtAndCar, true)} deuda/coche), ahorro ${money(summary.saving, true)} (${savingRate}%).</p>
      </article>`;
    })
    .join("");
}

// A-5: Patrimonio neto proyectado — mismo gráfico de liquidez total que #forecast (renderBalanceChart),
// adaptado a los meses de la ventana de Análisis. No recalcula: lee lastSimulation.
function renderAnalisisNetWorthChart(months) {
  const svg = qs("analisisNetWorthChart");
  // Filtra solo los meses con datos de simulación (totalLiquidity no nulo)
  const validMonths = months.filter((month) => Number.isFinite(month.totalLiquidity));
  if (!svg || !validMonths.length) return;
  const width = svg.clientWidth || 900;
  const height = 320;
  const pad = { left: 62, right: 24, top: 24, bottom: 42 };
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
  svg.innerHTML = "";
  const values = validMonths.flatMap((month) => [month.totalLiquidity, month.checking, month.savings]);
  const min = Math.min(0, ...values);
  const max = Math.max(...values) * 1.04;
  const x = (i) => pad.left + (i / (validMonths.length - 1 || 1)) * (width - pad.left - pad.right);
  const y = (value) => height - pad.bottom - ((value - min) / (max - min || 1)) * (height - pad.top - pad.bottom);

  for (let i = 0; i <= 4; i += 1) {
    const value = min + ((max - min) * i) / 4;
    const yy = y(value);
    svg.insertAdjacentHTML("beforeend", `<line class="tick" x1="${pad.left}" x2="${width - pad.right}" y1="${yy}" y2="${yy}" />
      <text class="chart-label" x="8" y="${yy + 4}">${money(value)}</text>`);
  }

  const series = [
    { key: "totalLiquidity", color: "#6657d2", label: "Patrimonio neto" },
    { key: "checking", color: "#2c6be0", label: "Cuenta" },
    { key: "savings", color: "#267f4e", label: "Ahorro" },
  ];
  series.forEach((serie) => {
    const path = validMonths
      .map((month, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(2)} ${y(month[serie.key]).toFixed(2)}`)
      .join(" ");
    svg.insertAdjacentHTML("beforeend", `<path d="${path}" fill="none" stroke="${serie.color}" stroke-width="3" stroke-linecap="round" />`);
  });

  validMonths.forEach((month, idx) => {
    if (idx % Math.ceil(validMonths.length / 12) === 0 || idx === validMonths.length - 1) {
      svg.insertAdjacentHTML("beforeend", `<text class="chart-label" x="${x(idx) - 14}" y="${height - 12}">${month.label || month.month}</text>`);
    }
  });
}

// A-8: En qué se va · reparto completo del ingreso — desglose de dónde sale y a dónde va el ingreso.
// Lee lastSimulation (la simulación activa), sin cálculo nuevo.
function analisisIncomeGrid(months) {
  // Filtra solo los meses con datos de simulación
  const validMonths = months.filter((month) => Number.isFinite(month.income));
  const totalIncome = validMonths.reduce((sum, month) => sum + month.income, 0);
  const totalCoreSpend = validMonths.reduce((sum, month) => sum + (month.coreSpend || 0), 0);
  const totalDebtCar = validMonths.reduce((sum, month) => sum + (month.car || 0) + (month.refi || 0), 0);
  const totalProjects = validMonths.reduce((sum, month) => sum + (month.projectOutflow || 0), 0);
  const totalSaving = validMonths.reduce((sum, month) => sum + (month.saving || 0), 0);
  const pct = (value) => (totalIncome ? ((value / totalIncome) * 100).toFixed(0) : "0");
  return [
    ["Ingreso total", totalIncome, `${validMonths.length} meses simulados.`],
    ["Gasto operativo", totalCoreSpend, `${pct(totalCoreSpend)}% del ingreso.`],
    ["Deuda y coche", totalDebtCar, `${pct(totalDebtCar)}% del ingreso.`],
    ["Proyectos", totalProjects, totalProjects ? `${pct(totalProjects)}% del ingreso.` : "Sin presión por proyectos."],
    ["Ahorro", totalSaving, `${pct(totalSaving)}% del ingreso.`],
  ]
    .map(([label, value, note]) => `<article>
      <span>${escapeHtml(label)}</span>
      <strong>${money(value, true)}</strong>
      <p>${escapeHtml(note)}</p>
    </article>`)
    .join("");
}

// A-9: Qué se repite — patrones que aparecen mes a mes en la simulación activa.
// Procedencia: misma serie que #movimientos (M-3 chips), leída de lastSimulation.
function analisisPatternsList(months) {
  if (!months.length) return '<p class="e19-kpi-note">Sin datos suficientes en esta ventana.</p>';
  const patterns = [
    { key: "coreSpend", label: "Gasto operativo recurrente", desc: "Se repite mes a mes con la inflación aplicada." },
    { key: "car", label: "Cuota de coche", desc: "Pago fijo mensual, sin variación." },
    { key: "refi", label: "Refinanciación", desc: "Cuota mensual de la operación de deuda." },
    { key: "saving", label: "Ahorro mensual", desc: "Parte del ingreso que queda como patrimonio." },
  ];
  return patterns
    .map((pattern) => {
      const values = months.map((month) => month[pattern.key]).filter((value) => Number.isFinite(value));
      const avg = values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : 0;
      const stable = values.length > 1 && Math.abs(Math.max(...values) - Math.min(...values)) < Math.abs(avg) * 0.01;
      return `<article class="analisis-pattern-card">
        <h4>${escapeHtml(pattern.label)}</h4>
        <p>Media ${money(avg, true)}/mes${stable ? " · estable" : ""}. ${escapeHtml(pattern.desc)}</p>
      </article>`;
    })
    .join("");
}

function analisisCsvContent(months) {
  const validMonths = months.filter((month) => Number.isFinite(month.income));
  const rows = [["Mes", "Ingreso", "Gasto operativo", "Deuda y coche", "Proyectos", "Ahorro", "Patrimonio neto"]];
  validMonths.forEach((month) => {
    rows.push([
      month.label || month.month,
      month.income.toFixed(2),
      (month.coreSpend || 0).toFixed(2),
      ((month.car || 0) + (month.refi || 0)).toFixed(2),
      (month.projectOutflow || 0).toFixed(2),
      (month.saving || 0).toFixed(2),
      month.totalLiquidity.toFixed(2),
    ]);
  });
  return rows.map((row) => row.join(",")).join("\n");
}

function handleAnalisisExport(kind) {
  const months = analisisWindowMonths();
  if (!months.length) return;
  if (kind === "csv") {
    const content = analisisCsvContent(months);
    const blob = new Blob([content], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `analisis-${analisisWindowKey}-${isoLocalDate(new Date())}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  } else if (kind === "pdf") {
    window.print();
  }
}


